// KANBAN - tokens estilo Trello. Colunas estreitas e altas, fundo levemente
// cinza, cards brancos compactos com sombra fininha. O objetivo é densidade: o
// quadro rola horizontal e cabe muita coisa na tela sem parecer "gordo".
// Reutilizados por todos os Kanbans (Terceiros, Obras, Funil, Jornada) para
// que fiquem visualmente idênticos.
export const KB = {
  larguraCol: 272,          // largura da coluna (Trello usa ~272px)
  gapCols:    8,            // espaço entre colunas
  gapCards:   6,            // espaço entre cards
  raioCol:    8,
  raioCard:   6,
  padCol:     "6px 6px 8px",
  padCard:    "7px 9px",
  scroll: {                 // container do quadro
    display:"flex", gap:8, overflowX:"auto", overflowY:"hidden",
    paddingBottom:10, alignItems:"flex-start",
    WebkitOverflowScrolling:"touch", scrollSnapType:"x proximity",
  },
  coluna: (cor, ativa) => ({
    width:272, minWidth:272, maxWidth:272, scrollSnapAlign:"start",
    background: ativa ? `${cor}0e` : "#F0EDE7",
    border:`1px solid ${ativa ? cor : "#E2DCD2"}`,
    borderRadius:8, display:"flex", flexDirection:"column",
    maxHeight:"calc(100vh - 220px)",
    transition:"background .15s, border-color .15s",
  }),
  colHead: (cor) => ({
    display:"flex", justifyContent:"space-between", alignItems:"center", gap:6,
    padding:"8px 10px", borderTop:`3px solid ${cor}`,
    borderTopLeftRadius:8, borderTopRightRadius:8,
    position:"sticky", top:0, zIndex:1, background:"inherit",
  }),
  colBody: {
    padding:"0 6px 6px", display:"flex", flexDirection:"column", gap:6,
    overflowY:"auto", flex:1,
  },
  card: (destaque) => ({
    background:"#fff",
    border:`1px solid ${destaque || "#E2DCD2"}`,
    borderRadius:6, padding:"7px 9px", cursor:"pointer",
    boxShadow:"0 1px 2px rgba(18,18,18,.08)",
    display:"flex", flexDirection:"column", gap:4,
  }),
  contador: {
    fontSize:"var(--arcd-type-label)", fontWeight:600, color:C.muted,
    background:"#fff", borderRadius:99, padding:"1px 8px", minWidth:22, textAlign:"center",
  },
};

const G = `
@keyframes chatMentionPulse{0%,100%{box-shadow:0 6px 18px rgba(0,0,0,.28)}50%{box-shadow:0 0 0 8px rgba(212,175,55,.28),0 6px 18px rgba(0,0,0,.28)}}
@keyframes chatMessageFlash{0%,100%{outline-color:transparent}35%{outline-color:#D4AF37}}
.chat-mention-pulse{animation:chatMentionPulse 1.4s ease-in-out infinite}
.chat-msg-flash{outline:3px solid transparent;animation:chatMessageFlash 1.2s ease-in-out 2}
:root{
  --bg:${C.bg};--surface:${C.surface};--card:${C.card};
  --gold:${C.yellow};--text:${C.text};--muted:${C.muted};
  --green:${C.green};--red:${C.red};--blue:${C.blue};
  --grafite:#121212;--areia:#F5F3EE;--cinza:#BFBFBF;
  --type-display:'Nimbus Sans','Helvetica Neue',Arial,sans-serif;
  --type-body:'Nimbus Sans','Helvetica Neue',Arial,sans-serif;
  --type-data:'IBM Plex Mono',ui-monospace,monospace;
  --fs-caption:var(--arcd-type-caption);--fs-label:var(--arcd-type-label);--fs-body:var(--arcd-type-body);--fs-title:var(--arcd-type-section-title);
  --fs-page-title:var(--arcd-type-page-title);
  --fs-section-title:var(--arcd-type-section-title);
  --fs-card-title:var(--arcd-type-card-title);
  --radius-control:8px;--radius-card:8px;
}
*{box-sizing:border-box;margin:0;padding:0}
html,body,#root{width:100%;min-width:0;max-width:100%;min-height:100%}
body{min-width:320px}

/*  LAYOUT FLUIDO
   O elemento que exceder deve ser corrigido ou receber rolagem local. A raiz
   não mascara estouros com overflow hidden. */

/* Em CSS Grid e Flex, um filho tem min-width:auto por padrão: ele se
   RECUSA a encolher abaixo da largura da palavra mais longa que contém.
   Era isso que empurrava o "38%" do painel para fora do celular - a coluna
   do título não cedia espaço. min-width:0 devolve o controle ao layout. */
.fluid-grid > *{min-width:0}

/* Palavra longa (e-mail, nome de obra, descrição SINAPI) não rasga o card */
.brk{overflow-wrap:anywhere;word-break:break-word}

/* Escala tipográfica fluida: cresce com a tela, sem saltos e sem estourar.
   clamp(mínimo, ideal, máximo) - o meio usa vw, então acompanha a largura. */
.t-hero{font-size:clamp(18px,3.2vw,25px);line-height:1.08;letter-spacing:-.2px}
.t-kpi {font-size:clamp(19px,4vw,28px);line-height:1;letter-spacing:-.45px}
.t-lead{font-size:clamp(10px,2vw,12px)}

/* Tabelas largas (orçamento, DRE) rolam sozinhas em vez de rasgar a página */
.scroll-x{overflow-x:auto;-webkit-overflow-scrolling:touch;max-width:100%}
body{
  background:${C.bg};
  color:${C.text};
  font-family:var(--type-body);
  -webkit-tap-highlight-color:transparent;
  font-size:var(--arcd-type-body);
  line-height:1.5;
  letter-spacing:.16px;
}
/* Escala comum para todas as telas. Os módulos antigos possuem muitos
   tamanhos inline; estes tetos impedem títulos gigantes e preservam a
   hierarquia sem apagar KPIs e números de operação. */
main h1{font-family:var(--type-display)!important;font-size:var(--fs-page-title)!important;font-weight:600!important;line-height:1.12!important;letter-spacing:-.55px!important}
main h2:not(.page-hero__title){font-family:var(--type-display)!important;font-size:var(--fs-section-title)!important;font-weight:600!important;line-height:1.18!important;letter-spacing:-.32px!important}
main h3:not(.arcd-dialog__title):not(.arcd-heading-page){font-family:var(--type-display)!important;font-size:var(--fs-card-title)!important;font-weight:600!important;line-height:1.24!important;letter-spacing:-.12px!important}
main table{font-size:var(--arcd-type-body);font-variant-numeric:tabular-nums}
main th{font-size:var(--arcd-type-label);font-weight:600;letter-spacing:.1px;text-transform:none;color:${C.muted}}
main input:not([type="checkbox"]):not([type="radio"]),main select,main textarea{font-size:var(--arcd-type-body)!important;line-height:1.5}
main textarea{min-height:76px}
main label>span:first-child{font-size:var(--arcd-type-label)!important;font-weight:500!important;letter-spacing:.1px!important}
main button{font-size:var(--arcd-type-label)}
/* Sem textura decorativa: ferramenta técnica tem fundo limpo. */
body>*{position:relative;z-index:1}
input,select,textarea,button{
  font-family:var(--type-body);
}
button:disabled{opacity:.4;cursor:not-allowed!important}
button{touch-action:manipulation;transition:background .12s ease,border-color .12s ease,color .12s ease}
button:not(:disabled):hover{filter:brightness(.98)}
button:not(:disabled):active{filter:brightness(.94)}
button:focus-visible{outline:2px solid ${C.yellow};outline-offset:2px}
.arcd-btn{
  min-height:40px;border-width:1px!important;border-radius:var(--radius-control)!important;
  font-size:var(--arcd-type-body)!important;font-weight:600!important;letter-spacing:.08px!important;
  text-transform:none!important;line-height:1.1;white-space:nowrap;
  box-shadow:none!important;
  transition:background .15s ease,border-color .15s ease,color .15s ease,transform .1s ease!important;
}
.arcd-btn[data-size="sm"]{min-height:36px;padding:6px 10px!important;font-size:var(--arcd-type-label)!important;border-radius:var(--radius-control)!important}
.arcd-btn[data-size="lg"]{min-height:42px;padding:9px 16px!important;font-size:var(--arcd-type-body)!important;border-radius:var(--radius-control)!important}
.arcd-btn svg{width:13px!important;height:13px!important;flex:0 0 13px}
.arcd-btn[data-size="sm"] svg{width:11px!important;height:11px!important;flex-basis:11px}
.arcd-btn[data-icon-only="true"]{width:36px;padding:0!important}
.arcd-btn[data-size="sm"][data-icon-only="true"]{width:30px}
.arcd-btn[data-size="lg"][data-icon-only="true"]{width:42px}
.arcd-btn:not(:disabled):hover{background:var(--btn-hover)!important;border-color:var(--btn-hover-border)!important;box-shadow:none!important;filter:none}
.arcd-btn:not(:disabled):active{transform:translateY(1px);filter:none}
.arcd-btn[aria-busy="true"]{cursor:progress}
.arcd-btn[aria-busy="true"] svg{animation:spin .8s linear infinite}
/* No celular o espaço clicável é maior que o ícone. Isso preserva a
   densidade visual da tabela, mas evita toques imprecisos em campo. */
@media(max-width:767px){
  .arcd-btn{min-height:var(--arcd-touch-target-min)!important}
  .arcd-btn[data-icon-only="true"]{width:var(--arcd-touch-target-min);min-width:var(--arcd-touch-target-min)}
  .arcd-tab{min-height:var(--arcd-touch-target-min)}
  button:not(.arcd-btn)[title="Editar"],button:not(.arcd-btn)[title="Excluir"],button:not(.arcd-btn)[title="Remover"],button:not(.arcd-btn)[title="Editar obra"],button:not(.arcd-btn)[title="Excluir obra"]{
    width:var(--arcd-touch-target-min)!important;height:var(--arcd-touch-target-min)!important;
    min-width:var(--arcd-touch-target-min)!important;min-height:var(--arcd-touch-target-min)!important;
  }
}
.arcd-tab{min-height:32px;padding:6px 10px!important;border:0!important;border-bottom:2px solid transparent!important;background:transparent!important;border-radius:0!important;color:${C.muted};font-size:var(--arcd-type-label)!important;font-weight:600!important;white-space:nowrap}
.arcd-tab[data-active="true"]{color:${C.text}!important;border-bottom-color:${C.yellow}!important;font-weight:600!important}
.arcd-tab:hover{color:${C.text};filter:none!important}
.arcd-pill{min-height:23px;padding:3px 7px!important;border-radius:99px!important;font-size:var(--arcd-type-caption)!important;font-weight:600!important;letter-spacing:.08px}
button:not(.arcd-btn)[title="Editar"],button:not(.arcd-btn)[title="Excluir"],button:not(.arcd-btn)[title="Remover"],button:not(.arcd-btn)[title="Editar obra"],button:not(.arcd-btn)[title="Excluir obra"]{
  width:28px!important;height:28px!important;min-width:28px!important;min-height:28px!important;
  padding:0!important;display:inline-grid!important;place-items:center!important;border-radius:var(--radius-control)!important;
  border:1px solid ${C.border}!important;background:${C.card}!important;box-shadow:none!important;
}
input:focus,select:focus,textarea:focus{
  outline:none;
  border-color:${C.yellow}!important;
  box-shadow:0 0 0 2px ${C.yellow}22;
}
/* Cards e elevação */
.lift-card{transition:background .15s ease,border-color .15s ease}
.lift-card:hover{border-color:${C.yellow}88;background:${C.card2}}
/* Elevação padrão para cards em fundo branco */
.card-base{
  background:${C.card};
  border:1px solid ${C.border};
  box-shadow:none;
  border-radius:4px;
}
/* Linha de acento ouro */
.brand-slice{position:relative;overflow:hidden}
.brand-slice:after{content:"";position:absolute;bottom:0;left:0;right:0;height:2px;background:${C.yellow}}
/* Animações */
@keyframes fadeIn   {from{opacity:0;transform:translateY(6px)}  to{opacity:1;transform:none}}
@keyframes fadeInUp {from{opacity:0;transform:translateY(20px)} to{opacity:1;transform:none}}
@keyframes spin     {to{transform:rotate(360deg)}}
@keyframes slideIn  {from{opacity:0;transform:translateX(-6px)} to{opacity:1;transform:none}}
@keyframes arcdTvScan{0%{top:8%;opacity:0}12%{opacity:.55}88%{opacity:.25}100%{top:94%;opacity:0}}
@keyframes arcdTvPhotoIn{0%{opacity:0;transform:scale(1.045)}12%{opacity:.82}100%{opacity:.86;transform:scale(1)}}
.anim   {animation:fadeIn    .2s ease}
.animUp {animation:fadeInUp  .3s ease}
.animSl {animation:slideIn   .16s ease}
.arcd-tv-scan{animation:arcdTvScan 8s linear infinite;pointer-events:none}
.arcd-tv-photo{animation:arcdTvPhotoIn 7.8s ease-out both;will-change:opacity,transform}
.arcd-tv:fullscreen{width:100vw;height:100vh;border-radius:0!important}
.no-scroll{overflow:hidden}
@media (prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}

/*
   NAVEGAÇÃO LATERAL

   O trilho: obra se mede com prumo, e a barra segue essa lógica. Cada grupo
   aberto tem um fio vertical na sua cor; a aba ativa é o marcador que assenta
   nele. É a única coisa ousada aqui - o resto fica quieto de propósito.

   Cada grupo injeta suas cores como variáveis (--gc, --gc-hov, --gc-act),
   porque estilo inline não faz :hover.
    */

/* Cabeçalho do grupo - clicável */
.nav-grp-hd{
  width:100%; display:flex; align-items:center; gap:7px;
  padding:6px 8px; margin-bottom:1px;
  background:transparent; border:0; border-radius:${C.rSm}px;
  cursor:pointer; text-align:left;
  color:${C.muted};
  font-family:var(--type-body);
  font-size:var(--arcd-type-caption); font-weight:600; letter-spacing:.6px; text-transform:uppercase;
  transition:background .12s ease, color .12s ease;
}
.nav-grp-hd:hover{ background:var(--gc-hov); color:var(--gc); }
.nav-grp-hd[data-open="true"]{ color:var(--gc); }
.nav-grp-hd:focus-visible{ outline:2px solid ${C.yellow}; outline-offset:1px; }

/* Seta */
.nav-chev{
  margin-left:auto; flex-shrink:0;
  transition:transform .18s ease;
  font-size:var(--arcd-type-caption); line-height:1; opacity:.55;
}
.nav-grp-hd[data-open="true"] .nav-chev{ transform:rotate(90deg); opacity:1; }

/* Quantas abas há num grupo fechado - para não esconder o que existe */
.nav-count{
  margin-left:auto; flex-shrink:0;
  font-size:var(--arcd-type-caption); font-weight:600; letter-spacing:0;
  color:${C.muted}; opacity:.6;
}

/* Corpo do grupo: o trilho vive aqui */
.nav-body{
  overflow:hidden;
  margin-left:14px;
  border-left:1px solid var(--gc-rail);
  padding-left:0;
  animation:navOpen .18s ease;
}
@keyframes navOpen{
  from{ opacity:0; transform:translateY(-3px) }
  to  { opacity:1; transform:none }
}

/* Aba */
.nav-item{
  position:relative;
  width:100%; display:flex; align-items:center; gap:8px;
  padding:6px 10px 6px 12px; margin-bottom:0;
  background:transparent; border:0; border-radius:0 ${C.rSm}px ${C.rSm}px 0;
  cursor:pointer; text-align:left;
  color:${C.muted};
  font-family:var(--type-body);
  font-size:12px; font-weight:500;
  transition:background .12s ease, color .12s ease;
  --ic-color:${C.muted};
}

/* O marcador que assenta no trilho */
.nav-item::before{
  content:""; position:absolute; left:-1.5px; top:50%;
  transform:translateY(-50%);
  width:2.5px; height:0; border-radius:0 2px 2px 0;
  background:var(--gc);
  transition:height .16s ease, opacity .16s ease;
  opacity:0;
}

.nav-item:hover{
  background:var(--gc-hov);
  color:${C.subtle};
  --ic-color:var(--gc);
}
.nav-item:hover::before{ height:13px; opacity:.45; }

.nav-item[data-active="true"]{
  background:var(--gc-act);
  color:${C.text};
  font-weight:600;
  --ic-color:var(--gc);
}
.nav-item[data-active="true"]::before{ height:100%; opacity:1; }

.nav-item:focus-visible{
  outline:2px solid ${C.yellow};
  outline-offset:-2px;
}

/* Pendência */
.nav-dot{
  margin-left:auto; flex-shrink:0;
  width:5px; height:5px; border-radius:50%;
  background:${C.red};
}

/* Quem prefere menos movimento não leva movimento nenhum */
@media (prefers-reduced-motion: reduce){
  .nav-grp-hd, .nav-chev, .nav-item, .nav-item::before{ transition:none }
  .nav-body{ animation:none }
}

/* ==============================================================
   ACORDEAO DO PAINEL DA OBRA
   Cada secao abre e fecha, como no app que o Hygor ja usa. No
   celular isso importa: uma tela cheia de blocos fixos obriga a
   rolar muito; o acordeao deixa aberto so o que interessa agora.
   ============================================================== */
.acc-sec{
  background:${C.card};
  border:1px solid ${C.border};
  border-radius:8px;
  overflow:hidden;
  margin-bottom:9px;
}
.acc-hd{
  width:100%; display:flex; align-items:center; gap:9px;
  padding:14px 15px;
  background:transparent; border:0; cursor:pointer; text-align:left;
  font-family:var(--type-display);
  transition:background .14s ease;
}
.acc-hd:hover{ background:${C.surface}; }
.acc-hd:focus-visible{ outline:2px solid ${C.yellow}; outline-offset:-2px; }
.acc-ic{ flex-shrink:0; --ic-color:var(--acc-color); }
.acc-title{
  flex:1; min-width:0;
  font-size:13.5px; font-weight:600; color:${C.text};
}
.acc-badge{
  flex-shrink:0; min-width:20px; height:20px; padding:0 6px;
  display:flex; align-items:center; justify-content:center;
  border-radius:6px; font-size:var(--arcd-type-caption); font-weight:600;
  background:var(--acc-color); color:#fff;
}
.acc-chev{
  flex-shrink:0; font-size:var(--arcd-type-caption); color:${C.muted};
  transition:transform .18s ease;
}
.acc-hd[data-open="true"] .acc-chev{ transform:rotate(180deg); }
.acc-body{
  padding:0 15px 14px;
  animation:accOpen .18s ease;
}
@keyframes accOpen{
  from{ opacity:0; transform:translateY(-4px) }
  to  { opacity:1; transform:none }
}
.acc-link{
  width:100%; margin-top:11px; padding:9px;
  background:transparent; border:1px solid ${C.border};
  border-radius:8px; cursor:pointer;
  color:${C.yellowD}; font-size:var(--arcd-type-caption); font-weight:600;
  font-family:var(--type-display);
  transition:background .14s ease, border-color .14s ease;
}
.acc-link:hover{ background:${C.yellow}0F; border-color:${C.yellow}; }

@media (prefers-reduced-motion: reduce){
  .acc-hd, .acc-chev{ transition:none }
  .acc-body{ animation:none }
}
/* Scrollbar */
::-webkit-scrollbar{width:4px;height:4px}
::-webkit-scrollbar-track{background:${C.surface}}
::-webkit-scrollbar-thumb{background:${C.cinza};border-radius:99px}
/* Print */
@media print{
  .no-print{display:none!important}
  body{background:#fff;color:#000;font-size:var(--arcd-type-caption)}
  body:before{display:none}
}
/* Hide sub-nav scrollbar */
div::-webkit-scrollbar{height:0;width:0}
/* Ponto da quinzena: controles e legenda (sem estas regras os filtros e a
   legenda caiam um sob o outro, sem espaçamento nem quebra responsiva). */
.ponto-geral-controls{background:${C.card};border:1px solid ${C.border};border-radius:${C.rLg}px;padding:12px 14px}
.ponto-geral-filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px 10px;align-items:end}
.ponto-geral-count{font-size:var(--arcd-type-caption);color:${C.muted};font-weight:600;margin-top:10px;padding-top:10px;border-top:1px solid ${C.line}}
.ponto-geral-legend{display:flex;align-items:center;gap:14px;flex-wrap:wrap;font-size:var(--arcd-type-caption);color:${C.muted};padding:9px 2px}
.ponto-legend-title{font-weight:600;color:${C.text}}
.ponto-legend-chip{display:inline-flex;align-items:center;gap:5px}
.ponto-legend-chip>i{width:8px;height:8px;border-radius:99px;display:block;flex-shrink:0}
.ponto-legend-help{margin-left:auto;font-style:italic}
@media(max-width:767px){
  .ponto-geral-filters{grid-template-columns:1fr 1fr}
  .ponto-legend-help{margin-left:0;width:100%}
}
`;


//
// Helpers gerais
//

export const uid = () => Math.random().toString(36).slice(2, 10) + Date.now().toString(36).slice(-4);
const pointOperationId=()=>crypto.randomUUID();

export const today = () => toLocalISODate(new Date());

export const fmt = n => Number(n || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });

// Consulta pública de CNPJ (BrasilAPI - gratuita, sem chave). Devolve os campos
// já normalizados para o app, ou lança erro com mensagem amigável. Não guarda
// nada; é só leitura da base pública da Receita.
const buscarCNPJ = async (cnpjBruto) => {
  const cnpj = soDigitos(cnpjBruto);
  if (cnpj.length !== 14) throw new Error("CNPJ deve ter 14 dígitos.");
  const resp = await consultarCNPJReceita(cnpj);
  if (!resp.ok) throw new Error(resp.error || "Não consegui consultar o CNPJ agora. Tente novamente.");
  const d = resp.data || {};
  const cidade = d.municipio || "";
  const uf = d.uf || "";
  const enderecoPartes = [d.descricao_tipo_de_logradouro, d.logradouro, d.numero].filter(Boolean).join(" ");
  const bairro = d.bairro ? `, ${d.bairro}` : "";
  const cidadeUf = [cidade, uf].filter(Boolean).join(" - ");
  // CNAEs: o principal e os secundarios. E daqui que da pra deduzir o ramo
  // de fornecimento sem o usuario marcar na mao.
  const cnaes = [
    { codigo: String(d.cnae_fiscal || ""), descricao: d.cnae_fiscal_descricao || "" },
    ...(Array.isArray(d.cnaes_secundarios) ? d.cnaes_secundarios.map(c => ({
      codigo: String(c.codigo || ""), descricao: c.descricao || "",
    })) : []),
  ].filter(c => c.codigo || c.descricao);

  return {
    razaoSocial: d.razao_social || "",
    nomeFantasia: d.nome_fantasia || "",
    // Nome de exibição: fantasia se houver, senão razão social.
    nome: d.nome_fantasia || d.razao_social || "",
    telefone: d.ddd_telefone_1 || "",
    email: d.email || "",
    cidade, uf, cidadeUf,
    endereco: [enderecoPartes + bairro, cidadeUf, d.cep ? `CEP ${d.cep}` : ""].filter(Boolean).join(", "),
    // Partes separadas do endereco, para preencher campo a campo.
    logradouro: [d.descricao_tipo_de_logradouro, d.logradouro].filter(Boolean).join(" ").trim(),
    numero: d.numero || "",
    complemento: d.complemento || "",
    bairro: d.bairro || "",
    cep: d.cep || "",
    situacao: d.descricao_situacao_cadastral || "",
    atividade: d.cnae_fiscal_descricao || "",
    cnaes,
    abertura: d.data_inicio_atividade || "",
  };
};
// Formato compacto para KPIs executivos: R$ 2,4 mi / R$ 850 mil. Mantém a leitura
// rápida sem encher o card de dígitos. Para valores pequenos, cai no fmt normal.
export const fmtCompact = n => {
  const v = Number(n || 0);
  const abs = Math.abs(v);
  const sinal = v < 0 ? "-" : "";
  if (abs >= 1e6) return `${sinal}R$ ${(abs/1e6).toFixed(abs>=1e7?0:1).replace(".",",")} mi`;
  if (abs >= 1e3) return `${sinal}R$ ${(abs/1e3).toFixed(0)} mil`;
  return fmt(v);
};

export const fmtDate = iso => {
  if (!iso || typeof iso !== "string" || !iso.includes("-")) return "-";
  const [, m, d] = iso.split("-");
  return `${d}/${m}`;
};

export const fmtDateFull = iso => {
  if (!iso || typeof iso !== "string" || !iso.includes("-")) return "-";
  const [y, m, d] = iso.split("-");
  return `${d}/${m}/${y}`;
};

export const monthName = m => ["Jan", "Fev", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Out", "Nov", "Dez"][m] || "";
export const MONTHS = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];
export const fullMonth = m => ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"][m] || "";
// Mes/ano curto a partir de uma data ISO: "ago/26". Usado na regua do Gantt.
export const fmtMesAno = iso => {
  if (!iso) return "";
  const meses = ["jan","fev","mar","abr","mai","jun","jul","ago","set","out","nov","dez"];
  const d = new Date(iso + "T00:00:00");
  return `${meses[d.getMonth()]}/${String(d.getFullYear()).slice(2)}`;
};

// Prazo da obra: dado contractStart/contractEnd, devolve % de tempo decorrido,
// dias restantes e um rotulo/cor. null se nao ha datas de contrato.
const prazoObra = (obra) => {
  const ini = obra?.contractStart, fim = obra?.contractEnd;
  if (!ini || !fim) return null;
  const hoje = today();
  const totalDias = diasCorridos(ini, fim);
  if (totalDias <= 0) return null;
  const decorridos = Math.max(0, Math.min(totalDias, diasCorridos(ini, hoje)));
  const pct = (decorridos / totalDias) * 100;
  // Diferenca ASSINADA em dias (negativa se o prazo ja passou). diasCorridos
  // trava em zero, entao calculamos direto aqui.
  const restam = Math.round((new Date(fim + "T00:00:00") - new Date(hoje + "T00:00:00")) / 86400000);
  let rotulo, cor;
  if (restam < 0)      { rotulo = `atrasada ${Math.abs(restam)}d`; cor = C.red; }
  else if (restam === 0) { rotulo = "vence hoje"; cor = C.orange; }
  else if (restam <= 15) { rotulo = `faltam ${restam}d`; cor = C.orange; }
  else                 { rotulo = `faltam ${restam}d`; cor = C.blue; }
  return { pct: Math.min(pct, 100), restam, totalDias, decorridos, rotulo, cor };
};

