const TIPO_EVENTO_EMPRESA={
  aniversario:{l:"Aniversário",c:C.purple}, reuniao:{l:"Reunião",c:C.blue},
  feriado:{l:"Feriado",c:C.orange}, outro:{l:"Outro",c:C.muted},
};

// Calendário compartilhado, visível para toda a empresa independente do
// papel do usuário (aniversários, reuniões gerais, feriados, avisos). Não usa
// o motor de comandos: é um cadastro leve, sem impacto financeiro ou de
// auditoria, salvo pelo caminho simples de seção (como leads/clientes).
function CalendarioEmpresa({data,update,showToast,currentUser}){
  const {isDesktop}=useBreakpoint();
  const [mesOffset,setMesOffset]=useState(0);
  const [diaSelecionado,setDiaSelecionado]=useState("");
  const [eventoForm,setEventoForm]=useState(null);
  const eventos=data.eventosEmpresa||[];

  const salvarEvento=async()=>{
    const f=eventoForm;
    if(!String(f.titulo||"").trim()){showToast("Informe o título do evento.","error");return;}
    if(!f.data){showToast("Informe a data do evento.","error");return;}
    const agora=new Date().toISOString();
    const registro={
      id:f.id||uid(),titulo:String(f.titulo).trim(),data:f.data,tipo:f.tipo||"outro",
      descricao:String(f.descricao||"").trim(),
      criadoPorId:f.criadoPorId||currentUser?.id||"",criadoPor:f.criadoPor||currentUser?.nome||"",
      criadoEm:f.criadoEm||agora,
    };
    const lista=f.id?eventos.map(e=>e.id===f.id?registro:e):[...eventos,registro];
    const result=await update({...data,eventosEmpresa:lista});
    if(result&&result.ok===false){showToast("Não foi possível salvar o evento.","error");return;}
    setEventoForm(null);
    showToast(f.id?"Evento atualizado.":"Evento cadastrado.");
  };

  const excluirEvento=async evento=>{
    if(!window.confirm(`Excluir o evento "${evento.titulo}"?`))return;
    const result=await update({...data,eventosEmpresa:eventos.filter(e=>e.id!==evento.id)});
    if(result&&result.ok===false){showToast("Não foi possível excluir o evento.","error");return;}
    showToast("Evento excluído.");
  };

  const calRef=new Date();calRef.setDate(1);calRef.setMonth(calRef.getMonth()+mesOffset);
  const ano=calRef.getFullYear(),mesIdx=calRef.getMonth();
  const diasNoMes=new Date(ano,mesIdx+1,0).getDate();
  const primeiroDiaSemana=new Date(ano,mesIdx,1).getDay();
  const eventosPorDia={};
  eventos.forEach(e=>{if(!e.data)return;(eventosPorDia[e.data]=eventosPorDia[e.data]||[]).push(e);});
  const celulas=[...Array(primeiroDiaSemana).fill(null),...Array.from({length:diasNoMes},(_,i)=>{
    const dia=`${ano}-${String(mesIdx+1).padStart(2,"0")}-${String(i+1).padStart(2,"0")}`;
    return {dia,numero:i+1,eventos:eventosPorDia[dia]||[]};
  })];
  const proximos=eventos.filter(e=>e.data>=today()).sort((a,b)=>a.data.localeCompare(b.data)).slice(0,8);

  return <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:C.rLg,boxShadow:"none",padding:18}}>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12,gap:8,flexWrap:"wrap"}}>
      <h3 style={TYPO.h3}>Calendário da empresa</h3>
      <Btn size="sm" onClick={()=>setEventoForm({id:"",titulo:"",data:diaSelecionado||today(),tipo:"outro",descricao:""})}><Ic n="plus"/> Novo evento</Btn>
    </div>
    <div style={{display:"grid",gridTemplateColumns:isDesktop?"minmax(0,1fr) 220px":"1fr",gap:16}}>
      <div>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
          <button onClick={()=>setMesOffset(m=>m-1)} style={{background:"transparent",border:0,cursor:"pointer",color:C.muted,fontSize:"var(--arcd-type-control)",padding:"2px 10px"}}>‹</button>
          <b style={{fontSize:"var(--arcd-type-body)",color:C.text,textTransform:"capitalize"}}>{calRef.toLocaleDateString("pt-BR",{month:"long",year:"numeric"})}</b>
          <button onClick={()=>setMesOffset(m=>m+1)} style={{background:"transparent",border:0,cursor:"pointer",color:C.muted,fontSize:"var(--arcd-type-control)",padding:"2px 10px"}}>›</button>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:3,marginBottom:4}}>
          {["D","S","T","Q","Q","S","S"].map((d,i)=><span key={i} style={{textAlign:"center",fontSize:"var(--arcd-type-caption)",fontWeight:600,color:C.muted}}>{d}</span>)}
        </div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:3}}>
          {celulas.map((c,i)=>c?(
            <button key={c.dia} onClick={()=>setDiaSelecionado(v=>v===c.dia?"":c.dia)}
              style={{minHeight:52,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"flex-start",gap:3,padding:"4px 2px",
                border:`1px solid ${diaSelecionado===c.dia?C.blue:C.border}`,borderRadius:6,
                background:diaSelecionado===c.dia?`${C.blue}14`:c.dia===today()?`${C.yellowD}10`:"transparent",cursor:"pointer"}}>
              <span style={{fontSize:"var(--arcd-type-label)",fontWeight:diaSelecionado===c.dia?600:600,color:diaSelecionado===c.dia?C.blue:C.text}}>{c.numero}</span>
              <div style={{display:"flex",gap:2,flexWrap:"wrap",justifyContent:"center"}}>
                {c.eventos.slice(0,3).map(e=><span key={e.id} title={e.titulo} style={{width:5,height:5,borderRadius:99,background:(TIPO_EVENTO_EMPRESA[e.tipo]||TIPO_EVENTO_EMPRESA.outro).c}}/>)}
              </div>
            </button>
          ):<div key={`vazio-${i}`}/>)}
        </div>
        {diaSelecionado&&<div style={{marginTop:10,display:"flex",flexDirection:"column",gap:6}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
            <p style={{fontSize:"var(--arcd-type-label)",fontWeight:600,color:C.text}}>{fmtDate(diaSelecionado)}</p>
            <button onClick={()=>setDiaSelecionado("")} style={{background:"transparent",border:0,color:C.blue,fontSize:"var(--arcd-type-control)",fontWeight:600,cursor:"pointer"}}>Fechar</button>
          </div>
          {(eventosPorDia[diaSelecionado]||[]).map(e=><div key={e.id} style={{display:"flex",justifyContent:"space-between",gap:8,alignItems:"center",background:C.surface,border:`1px solid ${C.border}`,borderRadius:6,padding:"7px 9px"}}>
            <div style={{minWidth:0}}>
              <p style={{fontSize:"var(--arcd-type-label)",fontWeight:600,color:C.text}}>{e.titulo}</p>
              <p style={{fontSize:"var(--arcd-type-caption)",color:C.muted,marginTop:1}}>{(TIPO_EVENTO_EMPRESA[e.tipo]||TIPO_EVENTO_EMPRESA.outro).l}{e.descricao?` · ${e.descricao}`:""}</p>
            </div>
            <div style={{display:"flex",gap:4,flexShrink:0}}>
              <button onClick={()=>setEventoForm({...e})} style={{background:"transparent",border:0,color:C.blue,fontSize:"var(--arcd-type-control)",fontWeight:600,cursor:"pointer"}}>Editar</button>
              <button onClick={()=>excluirEvento(e)} style={{background:"transparent",border:0,color:C.red,fontSize:"var(--arcd-type-control)",fontWeight:600,cursor:"pointer"}}>Excluir</button>
            </div>
          </div>)}
          {!(eventosPorDia[diaSelecionado]||[]).length&&<p style={{fontSize:"var(--arcd-type-label)",color:C.muted}}>Nenhum evento neste dia.</p>}
        </div>}
      </div>
      <div>
        <p style={{fontSize:"var(--arcd-type-caption)",fontWeight:500,color:C.muted,marginBottom:8}}>Próximos eventos</p>
        <div style={{display:"flex",flexDirection:"column",gap:6}}>
          {proximos.map(e=><div key={e.id} style={{display:"flex",gap:7,alignItems:"flex-start"}}>
            <span style={{width:6,height:6,borderRadius:99,background:(TIPO_EVENTO_EMPRESA[e.tipo]||TIPO_EVENTO_EMPRESA.outro).c,marginTop:4,flexShrink:0}}/>
            <div style={{minWidth:0}}>
              <p style={{fontSize:"var(--arcd-type-label)",fontWeight:600,color:C.text,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{e.titulo}</p>
              <p style={{fontSize:"var(--arcd-type-caption)",color:C.muted}}>{fmtDate(e.data)}</p>
            </div>
          </div>)}
          {!proximos.length&&<p style={{fontSize:"var(--arcd-type-label)",color:C.muted}}>Nenhum evento futuro.</p>}
        </div>
      </div>
    </div>
    {eventoForm&&<Modal title={eventoForm.id?"Editar evento":"Novo evento"} onClose={()=>setEventoForm(null)}>
      <div style={{display:"flex",flexDirection:"column",gap:9}}>
        <Inp label="Título *" value={eventoForm.titulo} onChange={v=>setEventoForm(f=>({...f,titulo:v}))}/>
        <Inp label="Data *" type="date" value={eventoForm.data} onChange={v=>setEventoForm(f=>({...f,data:v}))}/>
        <Sel label="Tipo" value={eventoForm.tipo} onChange={v=>setEventoForm(f=>({...f,tipo:v}))} options={Object.entries(TIPO_EVENTO_EMPRESA).map(([v,o])=>({v,l:o.l}))}/>
        <Inp label="Descrição" value={eventoForm.descricao} onChange={v=>setEventoForm(f=>({...f,descricao:v}))}/>
        <div style={{display:"flex",gap:8}}>
          <Btn v="ghost" full onClick={()=>setEventoForm(null)}>Cancelar</Btn>
          <Btn full onClick={salvarEvento}><Ic n="check"/> Salvar</Btn>
        </div>
      </div>
    </Modal>}
  </div>;
}

const construirFilaOperador=(data,currentUser)=>{
  const role=currentUser?.role||"visualizador",userId=currentUser?.id||"",hoje=today();
  const acessos=new Set(allowedTabsForUser(currentUser));
  const obrasAtivas=(data.obras||[]).filter(o=>o.status!=="done");
  const minhasObras=role==="admin"?obrasAtivas:obrasAtivas.filter(o=>
    !currentUser?.obraId||o.id===currentUser.obraId).filter(o=>role!=="engenheiro"||
    o.engineerId===userId||o.engineer===currentUser?.nome||currentUser?.obraId===o.id);
  const escopoEngenharia=minhasObras.length?minhasObras:(["engenheiro","engenheiro_auditor"].includes(role)?obrasAtivas.filter(o=>!currentUser?.obraId||o.id===currentUser.obraId):obrasAtivas);
  const idsObras=new Set(escopoEngenharia.map(o=>o.id));
  const fila=[];
  const incluir=(id,setor,titulo,detalhe,quantidade,severidade,tab,icon,color)=>{
    if(!quantidade||!acessos.has(tab))return;
    fila.push({id,setor,titulo,detalhe,quantidade,severidade,tab,icon,color});
  };

  if(role==="admin"||["engenheiro","engenheiro_auditor"].includes(role)||acessos.has("rdo")){
    const semRdo=escopoEngenharia.filter(o=>!(data.rdos||[]).some(r=>r.obraId===o.id&&r.data===hoje&&r.status==="concluido"));
    incluir("rdo-hoje","Engenharia","Diário de obra do dia",`${semRdo.slice(0,3).map(o=>o.name).join(", ")}${semRdo.length>3?` e mais ${semRdo.length-3}`:""}`,semRdo.length,2,"rdo","clipboard",C.blue);
    const equipe=(data.employees||[]).filter(e=>e.active!==false&&(!idsObras.size||idsObras.has(e.obra)));
    const semPonto=equipe.filter(e=>!isValidAttendanceStatus(attStatus(data,e.id,hoje)));
    incluir("ponto-hoje","Campo","Apontamentos de equipe incompletos",`${semPonto.length} de ${equipe.length} profissional(is) sem situação registrada hoje`,semPonto.length,semPonto.length===equipe.length?3:2,"ponto","clock",C.orange);
    const fichas=(data.qualidadeRegistros||[]).filter(q=>idsObras.has(q.obraId)&&q.status!=="aprovada"&&(role==="admin"||!q.responsavelId||q.responsavelId===userId));
    incluir("qualidade","Qualidade","FVS/FVM aguardando inspeção",`${fichas.filter(q=>q.status==="reprovada").length} ficha(s) reprovada(s) exigem correção`,fichas.length,fichas.some(q=>q.status==="reprovada")?3:1,"obras","check",C.purple);
    const patologias=(data.conferencias||[]).flatMap(c=>(c.pendencias||[]).filter(p=>p.status!=="resolvida"&&(role==="admin"||(role==="engenheiro_auditor"&&c.responsavelId===userId)||(role==="engenheiro"&&p.responsavelAjusteId===userId))).map(p=>({...p,obraId:c.obraId})));
    incluir("patologias","Qualidade","Patologias e inconformidades abertas",`${patologias.filter(p=>p.impacto==="critico").length} crítica(s) · ${patologias.filter(p=>!(p.fotos||[]).some(f=>f.tipo==="ajuste")).length} aguardando foto`,patologias.length,patologias.some(p=>p.impacto==="critico")?3:2,"conferencia","alert",C.red);
  }

  if(role==="admin"||role==="compras"||acessos.has("cmp")){
    const solicitacoes=(data.solicitacoesCompra||[]).filter(s=>["enviada","em_analise"].includes(s.status));
    incluir("solicitacoes","Compras","Solicitações aguardando processamento",`${solicitacoes.filter(s=>s.prioridade==="urgente").length} urgente(s) para cotar ou transformar em pedido`,solicitacoes.length,solicitacoes.some(s=>s.prioridade==="urgente")?3:2,"cmp","cart",C.orange);
    const pedidos=(data.pedidos||[]).filter(p=>!["recebido","cancelado"].includes(p.status));
    incluir("pedidos","Compras","Pedidos ainda não concluídos",`${pedidos.filter(p=>p.status==="parcial").length} com recebimento parcial`,pedidos.length,pedidos.some(p=>p.status==="parcial")?2:1,"cmp","box",C.yellowD);
  }

  if(role==="admin"||role==="financeiro"||acessos.has("conc")){
    const conciliacoes=(data.transacoes||[]).filter(t=>t.status==="pendente");
    incluir("conciliacao","Financeiro","Movimentos sem conciliação",`${conciliacoes.length} lançamento(s) ainda sem obra/categoria confirmada`,conciliacoes.length,conciliacoes.length>10?3:2,"conc","receipt",C.purple);
    const notas=(data.notasFiscais||[]).filter(n=>n.status==="recebida");
    incluir("fiscal","Financeiro","Notas aguardando conferência",`${notas.filter(n=>n.divergencias?.length).length} documento(s) com divergência de pedido ou recebimento`,notas.length,notas.some(n=>n.divergencias?.length)?3:2,"fin","fileText",C.red);
    const med=(data.medicoes||[]).filter(m=>statusRecebimentoMedicao(m)!=="recebida"&&(!m.dataVencimento||m.dataVencimento<=hoje));
    incluir("medicoes","Financeiro","Medições a receber",`${med.filter(m=>m.dataVencimento&&m.dataVencimento<hoje).length} vencida(s)`,med.length,med.some(m=>m.dataVencimento&&m.dataVencimento<hoje)?3:1,"medicoes","ruler",C.green);
  }

  if(role==="admin"||role==="rh"||acessos.has("ponto_geral")){
    const ativos=(data.employees||[]).filter(e=>e.active!==false);
    const semPonto=ativos.filter(e=>!isValidAttendanceStatus(attStatus(data,e.id,hoje)));
    incluir("rh-ponto","RH","Fechamento diário do ponto",`${semPonto.length} de ${ativos.length} cadastro(s) sem apontamento`,semPonto.length,semPonto.length===ativos.length?3:2,"ponto_geral","users",C.green);
    const incompletos=ativos.filter(e=>!e.pixKey||!e.dailyRate||!e.obra);
    incluir("rh-cadastro","RH","Cadastros de equipe incompletos",`${incompletos.filter(e=>!e.pixKey).length} sem PIX · ${incompletos.filter(e=>!e.obra).length} sem lotação`,incompletos.length,1,"equipe","user",C.blue);
  }

  if(role==="admin"||role==="comercial"||acessos.has("com_tarefas")){
    const atividades=(data.comercial?.atividades||[]).filter(a=>a.status!=="concluida"&&(role==="admin"||!a.responsavelId||a.responsavelId===userId));
    const atrasadas=atividades.filter(a=>a.dataHora&&a.dataHora<new Date().toISOString());
    incluir("comercial-atividades","Comercial","Follow-ups e atividades pendentes",`${atrasadas.length} atividade(s) fora do prazo`,atividades.length,atrasadas.length?3:1,"com_tarefas","funnel",C.green);
    const leads=(data.comercial?.leads||[]).filter(l=>!["perdido","arquivado","transferido"].includes(l.etapa)&&(role==="admin"||!l.responsavelId||l.responsavelId===userId)&&!l.proximaAtividadeEm);
    incluir("comercial-leads","Comercial","Leads sem próximo passo",`${leads.length} oportunidade(s) precisam de data e ação definida`,leads.length,2,"com_leads","target",C.orange);
  }
  return fila.sort((a,b)=>b.severidade-a.severidade||b.quantidade-a.quantidade);
};

function DashboardEngenheiro({data,update,showToast,onTab,currentUser,ultimaSync,saveState}){
  const {cols,isDesktop}=useBreakpoint();
  const [obraFiltro,setObraFiltro]=useState("all");
  const ehAuditor=currentUser?.role==="engenheiro_auditor";
  const conferencias=(data.conferencias||[]).filter(c=>ehAuditor?c.responsavelId===currentUser?.id:(c.pendencias||[]).some(p=>p.responsavelAjusteId===currentUser?.id));
  // A lista de obras não pode nascer das conferências: uma obra nova ou sem
  // vistoria atribuída desaparecia do dashboard do engenheiro. A única trava
  // válida é a restrição explícita definida pelo administrador no usuário.
  const obras=(data.obras||[]).filter(o=>o.status!=="done"&&(!currentUser?.obraId||o.id===currentUser.obraId));
  const abertas=conferencias.flatMap(c=>(c.pendencias||[]).filter(p=>p.status!=="resolvida"&&(ehAuditor?c.responsavelId===currentUser?.id:p.responsavelAjusteId===currentUser?.id)).map(p=>({p,c,obra:(data.obras||[]).find(o=>o.id===c.obraId)}))).filter(x=>obraFiltro==="all"||x.c.obraId===obraFiltro);
  const criticas=abertas.filter(x=>x.p.impacto==="critico").length;
  const aguardandoValidacao=ehAuditor?abertas.filter(x=>x.p.status==="aguardando_validacao").length:0;
  const aguardandoCorrecao=!ehAuditor?abertas.filter(x=>["aberta","em_ajuste"].includes(x.p.status)).length:0;
  const fila=useMemo(()=>construirFilaOperador(data,currentUser),[data,currentUser]);
  const abrir=c=>{sessionStorage.setItem("arcd_obra_contexto",c.obraId);sessionStorage.setItem("arcd_conferencia_obra",c.obraId);onTab("conferencia");};
  const impacto={baixo:C.green,medio:C.orange,alto:"#E26A2C",critico:C.red};
  return <div className="anim dashboard-tech-motion" style={{display:"flex",flexDirection:"column",gap:16}}>
    <DashboardTechHero data={data} currentUser={currentUser} ultimaSync={ultimaSync} fila={fila} onAbrir={onTab} saveState={saveState}/>
    <FilaOperador fila={fila} onTab={onTab}/>
    <div><p style={{...TYPO.eyebrow,color:C.blue}}>{ehAuditor?"Auditoria de engenharia":"Engenharia de campo"}</p><h2 style={{...TYPO.h2,marginTop:4}}>{ehAuditor?"Vistorias e validações":"Correções e evidências"}</h2><p style={{...TYPO.bodyMuted,marginTop:5}}>{ehAuditor?"Crie vistorias, registre os achados e valide as evidências enviadas pelos engenheiros de campo.":"Acesse apenas as pendências atribuídas a você e envie a foto da correção para validação do auditor."}</p></div>
    <div className="dashboard-kpi-grid" style={{display:"grid",gridTemplateColumns:cols(2,3,4),gap:9}}>{(ehAuditor?[["Pendências auditadas",abertas.length,C.blue,"clipboard"],["Críticas",criticas,C.red,"alert"],["Para sua validação",aguardandoValidacao,C.green,"check"],["Vistorias sob sua responsabilidade",conferencias.length,C.purple,"building"]]:[["Pendências para corrigir",abertas.length,C.blue,"clipboard"],["Críticas",criticas,C.red,"alert"],["Aguardando sua correção",aguardandoCorrecao,C.orange,"camera"]]).map(([l,v,c,i],idx)=><span key={l} style={{"--row-i":idx}}><KpiCard label={l} value={v} icon={i} color={c}/></span>)}</div>
    <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:C.rLg,boxShadow:"none",display:"flex",gap:8,alignItems:"end",flexWrap:"wrap",padding:12}}><div style={{minWidth:240,flex:1}}><Sel label="Filtrar conferências por obra" value={obraFiltro} onChange={setObraFiltro} options={[{v:"all",l:"Todas as obras disponíveis"},...obras.map(o=>({v:o.id,l:o.name}))]}/></div><Btn v="ghost" onClick={()=>onTab("obras")}><Ic n="building"/> Abrir todas as obras</Btn>{currentUser?.obraId&&<p style={{width:"100%",fontSize:"var(--arcd-type-caption)",color:C.orange}}>Seu cadastro está restrito a uma obra. O administrador pode liberar “Todas as obras” na Central do Administrador.</p>}</div>
    <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:C.rLg,overflow:"hidden",boxShadow:"none"}}><div style={{padding:"13px 15px",borderBottom:`1px solid ${C.line}`,display:"flex",justifyContent:"space-between"}}><b style={{fontSize:"var(--arcd-type-body)",color:C.text}}>Pendências sob sua responsabilidade</b><span style={{fontSize:"var(--arcd-type-caption)",color:C.muted}}>{ehAuditor?"Análise e validação técnica":"Somente envio da correção"}</span></div>{!abertas.length?<div style={{padding:30,textAlign:"center"}}><Ic n="check" s={24} color={C.green}/><p style={{fontSize:"var(--arcd-type-body)",fontWeight:600,color:C.text,marginTop:7}}>Nenhuma pendência aberta neste filtro</p></div>:abertas.map(({p,c,obra},index)=>{const acao=ehAuditor?(p.status==="aguardando_validacao"?"Validar evidência":"Acompanhar vistoria"):(p.status==="aguardando_validacao"?"Aguardando auditor":"Enviar correção");const corAcao=acao==="Validar evidência"?C.green:acao==="Enviar correção"?C.orange:C.blue;return <button key={`${c.id}-${p.id}`} onClick={()=>abrir(c)} style={{width:"100%",border:0,borderTop:index?`1px solid ${C.line}`:"none",background:"transparent",padding:"13px 15px",display:"grid",gridTemplateColumns:isDesktop?"minmax(170px,.7fr) minmax(260px,1.5fr) 130px 140px 26px":"1fr auto",gap:12,alignItems:"center",textAlign:"left",cursor:"pointer"}}><div><p style={{fontSize:"var(--arcd-type-label)",fontWeight:600,color:C.blue}}>{obra?.name||"Obra"}</p><p style={{fontSize:"var(--arcd-type-caption)",color:C.muted,marginTop:2}}>CONF-{String(c.codigo||0).padStart(3,"0")}</p></div><div style={{minWidth:0}}><p style={{fontSize:"var(--arcd-type-label)",fontWeight:600,color:C.text,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{p.descricao}</p><p style={{fontSize:"var(--arcd-type-caption)",color:C.muted,marginTop:3,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{p.ajusteNecessario}</p></div><span style={{display:isDesktop?"inline-flex":"none",justifySelf:"start"}}><Badge color={impacto[p.impacto]||C.orange}>{p.impacto}</Badge></span><span style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,color:corAcao,whiteSpace:"nowrap"}}>{acao}</span><span style={{fontSize:"var(--arcd-type-section-title)",color:C.muted}}>›</span></button>;})}</div>
    <CalendarioEmpresa data={data} update={update} showToast={showToast} currentUser={currentUser}/>
  </div>;
}

// Dashboard executivo premium. A tela trabalha por exceção: primeiro mostra
// saúde da empresa, depois o que exige decisão e só então os resumos de apoio.
function Dashboard({ data, update, showToast, onTab, onAbrirObra, ultimaSync, currentUser, onBuscar, onAtualizar, saveState }) {
  const { cols, isDesktop } = useBreakpoint();
  const [todosIndicadores,setTodosIndicadores]=useState(false);
  const agora=new Date();
  const [periodo,setPeriodo]=useState({y:agora.getFullYear(),m:agora.getMonth()});
  const year=periodo.y, month=periodo.m;
  const ym=`${year}-${String(month+1).padStart(2,"0")}`;
  const ehAtual=year===agora.getFullYear()&&month===agora.getMonth();
  const irMes=delta=>setPeriodo(p=>{const d=new Date(p.y,p.m+delta,1);if(d>new Date(agora.getFullYear(),agora.getMonth(),1))return p;return{y:d.getFullYear(),m:d.getMonth()};});
  const exec=useMemo(()=>calcResumoExecutivo(data,year,month),[data,year,month]);
  const alertasBase=useMemo(()=>calcAlertas(data,year,month),[data,year,month]);
  const hoje=today();
  const fimMes=`${ym}-${String(new Date(year,month+1,0).getDate()).padStart(2,"0")}`;
  const abasPermitidas=allowedTabsForUser(currentUser);
  const filaOperador=useMemo(()=>construirFilaOperador(data,currentUser),[data,currentUser]);
  // Gestão à vista: sempre o dia de hoje, independente do mês escolhido no topo.
  // O custo vem do servidor (mesmo motor e títulos nativos do DRE por obra).
  // Vai só até o mês fechado, então basta renová-lo a cada 5 minutos de
  // sincronização: recalcular a cada salvamento pesaria no servidor à toa.
  // Sem acesso à DRE, a coluna fica restrita.
  const veObras=abasPermitidas.includes("obras");
  const veCusto=abasPermitidas.includes("dre")||abasPermitidas.includes("dre_emp");
  const [custosObras,setCustosObras]=useState({status:"carregando",obras:{},custoAte:""});
  const custoBuscadoEm=useRef({chave:"",em:0});
  useEffect(()=>{
    if(!veObras)return;
    if(!veCusto){setCustosObras({status:"sem-acesso",obras:{},custoAte:""});return;}
    const {ano,mes}=ultimoMesFechado(hoje);
    const chave=`${ano}-${mes}`,agoraMs=Date.now();
    if(custoBuscadoEm.current.chave===chave&&agoraMs-custoBuscadoEm.current.em<5*60*1000)return;
    custoBuscadoEm.current={chave,em:agoraMs};
    let ativo=true,concluida=false;
    consultarCustoAcumuladoObras({year:ano,month:mes}).then(r=>{
      concluida=true;
      if(!ativo)return;
      if(!r?.ok)custoBuscadoEm.current={chave:"",em:0};
      setCustosObras(r?.ok?{status:"ok",obras:r.obras||{},custoAte:r.custoAte||""}:{status:"erro",obras:{},custoAte:""});
    });
    // Resposta descartada no meio do caminho não pode travar a próxima busca.
    return ()=>{ativo=false;if(!concluida)custoBuscadoEm.current={chave:"",em:0};};
  },[veObras,veCusto,hoje,ultimaSync]);
  const gestaoAVista=useMemo(()=>resumoGestaoAVista(data,{hoje,custoAcumulado:(_,obraId)=>custosObras.obras[obraId]??null,
    obraDoDia:(employee,date,record)=>resolveEmployeeAttendanceObraId({data,employee,date,record})}),[data,hoje,custosObras]);

  // Resumo diário (clima + notícias do setor): carrega uma vez por sessão de
  // dashboard, cacheado 15min no servidor — não precisa refazer a cada render.
  const [resumoDiario,setResumoDiario]=useState({carregando:true,clima:null,noticias:[],noticiasCbicPe:[],cub:null});
  useEffect(()=>{
    let ativo=true;
    buscarResumoDiario().then(r=>{
      if(!ativo)return;
      if(r.ok)setResumoDiario({carregando:false,clima:r.clima||null,noticias:r.noticias||[],noticiasCbicPe:r.noticiasCbicPe||[],cub:r.cub||null});
      else setResumoDiario({carregando:false,clima:null,noticias:[],noticiasCbicPe:[],cub:null});
    });
    return ()=>{ativo=false};
  },[]);

  const comercial=data.comercial||{};
  const leadsAtivos=(comercial.leads||[]).filter(l=>l.status!=="perdido"&&!['perdido','arquivado','transferido'].includes(l.etapa));
  const novosLeads=leadsAtivos.filter(l=>(l.createdAt||"").slice(0,7)===ym).length;
  const propostasAbertas=(comercial.propostas||[]).filter(p=>!["aceita","aceito","rejeitada","rejeitado","cancelada"].includes(p.status)).length;
  const contratosPendentes=(comercial.contratos||[]).filter(k=>["enviado","aguardando","aguardando_assinatura","pendente"].includes(k.status)).length;
  const vendasMes=(comercial.vendas||[]).filter(v=>(v.fechadaEm||"").slice(0,7)===ym).reduce((s,v)=>s+Number(v.valor||0),0);
  const medicoesPendentes=(data.medicoes||[]).filter(m=>statusRecebimentoMedicao(m)!=="recebida"&&m.dataVencimento&&m.dataVencimento<=fimMes).length;
  const pontoPendente=(data.employees||[]).some(e=>e.active!==false)&&data.dailyCheckDate!==hoje;
  const conferenciasCriticas=(data.conferencias||[]).flatMap(c=>(c.pendencias||[]).filter(p=>p.status!=="resolvida"&&p.impacto==="critico").map(p=>({sev:3,texto:`${(data.obras||[]).find(o=>o.id===c.obraId)?.name||"Obra"}: ${p.descricao}`,tab:"conferencia"})));
  const atividadesAtrasadas=(comercial.atividades||[]).filter(a=>a.status!=="concluida"&&a.dataHora&&a.dataHora<new Date().toISOString()).length;
  const prioridades=[
    ...conferenciasCriticas,
    ...(pontoPendente?[{sev:2,texto:"Verificação e distribuição da equipe ainda não concluídas",tab:"ponto"}]:[]),
    ...(medicoesPendentes?[{sev:2,texto:`${medicoesPendentes} medição(ões) aguardando recebimento`,tab:"medicoes"}]:[]),
    ...(atividadesAtrasadas?[{sev:2,texto:`${atividadesAtrasadas} atividade(s) comercial(is) atrasada(s)`,tab:"com_tarefas"}]:[]),
    ...alertasBase,
  ].filter(a=>abasPermitidas.includes(a.tab)).filter((a,i,arr)=>arr.findIndex(x=>x.texto===a.texto)===i).sort((a,b)=>b.sev-a.sev);

  const Titulo=({children,acao})=><div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,marginBottom:12}}><div><h3 style={TYPO.h3}>{children}</h3></div>{acao}</div>;
  const superficie={background:C.card,border:`1px solid ${C.border}`,borderRadius:C.rLg,boxShadow:"none"};

  return <div className="anim dashboard-tech-motion dashboard-command-center" style={{position:"relative",display:"flex",flexDirection:"column",gap:14,paddingBottom:16}}>
    <DashboardTechHero data={data} currentUser={currentUser} ultimaSync={ultimaSync} fila={filaOperador} onBuscar={onBuscar} onAtualizar={onAtualizar} onAbrir={onTab} periodo={`${fullMonth(month)} ${year}`} onAnterior={()=>irMes(-1)} onProximo={()=>irMes(1)} proximoDesabilitado={ehAtual} clima={resumoDiario.clima} saveState={saveState}/>
    <section id="dashboard-indicators" className="dashboard-executive-grid" data-expanded={todosIndicadores} style={{position:"relative",zIndex:1,display:"grid",gridTemplateColumns:cols(2,3,4),gap:10}}>
      {[
        {label:"Obras ativas",value:exec.obrasAtivas,detail:exec.obrasCriticas?`${exec.obrasCriticas} em situação crítica`:"Operação acompanhada",icon:"building",color:exec.obrasCriticas?C.red:C.blue,tab:"obras"},
        {label:"Receitas do período",value:fmt(exec.dre.recebido),detail:`Faturado ${fmt(exec.dre.faturamento)}`,icon:"trending",color:C.green,tab:"dre"},
        {label:"Despesas do período",value:fmt(exec.dre.totalCustos),detail:`${exec.dre.faturamento?((exec.dre.totalCustos/exec.dre.faturamento)*100).toFixed(0):0}% da receita`,icon:"receipt",color:C.red,tab:"dre_emp"},
        {label:"Saldo atual",value:fmt(exec.dre.saldoCaixa),detail:"Recebimentos menos custos",icon:"wallet",color:exec.dre.saldoCaixa>=0?C.green:C.red,tab:"dre"},
        {label:"Pendências críticas",value:prioridades.filter(a=>a.sev===3).length,detail:`${prioridades.length} alertas ativos`,icon:"alert",color:prioridades.some(a=>a.sev===3)?C.red:C.orange},
        {label:"Compras pendentes",value:exec.comprasPendentes+exec.solicitacoesAbertas,detail:`${exec.solicitacoesAbertas} aguardando análise`,icon:"cart",color:C.orange,tab:"cmp"},
        {label:"Leads em andamento",value:exec.leadsAtivos,detail:`${novosLeads} novo(s) no mês`,icon:"funnel",color:C.blue,tab:"com_funil"},
        {label:"Resultado operacional",value:fmt(exec.dre.lucroBruto),detail:`Margem ${exec.dre.margemBruta.toFixed(1)}%`,icon:"chart",color:exec.dre.lucroBruto>=0?C.green:C.red,tab:"dre_emp"},
      ].map(k=>{const acessivel=k.tab&&abasPermitidas.includes(k.tab);return k.tab&&!acessivel?null:<span key={k.label}><KpiCard {...k} animate={false} onClick={acessivel?()=>onTab(k.tab):undefined}/></span>;})}
    </section>
    <Button variant="ghost" className="dashboard-indicators-toggle" aria-expanded={todosIndicadores} aria-controls="dashboard-indicators" onClick={()=>setTodosIndicadores(value=>!value)}>{todosIndicadores?"Menos indicadores":"Mais indicadores"}</Button>
    <div className="dashboard-work-grid">
    {veObras&&<GestaoAVistaObras resumo={gestaoAVista} hoje={hoje} onAbrirObra={onAbrirObra} custoStatus={custosObras.status}/>}

      <div className="dashboard-work-grid__aside"><FilaOperador fila={filaOperador} onTab={onTab}/><details className="workspace-disclosure"><summary>Outras pendências ({prioridades.length})</summary><section id="dashboard-prioridades" style={{position:"relative",zIndex:1,padding:isDesktop?8:4}}>
      <Titulo acao={<span style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,color:prioridades.length?C.red:C.green,background:`${prioridades.length?C.red:C.green}0D`,padding:"5px 9px",borderRadius:99}}>{prioridades.length?`${prioridades.length} para revisar`:"Tudo em ordem"}</span>}>Pendências que exigem atenção</Titulo>
      {!prioridades.length?<div style={{padding:"18px 4px",display:"flex",alignItems:"center",gap:10,color:C.green}}><span style={{width:30,height:30,borderRadius:10,display:"grid",placeItems:"center",background:`${C.green}10`}}><Ic n="check"/></span><div><p style={{fontSize:"var(--arcd-type-body)",fontWeight:600,color:"#2D3135"}}>Nenhuma pendência prioritária</p><p style={{fontSize:"var(--arcd-type-label)",color:C.muted,marginTop:2}}>A operação está sob controle.</p></div></div>:<div style={{display:"grid",gridTemplateColumns:isDesktop&&prioridades.length>3?"1fr 1fr":"1fr",columnGap:20}}>{prioridades.slice(0,8).map((a,i)=>{const cor=a.sev===3?C.red:a.sev===2?C.orange:C.blue;return <button key={`${a.texto}-${i}`} onClick={()=>onTab(a.tab)} style={{display:"flex",alignItems:"center",gap:11,width:"100%",textAlign:"left",border:0,borderTop:i>=(isDesktop&&prioridades.length>3?2:1)?"1px solid rgba(27,31,36,.06)":"none",background:"transparent",padding:"11px 3px",cursor:"pointer"}}><span style={{width:8,height:8,borderRadius:99,background:cor,boxShadow:`0 0 0 5px ${cor}0D`,flexShrink:0}}/><span style={{fontSize:"var(--arcd-type-label)",color:"#303438",lineHeight:1.35,flex:1}}>{a.texto}</span><span style={{fontSize:"var(--arcd-type-card-title)",color:"#B1B5B9"}}>›</span></button>;})}</div>}
    </section></details>
      </div>
    </div>


    <details className="workspace-disclosure"><summary>Resumo financeiro e comercial</summary>    <section style={{position:"relative",zIndex:1,display:"grid",gridTemplateColumns:isDesktop?"1fr 1fr":"1fr",gap:12}}>
      <div style={{...superficie,padding:18}}><Titulo acao={<DesignSystemButton variant="link" size="sm" className="dashboard-link-btn" onClick={()=>onTab("dre_emp")}>Detalhes →</DesignSystemButton>}>Resumo financeiro</Titulo><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"14px 22px"}}>{[["A receber",exec.dre.aReceber,C.orange],["Fluxo do período",exec.dre.saldoCaixa,exec.dre.saldoCaixa>=0?C.green:C.red],["Principais saídas",exec.dre.totalCustos,C.red],["Resultado do mês",exec.dre.lucroBruto,exec.dre.lucroBruto>=0?C.green:C.red]].map(([l,v,c])=><div key={l}><p style={{fontSize:"var(--arcd-type-caption)",color:C.muted}}>{l}</p><p style={{fontSize:"var(--arcd-type-card-title)",fontWeight:600,color:c,marginTop:5,letterSpacing:-.3}}>{fmt(v)}</p></div>)}</div></div>
      <div style={{...superficie,padding:18}}><Titulo acao={<DesignSystemButton variant="link" size="sm" className="dashboard-link-btn" onClick={()=>onTab("com_dash")}>Abrir comercial →</DesignSystemButton>}>Resumo comercial</Titulo><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"14px 22px"}}>{[["Novos leads",novosLeads,C.blue],["Propostas abertas",propostasAbertas,C.orange],["Aguardando assinatura",contratosPendentes,C.red],["Vendas no mês",fmt(vendasMes),C.green]].map(([l,v,c])=><div key={l}><p style={{fontSize:"var(--arcd-type-caption)",color:C.muted}}>{l}</p><p style={{fontSize:"var(--arcd-type-card-title)",fontWeight:600,color:c,marginTop:5,letterSpacing:-.3}}>{v}</p></div>)}</div><div style={{height:5,display:"flex",overflow:"hidden",borderRadius:99,marginTop:17,background:"#ECEEEF"}}>{[["novo",C.blue],["qualificado",C.orange],["proposta",C.purple],["negociacao",C.yellowD]].map(([etapa,cor])=>{const qtd=leadsAtivos.filter(l=>l.etapa===etapa).length;return qtd?<span key={etapa} title={`${etapa}: ${qtd}`} style={{width:`${qtd/Math.max(1,leadsAtivos.length)*100}%`,background:cor}}/>:null;})}</div></div>
    </section></details>

    <section style={{position:"relative",zIndex:1}}><Titulo>Ações rápidas</Titulo><div style={{display:"grid",gridTemplateColumns:cols(2,3,6),gap:8}}>{[
      ["Nova compra","cart","cmp"],["Novo lead","user","com_leads"],["Lançar despesa","dollar","dre_emp"],["Abrir ponto","clock","ponto"],["Revisar medições","ruler","medicoes"],["Conferências","check","conferencia"],
    ].filter(([, ,tab])=>abasPermitidas.includes(tab)).map(([label,icon,tab])=><button key={label} onClick={()=>onTab(tab)} className="dashboard-quick-action" style={{minHeight:70,border:`1px solid ${C.border}`,background:C.card,borderRadius:C.rLg,padding:11,cursor:"pointer",display:"flex",flexDirection:"column",alignItems:"flex-start",justifyContent:"space-between",textAlign:"left",...TYPO.label}}><span style={{width:28,height:28,borderRadius:9,background:C.card2,display:"grid",placeItems:"center",color:C.blue}}><Ic n={icon} s={13}/></span>{label}</button>)}</div></section>
    <CalendarioEmpresa data={data} update={update} showToast={showToast} currentUser={currentUser}/>
    <details className="workspace-disclosure"><summary>Mercado e índices da construção</summary>
    <section style={{position:"relative",zIndex:1,display:"grid",gridTemplateColumns:isDesktop?"1fr 1fr":"1fr",gap:12}}>
      <NoticiasSetor carregando={resumoDiario.carregando} noticias={resumoDiario.noticias}/>
      <NoticiasSetor carregando={resumoDiario.carregando} noticias={resumoDiario.noticiasCbicPe} titulo="CBIC Pernambuco" subtitulo="Sinduscon-PE e câmara regional"/>
    </section>
    <Suspense fallback={null}>
      <LazyCubChart cub={resumoDiario.cub} carregando={resumoDiario.carregando}/>
    </Suspense>

    </details>
  </div>;
}

//
// MEDIÇÕES / FATURAMENTO - por obra
//

//
// DRE GERENCIAL - helpers e componente
//

const OUTRAS_CATEGORIAS = DEFAULT_WORK_EXPENSE_CATEGORIES;
const categoriasDesp = workExpenseCategories;

// Rotulo de uma categoria por chave (cai na propria chave se nao achar).
const rotuloCategoria = (data, v) =>
  (categoriasDesp(data).find(c => c.v === v)?.l) || v;

function FinanceiroObraPainel({data,showToast,currentUser=null,obraId,dispatchCommand=null}){
  const agora=new Date();
  const [aba,setAba]=useState("resumo");
  const [periodo,setPeriodo]=useState(`${agora.getFullYear()}-${String(agora.getMonth()+1).padStart(2,"0")}`);
  const [busca,setBusca]=useState("");
  const [despModal,setDespModal]=useState(false);
  const [expenseCommandPending,setExpenseCommandPending]=useState(false);
  const [despForm,setDespForm]=useState({obraId,competencia:periodo,categoria:"material",descricao:"",valor:""});
  const obra=(data.obras||[]).find(o=>o.id===obraId);
  const [ano,mes]=periodo.split("-").map(Number);
  const dre=useMemo(()=>calcDREObra(data,obraId,ano,mes-1),[data,obraId,ano,mes]);
  const movimentos=useMemo(()=>selectFinancialMovements(dre.ledger,{
    obraId,startDate:`${periodo}-01`,endDate:dre.perF,competence:periodo,
  }).filter(item=>["revenue","revenue_reversal","cost","cost_reversal","cash_in","cash_out"].includes(item.natureza))
    .map(item=>({
      ...item,grupo:rotuloCategoria(data,item.categoria),pessoa:"",
      tipo:["revenue","revenue_reversal"].includes(item.natureza)?"receita":
        ["cost","cost_reversal"].includes(item.natureza)?"custo":
        item.natureza==="cash_in"?"entrada":"saida",
      status:"realizado",origem:item.origem,valor:item.valor,
    })).sort((a,b)=>String(b.data||"").localeCompare(String(a.data||""))),
    [dre.ledger,dre.perF,obraId,periodo,data]);
  const receitaReconhecida=dre.faturamento;
  const custoIncorrido=dre.totalCustos;
  const resultadoCompetencia=dre.lucroBruto;
  const entradasCaixa=dre.entradasCaixa;
  const saidasCaixa=dre.saidasCaixa;
  const saldo=dre.saldoCaixa;
  const totalFluxo=Math.max(1,entradasCaixa+saidasCaixa);
  const orc=orcamentoDaObra(data,obraId);
  const orcado=(orc?.itens||[]).filter(i=>i.tipo!=="titulo").reduce((s,i)=>s+Number(i.quantidade||0)*Number(i.precoUnit||0),0);
  const realizadoCustos=Number(dre.totalCustos||0);
  const categorias=Object.entries(movimentos.filter(m=>m.tipo==="custo").reduce((acc,m)=>({...acc,[m.grupo]:(acc[m.grupo]||0)+m.valor}),{})).sort((a,b)=>b[1]-a[1]);
  const termo=busca.toLowerCase().trim();
  const filtrar=(lista,tipo="")=>lista.filter(m=>(!tipo||m.tipo===tipo)&&(!termo||`${m.descricao} ${m.pessoa} ${m.grupo}`.toLowerCase().includes(termo)));
  const listaAba=aba==="dre"?filtrar(movimentos).filter(m=>["receita","custo"].includes(m.tipo))
    :aba==="caixa"?filtrar(movimentos).filter(m=>["entrada","saida"].includes(m.tipo))
    :filtrar(movimentos);
  const salvarDespesa=async()=>{
    if(!dispatchCommand||expenseCommandPending)return;
    setExpenseCommandPending(true);
    try {
      const id=uid();
      const result=await dispatchCommand(()=>({
        type:OPERATIONAL_COMMAND.PROJECT_EXPENSE_CREATED,
        idempotencyKey:`project-expense-create-${id}-${uid()}`,
        expectedVersion:0,
        actorId:currentUser?.id||"",actorName:currentUser?.nome||"",
        payload:{expense:{...despForm,id,obraId,competencia:despForm.competencia||periodo}},
      }));
      if(!result?.ok)throw new Error(result?.reason||"O servidor não confirmou a despesa.");
      setDespModal(false);setDespForm({obraId,competencia:periodo,categoria:"material",descricao:"",valor:""});showToast("Despesa registrada na obra.");
    } catch (error) {
      showToast(error.message || "Não foi possível registrar a despesa.","error");
    } finally {
      setExpenseCommandPending(false);
    }
  };
  const Metric=({label,value,detail,tone="neutral"})=><div className={`obra-fin-metric ${tone}`}><span>{label}</span><strong>{fmt(value)}</strong><small>{detail}</small></div>;
  const Tabela=({lista})=><div className="obra-fin-table-wrap"><table className="obra-fin-table"><thead><tr><th>Movimentação</th><th>Origem</th><th>Data</th><th>Natureza</th><th>Valor</th></tr></thead><tbody>{lista.map(m=><tr key={m.id}><td data-label="Movimentação"><b>{m.descricao}</b><small>{m.documento||m.grupo}</small></td><td data-label="Origem">{m.origem}</td><td data-label="Data">{m.data?fmtDate(m.data):"—"}</td><td data-label="Natureza"><span className={`obra-fin-status ${m.status}`}>{m.tipo==="receita"?"Receita reconhecida":m.tipo==="custo"?"Custo incorrido":m.tipo==="entrada"?"Entrada de caixa":"Saída de caixa"}</span></td><td data-label="Valor" className={["custo","saida"].includes(m.tipo)?"despesa":"receita"}>{["custo","saida"].includes(m.tipo)?"− ":"+ "}{fmt(m.valor)}</td></tr>)}</tbody></table>{!lista.length&&<div className="obra-fin-empty">Nenhuma movimentação encontrada neste filtro.</div>}</div>;

  return <div className="obra-financeiro">
    <header className="obra-fin-header"><div><p>CONTROLE FINANCEIRO DA OBRA</p><h2>{obra?.name||"Obra"}</h2><span>Recebimentos, compromissos e pagamentos em uma única visão.</span></div><DesignSystemButton onClick={()=>{setDespForm({obraId,competencia:periodo,categoria:"material",descricao:"",valor:""});setDespModal(true);}}><Ic n="plus"/> Nova despesa</DesignSystemButton></header>
    <TabRow tabs={[["resumo","Resumo"],["dre","DRE por competência"],["caixa","Entradas e saídas"],["posicoes","Contas em aberto"],["movimentos","Rastreabilidade"],["orcado","Orçado × comprometido"]]} active={aba} onChange={setAba}/>
    <div className="obra-fin-controls"><label><span>Competência</span><input type="month" value={periodo} onChange={e=>setPeriodo(e.target.value)}/></label>{aba!=="resumo"&&aba!=="orcado"&&<label className="obra-fin-search"><span>Pesquisar</span><input value={busca} onChange={e=>setBusca(e.target.value)} placeholder="Descrição, fornecedor ou categoria"/></label>}</div>
    {aba==="resumo"&&<><section className="obra-fin-summary">
      <div className="obra-fin-column"><h3>DRE do período</h3><Metric label="Receita reconhecida" value={receitaReconhecida} detail="Regime de competência" tone="positive"/><Metric label="Custos incorridos" value={custoIncorrido} detail="Documentos e apropriações" tone="negative"/><Metric label="Resultado por competência" value={resultadoCompetencia} detail={`${dre.margemBruta.toFixed(1)}% de margem`} tone={resultadoCompetencia>=0?"positive":"danger"}/></div>
      <div className="obra-fin-column"><h3>Posições</h3><Metric label="Contas a receber" value={dre.contasReceber} detail="Faturado ainda não recebido"/><Metric label="Contas a pagar" value={dre.contasPagar} detail="Obrigações ainda não liquidadas"/><Metric label="Comprometido" value={dre.comprometido} detail="Pedidos ainda não convertidos em custo"/><Metric label="Pago direto pelo cliente" value={dre.pagoPeloCliente||0} detail="Baixou obrigação sem passar pelo caixa da empresa"/></div>
      <div className="obra-fin-balance"><div><span>Saldo de caixa do período</span><strong className={saldo>=0?"positive":"negative"}>{fmt(saldo)}</strong><small>Entradas efetivas menos saídas efetivas</small></div><div className="obra-fin-balance-bar"><i style={{width:`${entradasCaixa/totalFluxo*100}%`}}/><b style={{width:`${saidasCaixa/totalFluxo*100}%`}}/></div><div className="obra-fin-legend"><span><i/>Entradas {fmt(entradasCaixa)}</span><span><i/>Saídas {fmt(saidasCaixa)}</span></div><div className="obra-fin-projection"><span>{dre.conference?.ok?"Conferência OK":`${dre.conference?.errors?.length||0} pendência(s) de conferência`}</span><b>{fmt(dre.recebimentosNaoAlocados)} não alocado</b></div></div>
    </section></>}
    {["dre","caixa","movimentos"].includes(aba)&&<Tabela lista={listaAba}/>}
    {aba==="posicoes"&&<section className="obra-fin-summary"><div className="obra-fin-column"><h3>Contas a receber</h3><Metric label="Saldo" value={dre.contasReceber} detail="Medições menos recebimentos vinculados"/><Metric label="Recebimentos não alocados" value={dre.recebimentosNaoAlocados} detail="Entraram no caixa sem baixar documento"/></div><div className="obra-fin-column"><h3>Contas a pagar</h3><Metric label="Saldo" value={dre.contasPagar} detail="NFs e medições de terceiros menos pagamentos"/><Metric label="Pagamentos não alocados" value={dre.pagamentosNaoAlocados} detail="Saíram do caixa sem obrigação reconhecida"/></div><div className="obra-fin-column"><h3>Compromissos</h3><Metric label="Pedidos comprometidos" value={dre.comprometido} detail="Pedido aprovado menos documentos reconhecidos"/></div></section>}
    {aba==="orcado"&&<section className="obra-fin-budget"><div className="obra-fin-budget-kpis"><Metric label="Custo orçado" value={orcado} detail="Orçamento aprovado"/><Metric label="Custo realizado" value={realizadoCustos} detail={`${orcado?(realizadoCustos/orcado*100).toFixed(1):"0,0"}% consumido`} tone={realizadoCustos>orcado?"danger":"negative"}/><Metric label="Saldo do orçamento" value={orcado-realizadoCustos} detail="Disponível para executar" tone={orcado-realizadoCustos>=0?"positive":"danger"}/></div><div className="obra-fin-budget-progress"><div><span>Execução financeira</span><b>{orcado?Math.round(realizadoCustos/orcado*100):0}%</b></div><i><b style={{width:`${Math.min(100,orcado?realizadoCustos/orcado*100:0)}%`}}/></i></div><div className="obra-fin-categories"><h3>Custos realizados por categoria</h3>{categorias.map(([l,v])=><div key={l}><span>{l}</span><i><b style={{width:`${realizadoCustos?v/realizadoCustos*100:0}%`}}/></i><strong>{fmt(v)}</strong></div>)}{!categorias.length&&<em>Sem custos realizados nesta competência.</em>}</div></section>}
    <DesignSystemDialog open={despModal} onOpenChange={setDespModal} title="Nova despesa da obra"><div style={{display:"grid",gap:10}}><DesignSystemInput label="Obra" value={obra?.name||""} onChange={()=>{}} disabled/><DesignSystemInput label="Descrição" required value={despForm.descricao} onChange={e=>setDespForm(f=>({...f,descricao:e.target.value}))}/><DesignSystemSelect label="Categoria" value={despForm.categoria} onChange={e=>setDespForm(f=>({...f,categoria:e.target.value}))} options={categoriasDesp(data).map(c=>({value:c.v,label:c.l}))}/><DesignSystemInput label="Competência" type="month" value={despForm.competencia} onChange={e=>setDespForm(f=>({...f,competencia:e.target.value}))}/><DesignSystemInput label="Valor" required type="number" value={despForm.valor} onChange={e=>setDespForm(f=>({...f,valor:e.target.value}))}/>
      {despForm.categoria==="material" && ["admin_only","fixed_labor_admin"].includes(obra?.contractType) && (
        <div>
          <p style={{fontSize:"var(--arcd-type-label)",fontWeight:600,color:C.subtle,textTransform:"uppercase",marginBottom:5}}>Este material entra na taxa de administração?</p>
          <div style={{display:"flex",gap:8}}>
            <DesignSystemButton size="sm" variant={despForm.contaAdmin!==false?"success":"ghost"} onClick={()=>setDespForm(f=>({...f,contaAdmin:true}))} style={{flex:1}}>Sim, entra</DesignSystemButton>
            <DesignSystemButton size="sm" variant={despForm.contaAdmin===false?"danger":"ghost"} onClick={()=>setDespForm(f=>({...f,contaAdmin:false}))} style={{flex:1}}>Não entra</DesignSystemButton>
          </div>
        </div>
      )}
      <div style={{display:"flex",gap:8}}><DesignSystemButton variant="ghost" onClick={()=>setDespModal(false)} style={{flex:1}}>Cancelar</DesignSystemButton><DesignSystemButton disabled={expenseCommandPending} onClick={salvarDespesa} style={{flex:1}}>{expenseCommandPending?"Salvando...":"Salvar despesa"}</DesignSystemButton></div></div></DesignSystemDialog>
  </div>;
}

function DRE({data,showToast,currentUser=null,obraIdFixo="",dispatchCommand=null}){
  return obraIdFixo?<FinanceiroObraPainel data={data} showToast={showToast} currentUser={currentUser} obraId={obraIdFixo} dispatchCommand={dispatchCommand}/>:<DRELegado data={data} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchCommand}/>;
}

function DRELegado({ data, showToast, currentUser=null, obraIdFixo="", dispatchCommand=null }) {
  const {intent}=useWorkflow();
  const useSessionState=(key,initial)=>useWorkspaceState("dre",key,initial,obraIdFixo);
  useWorkspaceScroll("dre",obraIdFixo);
  const now   = new Date();
  const [year,  setYear]   = useSessionState("year",now.getFullYear());
  const [month, setMonth]  = useSessionState("month",now.getMonth());
  const [periodoDRE,setPeriodoDRE] = useSessionState("periodoDRE","mes");
  const [view,  setView]   = useSessionState("view",obraIdFixo?"obra":"consolidado"); // "consolidado" | "obra" | "historico"
  const [selObra, setSelObra] = useSessionState("selObra",obraIdFixo||data.obras[0]?.id||"");
  useEffect(()=>{
    if(intent?.tabId!=="dre"||intent.action==="resume")return;
    const scope=normalizeWorkflowScope(intent.scope,currentUser);
    if(scope.year!=null)setYear(scope.year);
    if(scope.month!=null)setMonth(scope.month);
    if(intent.linked!==false)setPeriodoDRE(scope.period);
    if(scope.obraId){if(scope.obraId!==selObra||intent.linked!==false)setView("obra");setSelObra(scope.obraId);}
    else if(!obraIdFixo&&intent.linked!==false)setView("consolidado");
  },[intent?.sequence]);
  useRememberWorkflowScope("dre",{obraId:obraIdFixo||(view==="obra"?selObra:""),year,month,period:periodoDRE});
  const [despModal, setDespModal] = useState(false);
  const [expenseCommandPending,setExpenseCommandPending]=useState(false);
  const [despForm,  setDespForm]  = useState({ obraId:"", competencia:"", categoria:"material", descricao:"", valor:"" });
  const [detalheKpi, setDetalheKpi] = useState("");
  const [filtroDetalhe, setFiltroDetalhe] = useSessionState("filtroDetalhe",{ busca:"", categoria:"todos", obra:"todas", ordem:"data_desc" });
  const [avaliacaoCFOObra,setAvaliacaoCFOObra]=useState(null);
  const [avaliandoCFOObra,setAvaliandoCFOObra]=useState(false);
  const [razaoDRE,setRazaoDRE]=useState({consolidado:null,obra:null});
  const DF = k => v => setDespForm(f=>({...f,[k]:v}));

  const obraFinanceiraId = obraIdFixo || selObra;
  const dreLegado = useMemo(()=>calcDREConsolidado(data,year,month,periodoDRE), [data,year,month,periodoDRE]);
  const dreObraLegado = useMemo(()=>calcDREObra(data,obraFinanceiraId,year,month,periodoDRE), [data,obraFinanceiraId,year,month,periodoDRE]);
  useEffect(()=>{
    let ativo=true;
    Promise.all([
      consultarDreCanonico({year,month,period:periodoDRE}),
      obraFinanceiraId?consultarDreCanonico({year,month,period:periodoDRE,obraId:obraFinanceiraId}):Promise.resolve(null),
    ]).then(([consolidado,obra])=>{
      if(!ativo)return;
      setRazaoDRE({
        consolidado:consolidado?.status===200?consolidado:null,
        obra:obra?.status===200?obra:null,
      });
    });
    return()=>{ativo=false;};
  },[year,month,periodoDRE,obraFinanceiraId,data]);
  // FIN-002 já provou a igualdade em produção. A fonte visual do DRE passa a
  // ser o evento canônico; o cálculo legado fica somente como complemento de
  // detalhes que ainda não possuem projeção própria, não como indicador.
  const aplicarRazao=(legado,relatorio)=>relatorio?.source==="canonical_ledger"&&relatorio.current
    ? {...legado,...relatorio.current,fonteFinanceira:"razao_canonico"} : legado;
  const dre = useMemo(()=>aplicarRazao(dreLegado,razaoDRE.consolidado),[dreLegado,razaoDRE.consolidado]);
  const dreObra = useMemo(()=>aplicarRazao(dreObraLegado,razaoDRE.obra),[dreObraLegado,razaoDRE.obra]);
  // A visão selecionada é a única fonte dos cards, do período e do extrato.
  // Antes, apenas o demonstrativo inferior mudava para a obra; os KPIs
  // permaneciam presos ao consolidado.
  const dreResumo=(obraIdFixo||view==="obra")?dreObra:dre;
  const hist  = useMemo(()=>calcDREHistorico(data,year,month,6).map((linha,index)=>
    razaoDRE.consolidado?.source==="canonical_ledger"&&razaoDRE.consolidado.history?.[index]
      ? {...linha,...razaoDRE.consolidado.history[index],fonteFinanceira:"razao_canonico"} : linha
  ), [data,year,month,razaoDRE.consolidado]);
  const histObra=useMemo(()=>Array.from({length:6},(_,i)=>{
    const d=new Date(year,month-5+i,1);
    const base=calcDREObra(data,obraFinanceiraId,d.getFullYear(),d.getMonth(),"mes");
    const linha=razaoDRE.obra?.source==="canonical_ledger"&&razaoDRE.obra.history?.[i]
      ? {...base,...razaoDRE.obra.history[i]} : base;
    return {mes:`${monthName(d.getMonth())}/${String(d.getFullYear()).slice(2)}`,faturamento:linha.faturamento,
      recebido:linha.recebido,custos:linha.totalCustos,maoDeObra:linha.moData.laborCost+linha.moData.benefitCost,
      lucro:linha.lucroBruto,margem:linha.margemBruta};
  }),[data,obraFinanceiraId,year,month,razaoDRE.obra]);
  const equipeObra=useMemo(()=>{
    const ids=new Set();
    (data.employees||[]).forEach(emp=>(dreObra.days||[]).forEach(dia=>{
      const reg=data.attendance?.[emp.id]?.[dia];
      const obraDia=resolveEmployeeAttendanceObraId({data,employee:emp,date:dia,record:reg});
      if(obraDia===obraFinanceiraId&&["P","M"].includes(attStatus(data,emp.id,dia)))ids.add(emp.id);
    }));
    const homemDias=(data.employees||[]).reduce((s,emp)=>s+(dreObra.days||[]).reduce((sd,dia)=>{
      const reg=data.attendance?.[emp.id]?.[dia],obraDia=resolveEmployeeAttendanceObraId({data,employee:emp,date:dia,record:reg});
      if(obraDia!==obraFinanceiraId)return sd;
      const st=attStatus(data,emp.id,dia);return sd+(st==="P"?1:st==="M"?0.5:0);
    },0),0);
    return {pessoas:ids.size,homemDias};
  },[data,dreObra.days,obraFinanceiraId]);

  const years = Array.from({length:4},(_,i)=>now.getFullYear()-2+i).map(y=>({v:String(y),l:String(y)}));
  const period = `${periodoDRE==="q1"?"1ª quinzena (06–20) · ":periodoDRE==="q2"?"2ª quinzena (21–05) · ":""}${fullMonth(month)} ${year}`;
  const fmt2 = n=>Number(n||0).toFixed(2).replace(".",",");

  useEffect(()=>{setAvaliacaoCFOObra(null);},[obraFinanceiraId,year,month,periodoDRE]);

  const analisarObraComoCFO=async()=>{
    setAvaliandoCFOObra(true);
    try{
      const obra=dreObra.obra||{};
      const contexto={modulo:"dre",escopo:"obra",periodo:period,obra:{id:obra.id,nome:obra.name,status:obra.status,
        contrato:Number(obra.contractValue||0),receitaReconhecida:dreObra.faturamento,entradasCaixa:dreObra.entradasCaixa,
        recebimentosDeClientes:dreObra.recebido,contasReceber:dreObra.contasReceber,
        custosIncorridos:dreObra.totalCustos,saidasCaixa:dreObra.saidasCaixa,contasPagar:dreObra.contasPagar,
        comprometido:dreObra.comprometido,recebimentosNaoAlocados:dreObra.recebimentosNaoAlocados,
        pagamentosNaoAlocados:dreObra.pagamentosNaoAlocados,lucro:dreObra.lucroBruto,margem:dreObra.margemBruta,
        saldoCaixa:dreObra.saldoCaixa,maoDeObra:dreObra.moData.laborCost,beneficios:dreObra.moData.benefitCost,
        terceiros:dreObra.tercCost,outrasDespesas:dreObra.outrasTotal,equipamentos:dreObra.equipCost,
        equipe:equipeObra,backlog:dreObra.backlog,pctFaturado:dreObra.pctFaturado,pctRecebido:dreObra.pctRecebido},
        historicoMensal:histObra};
      const prompt=`Você é o CFO da empresa e deve emitir uma Avaliação do CFO sobre uma única obra. Retorne SOMENTE JSON válido:
{"veredicto":"saudavel|atencao|critico","avaliacao":"4 a 6 frases com o diagnóstico executivo","maoDeObra":{"veredicto":"adequada|revisar|inconclusivo","analise":"avalie custo, pessoas e homem-dias sem inventar produtividade física","evidencias":["números recebidos"],"decisao":"ação objetiva"},"historico":{"leitura":"evolução mês a mês","melhorMes":"mês e motivo numérico","piorMes":"mês e motivo numérico","tendencia":"melhora|estavel|piora|inconclusiva"},"decisoes":[{"prioridade":1,"acao":"decisão","impactoEsperado":"efeito financeiro sem inventar valor","prazo":"Hoje|7 dias|30 dias","indicador":"métrica"}],"riscos":["com evidência"],"dadosFaltantes":["o que impede conclusão"],"conclusao":"veredicto final direto"}.
Regras: diferencie faturamento de recebimento; não conclua excesso de pessoas apenas pelo número do efetivo; use custo de MO, homem-dias, faturamento, margem e histórico. Se não houver produção física ou planejamento, declare que a produtividade é inconclusiva e recomende qual dado acompanhar.`;
      const resposta=await chamarIA({modulo:"dre",prompt,contexto});
      if(!resposta.ok)throw new Error(resposta.error||"O Gemini não respondeu.");
      setAvaliacaoCFOObra({...jsonDaRespostaIA(resposta.reply||resposta.answer),geradoEm:new Date().toISOString()});
      showToast("Avaliação do CFO gerada para a obra.");
    }catch(error){showToast(error.message||"Não foi possível gerar a avaliação do CFO.","error");}
    finally{setAvaliandoCFOObra(false);}
  };

  const movimentosDRE = useMemo(() => {
    const porId=new Map((data.obras||[]).map(obra=>[obra.id,obra.name]));
    const filters={
      ...(obraIdFixo||view==="obra"?{obraId:obraFinanceiraId}:{}),
      startDate:dreResumo.per0,endDate:dreResumo.perF,
      ...(periodoDRE==="mes"?{competence:dreResumo.ym}:{}),
    };
    return selectFinancialMovements(dreResumo.ledger,filters)
      .filter(item=>["revenue","cost","cash_in"].includes(item.natureza))
      .map(item=>({
        ...item,obra:porId.get(item.obraId)||"Empresa",
        categoria:rotuloCategoria(data,item.categoria),
        natureza:item.natureza==="revenue"?"faturamento":item.natureza==="cash_in"?"recebido":"custo",
        valor:item.valor,
      }));
  }, [data,periodoDRE,obraIdFixo,view,obraFinanceiraId,dreResumo]);

  const movimentosDetalhe = useMemo(() => {
    const permitidos = detalheKpi==="faturamento" ? ["faturamento"]
      : detalheKpi==="recebido" ? ["recebido"]
      : detalheKpi==="custos" ? ["custo"] : ["faturamento","custo"];
    const busca=filtroDetalhe.busca.trim().toLocaleLowerCase("pt-BR");
    const fator = detalheKpi==="lucro" ? (x=>x.natureza==="custo"?-1:1) : (()=>1);
    return movimentosDRE.filter(x=>
      permitidos.includes(x.natureza) &&
      (filtroDetalhe.categoria==="todos"||x.categoria===filtroDetalhe.categoria) &&
      (filtroDetalhe.obra==="todas"||x.obraId===filtroDetalhe.obra) &&
      (!busca||`${x.descricao} ${x.obra} ${x.documento}`.toLocaleLowerCase("pt-BR").includes(busca))
    ).map(x=>({...x,valorExibido:x.valor*fator(x)})).sort((a,b)=>{
      if(filtroDetalhe.ordem==="valor_desc") return Math.abs(b.valorExibido)-Math.abs(a.valorExibido);
      if(filtroDetalhe.ordem==="valor_asc") return Math.abs(a.valorExibido)-Math.abs(b.valorExibido);
      return filtroDetalhe.ordem==="data_asc" ? a.data.localeCompare(b.data) : b.data.localeCompare(a.data);
    });
  },[movimentosDRE,detalheKpi,filtroDetalhe]);

  const saveDesp = async() => {
    if(!dispatchCommand||expenseCommandPending)return;
    setExpenseCommandPending(true);
    try {
      const id=uid();
      const result=await dispatchCommand(()=>({
        type:OPERATIONAL_COMMAND.PROJECT_EXPENSE_CREATED,
        idempotencyKey:`project-expense-create-${id}-${uid()}`,
        expectedVersion:0,
        actorId:currentUser?.id||"",actorName:currentUser?.nome||"",
        payload:{expense:{...despForm,id}},
      }));
      if(!result?.ok)throw new Error(result?.reason||"O servidor não confirmou a despesa.");
      setDespModal(false);
      setDespForm({obraId:"",competencia:"",categoria:"material",descricao:"",valor:""});
      showToast("Despesa registrada.");
    } catch (error) {
      showToast(error.message||"Não foi possível registrar a despesa.","error");
    } finally {
      setExpenseCommandPending(false);
    }
  };

  const delDesp = async id => {
    const motivo=window.prompt("Motivo do cancelamento da despesa:");
    if(!String(motivo||"").trim())return;
    if(!dispatchCommand||expenseCommandPending)return;
    setExpenseCommandPending(true);
    try {
      const result=await dispatchCommand(atual=>{
        const vigente=(atual.outrasDesp||[]).find(item=>item.id===id);
        return {
          type:OPERATIONAL_COMMAND.PROJECT_EXPENSE_CANCELLED,
          idempotencyKey:`project-expense-cancel-${id}-${uid()}`,
          expectedVersion:Number(vigente?.version||0),
          actorId:currentUser?.id||"",actorName:currentUser?.nome||"",
          payload:{expenseId:id,reason:motivo},
        };
      });
      if(!result?.ok)throw new Error(result?.reason||"O servidor não confirmou o cancelamento.");
      showToast("Despesa cancelada e preservada para auditoria.");
    } catch (error) {
      showToast(error.message || "Não foi possível cancelar a despesa.", "error");
    } finally {
      setExpenseCommandPending(false);
    }
  };

  //  Linha DRE reutilizável
  const DRERow = ({label,value,color=C.text,bold=false,indent=0,pct=null}) => (
    <div style={{
      display:"flex",justifyContent:"space-between",alignItems:"center",
      padding:`${bold?"8px":"5px"} ${indent*12}px 5px ${12+indent*12}px`,
      borderBottom:`1px solid ${C.line}22`,
      background:bold?`${color}08`:"transparent",
    }}>
      <p style={{fontSize:bold?"var(--arcd-type-body)":"var(--arcd-type-body)",color:bold?color:C.muted,fontWeight:bold?600:400}}>{label}</p>
      <div style={{textAlign:"right",flexShrink:0}}>
        <p style={{fontSize:bold?"var(--arcd-type-card-title)":"var(--arcd-type-body)",color,fontWeight:bold?600:600}}>{fmt(value)}</p>
        {pct!==null&&<p style={{fontSize:"var(--arcd-type-caption)",color:color+"99",marginTop:1}}>{pct.toFixed(1)}%</p>}
      </div>
    </div>
  );
  const DRESection = ({title,color=C.yellow}) => (
    <div style={{background:`${color}15`,borderLeft:`1px solid ${color}`,padding:"5px 12px",marginTop:6}}>
      <p style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,color,textTransform:"uppercase",letterSpacing:1}}>{title}</p>
    </div>
  );
  const DRESeparator = () => <div style={{height:1,background:`linear-gradient(90deg,transparent,${C.line},transparent)`,margin:"4px 0"}}/>;

  //  DRE de uma obra (card)
  const renderObraDRE = (d, compact=false) => {
    if(!d.obra) return null;
    const lucroCor = d.lucroBruto>=0?C.green:C.red;
    const caixaCor = d.saldoCaixa>=0?C.blue:C.red;
    return (
      <div key={d.obra.id} style={{background:C.card,border:`1px solid ${C.border}`,borderLeft:`1px solid ${lucroCor}`,borderRadius:10,overflow:"hidden"}}>
        {/* Header obra */}
        <div style={{background:`${lucroCor}10`,padding:"10px 14px",borderBottom:`1px solid ${C.line}`,display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:8}}>
          <div>
            <p style={{fontFamily:"var(--arcd-font-sans)",fontWeight:600,fontSize:"var(--arcd-type-card-title)"}}>{d.obra.name}</p>
            <p style={{fontSize:"var(--arcd-type-label)",color:C.muted,marginTop:2}}>
              {CONTRACT_LABELS[d.obra.contractType]||"Contrato"}
              {d.obra.contractValue>0&&`  ${fmt(d.obra.contractValue)}`}
              {d.pctAvanco>0&&`  ${d.pctAvanco}% executado`}
            </p>
          </div>
          <div style={{textAlign:"right",flexShrink:0}}>
            <p style={{fontSize:"var(--arcd-type-caption)",color:C.muted,textTransform:"uppercase",fontWeight:600}}>Lucro Bruto</p>
            <p style={{fontFamily:"var(--arcd-font-sans)",fontWeight:600,fontSize:"var(--arcd-type-section-title)",color:lucroCor,letterSpacing:.5}}>{fmt(d.lucroBruto)}</p>
            <p style={{fontSize:"var(--arcd-type-label)",color:lucroCor+"99"}}>{d.margemBruta.toFixed(1)}%</p>
          </div>
        </div>

        {/* DRE */}
        <div style={{padding:"8px 0"}}>
          <DRESection title="Receitas" color={C.green}/>
          <DRERow label="Faturamento emitido" value={d.faturamento} color={C.green} bold/>
          {d.equipReceita>0&&<DRERow label="↳ inclui locação de equip. (líq.)" value={d.equipLucro} color={C.blue} indent={1}/>}
          <DRERow label="Recebido em caixa"   value={d.recebido}    color={C.blue}  indent={1}/>
          <DRERow label="A receber"            value={d.aReceber}    color={d.aReceber>0?C.orange:C.muted} indent={1}/>

          <DRESection title="Custos Diretos" color={C.red}/>
          <DRERow label={`(-) MO própria · ${d.days?.length||0} dias no período`} value={d.moData.laborCost} color={C.orange} indent={1}/>
          <DRERow label="(-) Benefícios VT/VR" value={d.moData.benefitCost} color={C.muted}   indent={1}/>
          <DRERow label="(-) Terceirizados (obra)" value={d.tercCost}          color={C.purple}  indent={1}/>
          {d.tercPago>0&&(
            <div style={{padding:"5px 12px 5px 24px",display:"flex",justifyContent:"space-between",alignItems:"center",opacity:.75}}>
              <p style={{fontSize:"var(--arcd-type-label)",color:C.muted,fontStyle:"italic"}}>↳ já pago em caixa (referência, não afeta a margem desta obra)</p>
              <p style={{fontSize:"var(--arcd-type-label)",color:C.green,fontWeight:600}}>{fmt(d.tercPago)}</p>
            </div>
          )}
          {d.comprasCost>0&&<DRERow label="(-) Materiais reconhecidos por nota fiscal" value={d.comprasCost} color={C.yellowD} indent={1}/>}
          {d.rescTotal>0&&<DRERow label="(-) Rescisões" value={d.rescTotal} color={C.red} indent={1}/>}
          {d.equipCost>0&&<DRERow label="(-) Locação de equipamentos" value={d.equipCost} color={C.blue} indent={1}/>}
          {d.outrasTotal>0&&<DRERow label="(-) Outras despesas" value={d.outrasTotal} color={C.orange} indent={1}/>}
          <DRERow label="Total custos" value={d.totalCustos} color={C.red} bold/>
          {d.tercEmpresaObra>0&&(
            <div style={{padding:"5px 12px 5px 24px",display:"flex",justifyContent:"space-between",alignItems:"center",opacity:.75}}>
              <p style={{fontSize:"var(--arcd-type-label)",color:C.muted,fontStyle:"italic"}}>Terceirizados pagos pela empresa (referência, não afeta a margem desta obra)</p>
              <p style={{fontSize:"var(--arcd-type-label)",color:C.muted,fontWeight:600}}>{fmt(d.tercEmpresaObra)}</p>
            </div>
          )}

          <DRESeparator/>
          <DRERow label="Lucro Bruto" value={d.lucroBruto} color={lucroCor} bold pct={d.margemBruta}/>
          <DRERow label="Saldo de Caixa" value={d.saldoCaixa} color={caixaCor} bold pct={d.margemCaixa}/>

          {!compact && d.obra.contractValue>0&&(<>
            <DRESection title="Posição do Contrato (Acumulado)" color={C.blue}/>
            <DRERow label="Contrato total"    value={d.contratoTotal}  color={C.subtle}/>
            <DRERow label="Faturado acumulado" value={d.faturadoAcum} color={C.blue}  pct={d.pctFaturado}/>
            <DRERow label="Recebido acumulado" value={d.recebidoAcum} color={C.green} pct={d.pctRecebido}/>
            <DRERow label="A receber (acum.)"  value={d.aReceberAcum} color={d.aReceberAcum>0?C.orange:C.muted}/>
            <DRERow label="Backlog disponível"  value={d.backlog}      color={d.backlog>0?C.yellow:C.muted}/>
            {/* Barra de progresso do contrato */}
            <div style={{padding:"8px 14px 4px"}}>
              <div style={{height:5,background:C.surface,borderRadius:99,overflow:"hidden",marginBottom:2}}>
                <div style={{height:"100%",width:`${Math.min(d.pctFaturado,100)}%`,background:C.blue,borderRadius:99}}/>
              </div>
              <div style={{height:3,background:C.surface,borderRadius:99,overflow:"hidden"}}>
                <div style={{height:"100%",width:`${Math.min(d.pctRecebido,100)}%`,background:C.green,borderRadius:99}}/>
              </div>
              <p style={{fontSize:"var(--arcd-type-caption)",color:C.muted,marginTop:3}}> Faturado {d.pctFaturado.toFixed(0)}%  <span style={{color:C.green}}></span> Recebido {d.pctRecebido.toFixed(0)}%</p>
            </div>
          </>)}

          {/* Outras despesas detalhadas */}
          {!compact && d.outrasDesp.length>0&&(
            <div style={{padding:"6px 14px 8px"}}>
              <p style={{fontSize:"var(--arcd-type-caption)",color:C.muted,textTransform:"uppercase",fontWeight:600,marginBottom:4}}>Detalhamento outras despesas</p>
              {d.outrasDesp.map(x=>(
                <div key={x.id} style={{display:"flex",justifyContent:"space-between",fontSize:"var(--arcd-type-label)",color:C.muted,padding:"2px 0"}}>
                  <span>{x.descricao||x.categoria} <span style={{color:C.muted,fontSize:"var(--arcd-type-caption)"}}>({fmtDateFull(x.competencia+"-01")})</span></span>
                  <div style={{display:"flex",gap:8,alignItems:"center"}}>
                    <span style={{color:C.orange,fontWeight:600}}>{fmt(x.valor)}</span>
                    <button disabled={expenseCommandPending} onClick={()=>delDesp(x.id)} style={{background:"transparent",border:0,color:C.muted,cursor:"pointer",fontSize:"var(--arcd-type-control)",padding:0}}>x</button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    );
  };

  //  PDF do DRE
  const gerarPDF = () => {
    const isConsolidado = view==="consolidado"||view==="historico";
    const titulo = isConsolidado ? `DRE Consolidado - ${period}` : `DRE ${dreObra.obra?.name||""} - ${period}`;

    const dreTableRows = (obj) => `
      <tr class="sec"><td colspan="2">RECEITAS</td></tr>
      <tr class="entry"><td>Faturamento emitido (medições)</td><td class="val pos">R$ ${fmt2(obj.faturamento)}</td></tr>
      <tr class="entry sub"><td>&nbsp;&nbsp;Recebido em caixa</td><td class="val">R$ ${fmt2(obj.recebido||0)}</td></tr>
      <tr class="entry sub"><td>&nbsp;&nbsp;A receber</td><td class="val warn">R$ ${fmt2(obj.aReceber||0)}</td></tr>
      ${(obj.equipReceita||0)>0?`<tr class="entry sub"><td>&nbsp;&nbsp;↳ inclui locação de equip. (líq.)</td><td class="val">R$ ${fmt2(obj.equipLucro||0)}</td></tr>`:""}
      <tr class="sec"><td colspan="2">CUSTOS DIRETOS</td></tr>
      <tr class="entry"><td>(-) Mão de obra própria</td><td class="val neg">R$ ${fmt2(obj.laborCost||obj.moData?.laborCost||0)}</td></tr>
      <tr class="entry sub"><td>&nbsp;&nbsp;(-) Benefícios (VT/VR)</td><td class="val">R$ ${fmt2(obj.benefitCost||obj.moData?.benefitCost||0)}</td></tr>
      <tr class="entry"><td>(-) Terceirizados${obj.tercEmpresa!==undefined?" (obras)":""}</td><td class="val neg">R$ ${fmt2(obj.tercCost||0)}</td></tr>
      ${(obj.tercEmpresa||0)>0?`<tr class="entry"><td>(-) Terceirizados (empresa)</td><td class="val neg">R$ ${fmt2(obj.tercEmpresa)}</td></tr>`:""}
      ${(obj.comprasCost||0)>0?`<tr class="entry"><td>(-) Materiais reconhecidos por nota fiscal</td><td class="val neg">R$ ${fmt2(obj.comprasCost)}</td></tr>`:""}
      ${(obj.tercEmpresaObra||0)>0?`<tr class="entry sub"><td>&nbsp;&nbsp;Terceirizados (empresa, referência)</td><td class="val">R$ ${fmt2(obj.tercEmpresaObra)}</td></tr>`:""}
      ${(obj.rescTotal||0)>0?`<tr class="entry"><td>(-) Rescisões</td><td class="val neg">R$ ${fmt2(obj.rescTotal)}</td></tr>`:""}
      ${(obj.equipCost||0)>0?`<tr class="entry"><td>(-) Locação de equipamentos</td><td class="val neg">R$ ${fmt2(obj.equipCost)}</td></tr>`:""}
      ${(obj.outrasTotal||0)>0?`<tr class="entry"><td>(-) Outras despesas</td><td class="val neg">R$ ${fmt2(obj.outrasTotal)}</td></tr>`:""}
      <tr class="subtotal"><td>Total Custos</td><td class="val neg">R$ ${fmt2(obj.totalCustos||0)}</td></tr>
      <tr class="result ${(obj.lucroBruto||0)>=0?"pos":"neg"}">
        <td><strong>LUCRO BRUTO</strong></td>
        <td class="val"><strong>R$ ${fmt2(obj.lucroBruto||0)} (${(obj.margemBruta||0).toFixed(1)}%)</strong></td>
      </tr>
      <tr class="result ${(obj.saldoCaixa||0)>=0?"caixa":"neg"}">
        <td>Saldo de Caixa</td>
        <td class="val">R$ ${fmt2(obj.saldoCaixa||0)} (${(obj.margemCaixa||0).toFixed(1)}%)</td>
      </tr>`;

    const obrasSect = isConsolidado ? dre.obras.map(o=>`
      <h3 style="font-size:13px;margin:18px 0 6px;border-bottom:1px solid #ddd;padding-bottom:4px">${escapeHtml(o.obra?.name||"")}</h3>
      <table class="dre-table"><tbody>${dreTableRows(o)}</tbody></table>`).join("") : "";

    const html = `<!DOCTYPE html><html><head><meta charset="UTF-8">
<title>${escapeHtml(titulo)}</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:Arial,sans-serif;color:#111;background:#fff;padding:28px;font-size:11px}
.print-btn{position:fixed;top:10px;right:10px;background:#080808;color:#f6d833;border:none;padding:10px 18px;font-size:13px;font-weight:700;cursor:pointer}
.page-header{display:flex;align-items:center;gap:16px;padding-bottom:14px;border-bottom:3px solid #080808;margin-bottom:20px}
.logo-box{background:#080808;color:#f6d833;padding:10px 16px;font-family:Georgia,serif;font-size:24px;font-weight:900;letter-spacing:2px;flex-shrink:0}
.company h1{font-size:16px;font-weight:900}.company p{font-size:10px;color:#666;margin-top:2px}
.period{font-size:18px;font-weight:900;text-align:right;flex:1}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 0;page-break-inside:avoid}
.kpi{border:1px solid #ddd;padding:10px 12px;border-top:3px solid #999}
.kpi.green{border-top-color:#16a34a}.kpi.blue{border-top-color:#2563eb}.kpi.red{border-top-color:#dc2626}.kpi.purple{border-top-color:#9333ea}
.kpi-l{font-size:9px;font-weight:700;text-transform:uppercase;color:#777;letter-spacing:.5px}
.kpi-v{font-size:16px;font-weight:900;margin-top:4px}
.dre-table{width:100%;border-collapse:collapse;margin:10px 0}
.dre-table td{padding:5px 8px;border-bottom:1px solid #f0f0f0;font-size:11px}
.dre-table td.val{text-align:right;font-weight:700;min-width:120px}
.dre-table .pos{color:#16a34a}.dre-table .neg{color:#dc2626}.dre-table .warn{color:#d97706}.dre-table .caixa{color:#2563eb}
.dre-table .sec td{background:#f3f4f6;font-weight:700;font-size:9px;text-transform:uppercase;letter-spacing:.7px;color:#555;padding:4px 8px}
.dre-table .sub td{color:#888;font-style:italic}
.dre-table .subtotal td{font-weight:900;background:#fef2f2;border-top:2px solid #fca5a5}
.dre-table .result td{font-size:13px;font-weight:900;border-top:2px solid #111}
.dre-table .result.pos td{color:#16a34a}.dre-table .result.neg td{color:#dc2626}.dre-table .result.caixa td{color:#2563eb}
h2{font-size:14px;font-weight:900;margin:20px 0 8px;text-transform:uppercase;letter-spacing:.8px;border-bottom:1.5px solid #111;padding-bottom:5px}
h3{font-size:12px;font-weight:900;color:#2563eb}
.footer{margin-top:28px;text-align:center;font-size:9px;color:#bbb;border-top:1px solid #eee;padding-top:8px}
@media print{.print-btn{display:none!important}}
</style></head>
<body>
<button class="print-btn" onclick="window.print()"> Imprimir / PDF</button>
<div class="page-header">
  <div class="logo-box">ArcD</div>
  <div class="company">
    <h1>${escapeHtml(data.config.companyName||"ArcD Construtora")}</h1>
    ${data.config.cnpj?`<p>CNPJ: ${escapeHtml(data.config.cnpj)}</p>`:""}
    <p>DRE Gerencial - Demonstrativo de Resultado</p>
  </div>
  <div class="period">${escapeHtml(titulo.split("-").pop())}</div>
</div>

<div class="kpis">
  <div class="kpi green"><p class="kpi-l">Faturamento</p><p class="kpi-v">R$ ${fmt2(dre.faturamento)}</p></div>
  <div class="kpi blue"><p class="kpi-l">Recebido</p><p class="kpi-v">R$ ${fmt2(dre.recebido)}</p></div>
  <div class="kpi red"><p class="kpi-l">Total Custos</p><p class="kpi-v">R$ ${fmt2(dre.totalCustos)}</p></div>
  <div class="kpi ${dre.lucroBruto>=0?"green":"red"}"><p class="kpi-l">Lucro Bruto</p><p class="kpi-v">R$ ${fmt2(dre.lucroBruto)}</p></div>
</div>

<h2>${isConsolidado?"DRE Consolidado":"DRE - "+escapeHtml(dreObra.obra?.name||"")}</h2>
<table class="dre-table"><tbody>${dreTableRows(isConsolidado?dre:dreObra)}</tbody></table>

${isConsolidado&&dre.obras.length>1?`<h2>Detalhamento por Obra</h2>${obrasSect}`:""}

<div class="footer">Gerado por MARCELL · ${new Date().toLocaleString("pt-BR")}</div>
</body></html>`;
    const w=window.open("","_blank"); w.document.write(marcellReportHtml(html)); w.document.close();
  };

  //  Excel do DRE
  const exportXLS = async () => {
    await carregarXLSX();
    const wb = XLSX.utils.book_new();
    const dreRows = (obj) => [
      ["RECEITAS"],
      ["Faturamento emitido", obj.faturamento],
      ["Recebido em caixa",   obj.recebido||0],
      ["A receber",           obj.aReceber||0],
      ["CUSTOS DIRETOS"],
      ["(-) MO própria",      obj.laborCost||obj.moData?.laborCost||0],
      ["(-) Benefícios",      obj.benefitCost||obj.moData?.benefitCost||0],
      ["(-) Terceirizados",   obj.tercCost||0],
      ...((obj.tercEmpresa||0)>0 ? [["(-) Terceirizados (empresa)", obj.tercEmpresa]] : []),
      ...((obj.comprasCost||0)>0 ? [["(-) Materiais reconhecidos por nota fiscal", obj.comprasCost]] : []),
      ...((obj.tercEmpresaObra||0)>0 ? [["Terceirizados (empresa, referência)", obj.tercEmpresaObra]] : []),
      ["(-) Rescisões",       obj.rescTotal||0],
      ["(-) Outras despesas", obj.outrasTotal||0],
      ["Total Custos",        obj.totalCustos||0],
      ["LUCRO BRUTO",         obj.lucroBruto||0],
      ["Margem Bruta %",      (obj.margemBruta||0).toFixed(1)+"%"],
      ["Saldo de Caixa",      obj.saldoCaixa||0],
      ["Margem de Caixa %",   (obj.margemCaixa||0).toFixed(1)+"%"],
    ];
    const ws1=XLSX.utils.aoa_to_sheet([[`DRE Consolidado - ${period}`],[],["Linha","Valor"],...dreRows(dre)]);
    ws1["!cols"]=[30,14].map(w=>({wch:w}));
    XLSX.utils.book_append_sheet(wb,ws1,"DRE Consolidado");

    // Uma aba por obra
    dre.obras.forEach(o=>{
      if(!o.obra) return;
      const ws=XLSX.utils.aoa_to_sheet([[`DRE - ${o.obra.name} - ${period}`],[],["Linha","Valor"],...dreRows(o)]);
      ws["!cols"]=[30,14].map(w=>({wch:w}));
      XLSX.utils.book_append_sheet(wb,ws,(o.obra.name||"Obra").slice(0,30));
    });

    // Histórico
    const histHeader=["Mês","Faturamento","Recebido","Custos","Lucro Bruto","Margem %"];
    const histBody=hist.map(h=>[h.mes,h.faturamento,h.recebido,h.totalCustos,h.lucroBruto,h.margemBruta.toFixed(1)+"%"]);
    const wsH=XLSX.utils.aoa_to_sheet([["Histórico 6 meses"],[],histHeader,...histBody]);
    wsH["!cols"]=[14,14,12,12,14,10].map(w=>({wch:w}));
    XLSX.utils.book_append_sheet(wb,wsH,"Histórico");

    await XLSX.writeFile(wb,`arcd-dre-${year}-${String(month+1).padStart(2,"0")}.xlsx`);
    showToast("Excel DRE gerado!");
  };

  //  RENDER
  const mudarVisaoDRE = (proximaVisao) => {
    setView(proximaVisao);
    if (proximaVisao === "historico") setPeriodoDRE("mes");
  };

  return (
    <div className="anim dre-page" style={{display:"flex",flexDirection:"column",gap:14}}>

      <PageHero
        eyebrow="Demonstrativo gerencial"
        title="DRE por Obra"
        description="Faturamento, custos, resultado, caixa e posição dos contratos."
      />

      <section className="dre-toolbar" aria-label="Filtros e visualização do DRE">
        <div className="dre-toolbar-heading">
          <div>
            <p>Período de análise</p>
            <span>Escolha a competência e a mesma régua usada na folha.</span>
          </div>
          <span className="dre-toolbar-period">{period}</span>
        </div>

        <div className="dre-period-controls">
          <Sel label="Ano" value={String(year)} onChange={v=>setYear(Number(v))} options={years}/>
          <Sel label="Mês" value={String(month)} onChange={v=>setMonth(Number(v))} options={Array.from({length:12},(_,i)=>({v:String(i),l:fullMonth(i)}))}/>
          <Sel label="Apuração" value={periodoDRE} onChange={setPeriodoDRE} disabled={view==="historico"} options={[
            {v:"mes",l:"Mês completo (01 ao último dia)"},
            {v:"q1",l:"1ª quinzena da folha (06–20)"},
            {v:"q2",l:"2ª quinzena da folha (21–05)"},
          ]}/>
        </div>

        <div className="dre-period-note">
          <Ic n="info" s={14}/>
          <p><b>Base da mão de obra:</b> {periodoDRE==="mes"
            ?"mês civil. Inclui partes de três ciclos de folha; não deve ser comparado diretamente com uma única quinzena."
            :`mesmos dias da Folha de Pagamento: ${fmtDate(dreObra.per0||dre.per0)} a ${fmtDate(dreObra.perF||dre.perF)}.`}</p>
        </div>

        {!obraIdFixo&&<TabRow equal tabs={[
          ["consolidado","Consolidado","Visão geral de todas as obras"],
          ["obra","Por obra","Detalhamento individual"],
          ["historico","Evolução mensal","Comparativo dos últimos meses"],
        ]} active={view} onChange={mudarVisaoDRE}/>}
      </section>

      {/* KPI cards sempre visíveis */}
      <div className="dre-kpi-grid">
        {[
          ["faturamento","Faturamento",  dreResumo.faturamento,  C.green,  `${period}`],
          ["recebido","Recebido",     dreResumo.recebido,     C.blue,   `a receber: ${fmt(dreResumo.aReceber)}`],
          ["custos","Total Custos", dreResumo.totalCustos,  C.red,    `MO + terceiros + outros`],
          ["lucro","Lucro Bruto",  dreResumo.lucroBruto,   dreResumo.lucroBruto>=0?C.green:C.red, `margem ${dreResumo.margemBruta.toFixed(1)}%`],
        ].map(([k,l,v,c,s])=>(
          <button type="button" className="dre-kpi-card" key={l} onClick={()=>{setDetalheKpi(k);setFiltroDetalhe({busca:"",categoria:"todos",obra:"todas",ordem:"data_desc"});}} style={{"--dre-kpi-color":c}}>
            <p style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,color:C.muted,textTransform:"uppercase",letterSpacing:.8}}>{l}</p>
            <p style={{fontFamily:"var(--arcd-font-sans)",fontWeight:600,color:c,fontSize:"var(--arcd-type-page-title)",lineHeight:1.1,marginTop:4}}>{fmt(v)}</p>
            <span className="dre-kpi-footer"><span>{s}</span><b>Ver movimentos <Ic n="arrowRight" s={12}/></b></span>
          </button>
        ))}
      </div>

      {/*  VIEW: CONSOLIDADO  */}
      {view==="consolidado"&&(
        <div style={{display:"flex",flexDirection:"column",gap:6}}>
          <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,overflow:"hidden"}}>
            <div style={{padding:"8px 14px",background:`${C.green}10`,borderBottom:`1px solid ${C.line}`}}>
              <p style={{fontFamily:"var(--arcd-font-sans)",fontWeight:600,fontSize:"var(--arcd-type-card-title)",color:C.green,textTransform:"uppercase"}}>DRE Consolidado - {period}</p>
            </div>
            <DRESection title="Receitas" color={C.green}/>
            <DRERow label="Faturamento total" value={dre.faturamento} color={C.green} bold/>
            <DRERow label="Recebido em caixa"  value={dre.recebido}    color={C.blue}  indent={1}/>
            <DRERow label="A receber"           value={dre.aReceber}    color={dre.aReceber>0?C.orange:C.muted} indent={1}/>
            <DRESection title="Custos Diretos" color={C.red}/>
            <DRERow label={`(-) MO própria · ${dre.days?.length||0} dias no período`} value={dre.laborCost} color={C.orange} indent={1}/>
            <DRERow label="(-) Benefícios VT/VR" value={dre.benefitCost}  color={C.muted}  indent={1}/>
            <DRERow label="(-) Terceirizados (obras)" value={dre.tercCost}     color={C.purple} indent={1}/>
            {dre.tercEmpresa>0&&<DRERow label="(-) Terceirizados (empresa)" value={dre.tercEmpresa} color={C.purple} indent={1}/>}
            {dre.comprasCost>0&&<DRERow label="(-) Materiais reconhecidos por nota fiscal" value={dre.comprasCost} color={C.yellowD} indent={1}/>}
            {dre.rescTotal>0&&<DRERow label="(-) Rescisões" value={dre.rescTotal} color={C.red} indent={1}/>}
            {dre.outrasTotal>0&&<DRERow label="(-) Outras despesas" value={dre.outrasTotal} color={C.orange} indent={1}/>}
            <DRERow label="Total custos" value={dre.totalCustos} color={C.red} bold/>
            <DRESeparator/>
            <DRERow label="LUCRO BRUTO" value={dre.lucroBruto} color={dre.lucroBruto>=0?C.green:C.red} bold pct={dre.margemBruta}/>
            <DRERow label="Saldo de Caixa" value={dre.saldoCaixa} color={dre.saldoCaixa>=0?C.blue:C.red} bold pct={dre.margemCaixa}/>
            <DRESection title="Posição Acumulada (Todas as Obras)" color={C.blue}/>
            <DRERow label="Faturado acumulado" value={dre.faturadoAcum} color={C.blue}/>
            <DRERow label="Recebido acumulado" value={dre.recebidoAcum} color={C.green}/>
            <DRERow label="Backlog disponível"  value={dre.backlog}      color={dre.backlog>0?C.yellow:C.muted}/>
          </div>

          {/* Gráfico: Faturamento vs Lucro 6 meses */}
          <Suspense fallback={<div className="arcd-page-loading">Carregando gráfico...</div>}>
            <LazyDreFaturamentoResultadoChart hist={hist}/>
          </Suspense>

          {/* Distribuição de custos */}
          <Suspense fallback={<div className="arcd-page-loading">Carregando gráfico...</div>}>
            <LazyDreDistribuicaoCustosChart dre={dre}/>
          </Suspense>

          {/* Por obra compact */}
          <p style={{fontSize:"var(--arcd-type-label)",fontWeight:600,color:C.muted,textTransform:"uppercase",letterSpacing:1}}>Resumo por obra</p>
          {dre.obras.map(o=>renderObraDRE(o,true))}
        </div>
      )}

      {/*  VIEW: POR OBRA  */}
      {view==="obra"&&(
        <div style={{display:"flex",flexDirection:"column",gap:10}}>
          {!obraIdFixo&&<div className="dre-work-selector">
            <Sel label="Obra em análise" value={selObra} onChange={setSelObra} options={data.obras.map(o=>({v:o.id,l:o.name}))}/>
          </div>}
          <section className="dre-ai-full-report" style={{marginTop:0}}>
            <header>
              <div><p>Gemini · direção financeira</p><h3>Avaliação do CFO</h3></div>
              <button type="button" onClick={analisarObraComoCFO} disabled={avaliandoCFOObra}><Ic n="brain" s={12}/> {avaliandoCFOObra?"Analisando...":avaliacaoCFOObra?"Atualizar avaliação":"Analisar esta obra"}</button>
            </header>
            <div className="dre-ai-indicators">
              <div><span>Pessoas no período</span><strong>{equipeObra.pessoas}</strong><small>com presença registrada na obra</small></div>
              <div><span>Homem-dias</span><strong>{equipeObra.homemDias.toFixed(1)}</strong><small>presenças integrais e meios dias</small></div>
              <div><span>Custo de mão de obra</span><strong>{fmt(dreObra.moData.laborCost+dreObra.moData.benefitCost)}</strong><small>folha e benefícios no período</small></div>
              <div><span>Histórico analisado</span><strong>6 meses</strong><small>faturamento, caixa, custo e margem</small></div>
            </div>
            {!avaliacaoCFOObra?<p style={{fontSize:"var(--arcd-type-label)",color:C.muted,lineHeight:1.55,marginTop:10}}>O CFO cruza resultado, caixa, custo da equipe, homem-dias e evolução mensal. Quando faltarem avanço físico ou produção executada, ele indicará que não há base para afirmar excesso de pessoal.</p>:<>
              <div className="dre-ai-conclusion" style={{marginTop:10}}><span>Veredicto · {avaliacaoCFOObra.veredicto||"inconclusivo"}</span><p>{avaliacaoCFOObra.avaliacao}</p></div>
              <div className="dre-ai-diagnosis-grid">
                <article><span>Mão de obra · {avaliacaoCFOObra.maoDeObra?.veredicto||"inconclusivo"}</span><p>{avaliacaoCFOObra.maoDeObra?.analise}</p><small>{avaliacaoCFOObra.maoDeObra?.decisao}</small></article>
                <article><span>Evolução mês a mês · {avaliacaoCFOObra.historico?.tendencia||"inconclusiva"}</span><p>{avaliacaoCFOObra.historico?.leitura}</p><small>Melhor: {avaliacaoCFOObra.historico?.melhorMes||"—"} · Pior: {avaliacaoCFOObra.historico?.piorMes||"—"}</small></article>
              </div>
              <p className="dre-ai-report-label">Decisões recomendadas</p>
              <div className="dre-ai-action-plan">{(avaliacaoCFOObra.decisoes||[]).map((x,i)=><article key={`${x.prioridade}-${i}`}><span>{x.prazo}</span><div><strong>{x.prioridade}. {x.acao}</strong><small>{x.impactoEsperado} · Indicador: {x.indicador}</small></div></article>)}</div>
              {avaliacaoCFOObra.conclusao&&<div className="dre-ai-conclusion"><span>Conclusão do CFO</span><p>{avaliacaoCFOObra.conclusao}</p></div>}
              {(avaliacaoCFOObra.dadosFaltantes||[]).length>0&&<><p className="dre-ai-report-label">Dados necessários para uma decisão mais precisa</p><ul>{avaliacaoCFOObra.dadosFaltantes.map((x,i)=><li key={i}>{x}</li>)}</ul></>}
            </>}
          </section>
          {renderObraDRE(dreObra,false)}
        </div>
      )}

      {/*  VIEW: HISTÓRICO  */}
      {view==="historico"&&(
        <div style={{display:"flex",flexDirection:"column",gap:10}}>
          <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,overflow:"hidden"}}>
            <div style={{padding:"8px 14px",borderBottom:`1px solid ${C.line}`,display:"grid",gridTemplateColumns:"1fr 1fr 1fr 1fr 1fr",gap:4}}>
              {["Mês","Faturamento","Recebido","Lucro","Margem"].map(h=>(
                <p key={h} style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,color:C.muted,textTransform:"uppercase"}}>{h}</p>
              ))}
            </div>
            {hist.map((h,i)=>(
              <div key={i} style={{
                padding:"8px 14px",borderBottom:i<hist.length-1?`1px solid ${C.line}22`:"none",
                display:"grid",gridTemplateColumns:"1fr 1fr 1fr 1fr 1fr",gap:4,
                background:h.m===month&&h.y===year?`${C.yellow}0a`:"transparent",
              }}>
                <p style={{fontSize:"var(--arcd-type-body)",fontWeight:h.m===month&&h.y===year?600:500,color:h.m===month&&h.y===year?C.yellow:C.text}}>{h.mes}{h.m===month&&h.y===year?" ":""}</p>
                <p style={{fontSize:"var(--arcd-type-body)",color:C.green,fontWeight:600}}>{fmt(h.faturamento)}</p>
                <p style={{fontSize:"var(--arcd-type-body)",color:C.blue}}>{fmt(h.recebido)}</p>
                <p style={{fontSize:"var(--arcd-type-body)",color:h.lucroBruto>=0?C.green:C.red,fontWeight:600}}>{fmt(h.lucroBruto)}</p>
                <p style={{fontSize:"var(--arcd-type-body)",color:h.margemBruta>=0?C.green:C.red,fontWeight:600}}>{h.margemBruta.toFixed(1)}%</p>
              </div>
            ))}
          </div>
          {/* Gráfico margem */}
          <Suspense fallback={<div className="arcd-page-loading">Carregando gráfico...</div>}>
            <LazyDreMargemChart hist={hist}/>
          </Suspense>
        </div>
      )}

      {/* Botão: lançar outras despesas */}
      <button onClick={()=>{setDespForm({obraId:obraFinanceiraId||data.obras[0]?.id||"",competencia:`${year}-${String(month+1).padStart(2,"0")}`,categoria:"material",descricao:"",valor:""});setDespModal(true);}} style={{
        background:`${C.orange}10`,border:`1px dashed ${C.orange}66`,borderRadius:8,
        color:C.orange,padding:"10px 14px",cursor:"pointer",fontFamily:"var(--arcd-font-sans)",
        fontWeight:600,fontSize:"var(--arcd-type-control)",letterSpacing:.5,textAlign:"left",display:"flex",alignItems:"center",gap:8,
      }}>
        <Ic n="plus" color={C.orange}/> Lançar outras despesas (materiais, equipamentos, taxas...)
      </button>

      {/* Outras despesas do mês */}
      {(data.outrasDesp||[]).filter(d=>d.competencia===`${year}-${String(month+1).padStart(2,"0")}`&&(!obraIdFixo||d.obraId===obraIdFixo)).length>0&&(
        <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,overflow:"hidden"}}>
          <div style={{padding:"8px 14px",borderBottom:`1px solid ${C.line}`,background:`${C.orange}10`}}>
            <p style={{fontFamily:"var(--arcd-font-sans)",fontWeight:600,fontSize:"var(--arcd-type-body)",color:C.orange,textTransform:"uppercase"}}>Outras despesas - {period}</p>
          </div>
          {(data.outrasDesp||[]).filter(d=>d.competencia===`${year}-${String(month+1).padStart(2,"0")}`&&(!obraIdFixo||d.obraId===obraIdFixo)).map(d=>(
            <div key={d.id} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"9px 14px",borderBottom:`1px solid ${C.line}22`}}>
              <div>
                <p style={{fontSize:"var(--arcd-type-body)",fontWeight:600}}>{d.descricao||d.categoria}</p>
                <p style={{fontSize:"var(--arcd-type-label)",color:C.muted}}>{rotuloCategoria(data, d.categoria)}  {data.obras.find(o=>o.id===d.obraId)?.name||"-"}</p>
              </div>
              <div style={{display:"flex",gap:8,alignItems:"center"}}>
                <p style={{color:C.orange,fontWeight:600}}>{fmt(d.valor)}</p>
                <Btn size="sm" v="danger" disabled={expenseCommandPending} onClick={()=>delDesp(d.id)}><Ic n="trash"/></Btn>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Exportações */}
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
        <Btn onClick={gerarPDF} v="danger" full><Ic n="file"/> DRE PDF</Btn>
        <Btn onClick={exportXLS} v="success" full><Ic n="download"/> Excel Completo</Btn>
      </div>

      {detalheKpi&&(
        <Modal title={{
          faturamento:"Detalhamento do faturamento",recebido:"Recebimentos do período",
          custos:"Pagamentos e custos do período",lucro:"Composição do lucro bruto",
        }[detalheKpi]} onClose={()=>setDetalheKpi("")} wide>
          <div className="dre-detail">
            <div className="dre-detail-context">
              <div>
                <p>{period}</p>
                <span>{view==="obra" ? dreObra.obra?.name : "Todas as obras"} · movimentos em ordem cronológica</span>
              </div>
              <strong>{fmt(movimentosDetalhe.reduce((s,x)=>s+x.valorExibido,0))}</strong>
            </div>
            <div className="dre-detail-filters">
              <label className="dre-detail-search">
                <span>Buscar</span>
                <input value={filtroDetalhe.busca} onChange={e=>setFiltroDetalhe(f=>({...f,busca:e.target.value}))} placeholder="Descrição, obra ou documento"/>
              </label>
              <Sel label="Categoria" value={filtroDetalhe.categoria} onChange={v=>setFiltroDetalhe(f=>({...f,categoria:v}))}
                options={[{v:"todos",l:"Todas"},...Array.from(new Set(movimentosDRE.map(x=>x.categoria))).sort().map(x=>({v:x,l:x}))]}/>
              {!obraIdFixo&&view!=="obra"&&<Sel label="Obra" value={filtroDetalhe.obra} onChange={v=>setFiltroDetalhe(f=>({...f,obra:v}))}
                options={[{v:"todas",l:"Todas as obras"},...data.obras.map(o=>({v:o.id,l:o.name}))]}/>}
              <Sel label="Ordenar" value={filtroDetalhe.ordem} onChange={v=>setFiltroDetalhe(f=>({...f,ordem:v}))} options={[
                {v:"data_desc",l:"Mais recentes"},{v:"data_asc",l:"Mais antigos"},
                {v:"valor_desc",l:"Maior valor"},{v:"valor_asc",l:"Menor valor"},
              ]}/>
            </div>
            <div className="dre-detail-list" role="table" aria-label="Movimentos financeiros">
              <div className="dre-detail-row dre-detail-head" role="row">
                <span>Data</span><span>Movimento</span><span>Obra</span><span>Categoria</span><span>Valor</span>
              </div>
              {movimentosDetalhe.length ? movimentosDetalhe.map(x=>(
                <div className="dre-detail-row" role="row" key={x.id}>
                  <span data-label="Data">{fmtDate(x.data)}</span>
                  <span data-label="Movimento"><b>{x.descricao}</b>{x.documento&&<small>{x.documento}</small>}</span>
                  <span data-label="Obra">{x.obra}</span>
                  <span data-label="Categoria"><em>{x.categoria}</em></span>
                  <span data-label="Valor" className={x.valorExibido<0?"is-negative":"is-positive"}>{fmt(x.valorExibido)}</span>
                </div>
              )):<div className="dre-detail-empty"><Ic n="search" s={20}/><p>Nenhum movimento encontrado com estes filtros.</p></div>}
            </div>
          </div>
        </Modal>
      )}

      {/* Modal: outras despesas */}
      <DesignSystemDialog open={despModal} onOpenChange={setDespModal} title="Lançar Outras Despesas">
        <div style={{display:"grid",gap:10}}>
          {obraIdFixo
            ? <DesignSystemInput label="Obra" value={data.obras.find(o=>o.id===obraIdFixo)?.name||"Obra atual"} onChange={()=>{}} disabled/>
            : <DesignSystemSelect label="Obra" required value={despForm.obraId} onChange={e=>DF("obraId")(e.target.value)} options={[{value:"",label:"Selecione"},...data.obras.map(o=>({value:o.id,label:o.name}))]}/>
          }
          <DesignSystemInput label="Competência (mês/ano)" required type="month" value={despForm.competencia} onChange={e=>DF("competencia")(e.target.value)}/>
          <DesignSystemSelect label="Categoria" required value={despForm.categoria} onChange={e=>DF("categoria")(e.target.value)} options={categoriasDesp(data).map(c=>({value:c.v,label:c.l}))}/>
          <DesignSystemInput label="Descrição" value={despForm.descricao} onChange={e=>DF("descricao")(e.target.value)} placeholder="Ex.: Concreto fck 25 - 20m, Andaime locado..."/>
          <DesignSystemInput label="Valor (R$)" required type="number" value={despForm.valor} onChange={e=>DF("valor")(e.target.value)} placeholder="0,00"/>
          {despForm.categoria==="material" && ["admin_only","fixed_labor_admin"].includes(
            (data.obras.find(o=>o.id===(obraIdFixo||despForm.obraId))||{}).contractType
          ) && (
            <div>
              <p style={{fontSize:"var(--arcd-type-label)",fontWeight:600,color:C.subtle,textTransform:"uppercase",marginBottom:5}}>Este material entra na taxa de administração?</p>
              <div style={{display:"flex",gap:8}}>
                <DesignSystemButton size="sm" variant={despForm.contaAdmin!==false?"success":"ghost"} onClick={()=>DF("contaAdmin")(true)} style={{flex:1}}>Sim, entra</DesignSystemButton>
                <DesignSystemButton size="sm" variant={despForm.contaAdmin===false?"danger":"ghost"} onClick={()=>DF("contaAdmin")(false)} style={{flex:1}}>Não entra</DesignSystemButton>
              </div>
              <p style={{fontSize:"var(--arcd-type-caption)",color:C.muted,marginTop:5,lineHeight:1.4}}>Material comprado direto pelo cliente ou já embutido no contrato, por exemplo, não deve entrar na base do percentual de administração.</p>
            </div>
          )}
          <div style={{display:"flex",gap:8}}>
            <DesignSystemButton variant="ghost" onClick={()=>setDespModal(false)} style={{flex:1}}>Cancelar</DesignSystemButton>
            <DesignSystemButton disabled={expenseCommandPending} onClick={saveDesp} style={{flex:1}}><Ic n="check"/> {expenseCommandPending?"Salvando...":"Lançar"}</DesignSystemButton>
          </div>
        </div>
      </DesignSystemDialog>
    </div>
  );
}



