//
// FLUXO DE CAIXA
//

function FluxoCaixa({ data, year, month, obraId="all" }) {
  // Extrai primitivos: `new Date()` gera um objeto novo a cada render, então
  // usá-lo direto na lista de dependências faria o memo recalcular sempre.
  const _hoje = new Date();
  const nowY = year ?? _hoje.getFullYear();
  const nowM = month ?? _hoje.getMonth();
  const actualYear=_hoje.getFullYear(),actualMonth=_hoje.getMonth();
  const [months, setMonths] = useState(6);

  // Calcula histórico real + projeção futura
  const cashflow = useMemo(() => {
    const result = [];
    const ledger = buildFinancialLedger(data);
    for (let i = -(months-1); i <= 3; i++) {
      const d = new Date(nowY, nowM+i, 1);
      const y = d.getFullYear();
      const m = d.getMonth();
      const ym = `${y}-${String(m+1).padStart(2,"0")}`;
      const mdays = getDays(y, m);
      const isFuture = d > new Date(actualYear, actualMonth, 1);

      if (!isFuture) {
        const inicio = mdays[0] || `${ym}-01`;
        const fim = mdays[mdays.length-1] || `${ym}-31`;
        const caixa = selectLedgerCashFlow(ledger, { startDate:inicio, endDate:fim, ...(obraId==="all"?{}:{obraId}), includeCorporate:obraId==="all" });
        result.push({
          mes:monthName(m)+"/"+String(y).slice(2),
          received:caixa.cashIn, totalOut:caixa.cashOut, balance:caixa.balance,
          isProjection:false, isCurrent:i===0,
        });
      } else {
        // Projeção
        const workDays = mdays.filter(d=>{const wd=new Date(d+"T12:00:00").getDay();return wd>=1&&wd<=6;}).length;
        const activeEmps = data.employees.filter(e=>e.active!==false&&(obraId==="all"||e.obra===obraId));
        const laborEst = activeEmps.reduce((s,e)=>s+Number(e.dailyRate||0)*workDays*0.82,0);
        const tercEst = (data.terceirizados||[]).filter(t=>t.active!==false&&(obraId==="all"||t.obraId===obraId)).reduce((s,t)=>s+Number(t.weeklyRate||0)*4.3,0);
        // Projeção de meses futuros: só estima com base na MO (sem materiais e
        // terceirizados futuros, que não têm como ser projetados aqui). Para
        // obras admin_only/fixed_labor_admin isso subestima a receita prevista
        // - é uma aproximação grosseira só para o gráfico de fluxo de caixa;
        // o valor real e auditável fica no fechamento por competência em
        // Medições (MedicoesView).
        const revenueEst = data.obras.filter(o=>o.status!=="done"&&(obraId==="all"||o.id===obraId)).reduce((s,o)=>{const{laborCost}=calcObraLaborCost(data,o.id,mdays);return s+calcObraRevenue(o,laborCost).revenue;},0);
        result.push({ mes: monthName(m)+"/"+String(y).slice(2), received: revenueEst, laborCost: laborEst, tercCost: tercEst, totalOut: laborEst+tercEst, balance: revenueEst-(laborEst+tercEst), isProjection: true, isCurrent: false });
      }
    }
    return result;
  }, [data, months, nowY, nowM, obraId,actualYear,actualMonth]);

  const maxVal = Math.max(...cashflow.map(c=>Math.max(c.received,c.totalOut,1)));
  const totalReceived = cashflow.filter(c=>!c.isProjection).reduce((s,c)=>s+c.received,0);
  const totalOut = cashflow.filter(c=>!c.isProjection).reduce((s,c)=>s+c.totalOut,0);
  const projReceived = cashflow.filter(c=>c.isProjection).reduce((s,c)=>s+c.received,0);
  const projOut = cashflow.filter(c=>c.isProjection).reduce((s,c)=>s+c.totalOut,0);

  return (
    <div style={{display:"flex",flexDirection:"column",gap:12}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <div>
          <p style={{fontSize:"var(--arcd-type-label)",fontWeight:600,color:C.blue,textTransform:"uppercase",letterSpacing:1}}>Histórico + Projeção</p>
          <h3 style={{fontFamily:"var(--arcd-font-sans)",fontWeight:600,fontSize:"var(--arcd-type-page-title)",letterSpacing:1.5,color:C.text}}>Fluxo de Caixa</h3><p>Referência: {fullMonth(nowM)} {nowY} · {obraId==="all"?"Todas as obras":data.obras.find(o=>o.id===obraId)?.name}. Janela de {months} meses até a referência e 3 meses seguintes. Valores posteriores ao mês atual são estimativas.</p>
        </div>
        <Sel value={String(months)} onChange={v=>setMonths(Number(v))} options={[{v:"3",l:"3 meses"},{v:"6",l:"6 meses"},{v:"12",l:"12 meses"}]}/>
      </div>

      {/* KPIs */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:8}}>
        {[
          ["Recebido (real)", fmt(totalReceived),    C.green],
          ["Saída (real)",    fmt(totalOut),          C.red],
          ["Receita proj.",   fmt(projReceived),      C.blue],
          ["Saída proj.",     fmt(projOut),           C.orange],
        ].map(([l,v,c])=>(
          <div key={l} style={{background:C.card,border:`1px solid ${C.border}`,borderTop:`3px solid ${c}`,padding:"10px 12px",borderRadius:10}}>
            <p style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,color:C.muted,textTransform:"uppercase"}}>{l}</p>
            <p style={{fontFamily:"var(--arcd-font-sans)",fontWeight:600,color:c,fontSize:"var(--arcd-type-section-title)",lineHeight:1.1,marginTop:3}}>{v}</p>
          </div>
        ))}
      </div>

      {/* Gráfico visual (barras CSS customizadas) */}
      <div style={{background:C.card,border:`1px solid ${C.border}`,padding:14,borderRadius:12}}>
        <p style={{fontSize:"var(--arcd-type-label)",fontWeight:600,color:C.muted,textTransform:"uppercase",letterSpacing:.8,marginBottom:12}}>Receita x Saída por mês</p>
        <div style={{display:"flex",gap:6,alignItems:"flex-end",height:140}}>
          {cashflow.map((c,i)=>{
            const hRec = Math.round((c.received/maxVal)*120);
            const hOut = Math.round((c.totalOut/maxVal)*120);
            const isPos = c.balance >= 0;
            return (
              <div key={i} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",gap:3}}>
                <div style={{display:"flex",gap:2,alignItems:"flex-end",height:120}}>
                  <div style={{width:12,height:hRec||2,background:c.isProjection?C.blue+"88":C.green,borderRadius:"3px 3px 0 0",transition:"height .3s"}}/>
                  <div style={{width:12,height:hOut||2,background:c.isProjection?C.orange+"88":C.red,borderRadius:"3px 3px 0 0",transition:"height .3s"}}/>
                </div>
                <p style={{fontSize:"var(--arcd-type-caption)",color:c.isCurrent?C.yellow:c.isProjection?C.blue:C.muted,fontWeight:c.isCurrent?600:600,textAlign:"center",whiteSpace:"nowrap"}}>{c.mes}</p>
                <div style={{width:12,height:3,background:isPos?C.green:C.red,borderRadius:99}}/>
              </div>
            );
          })}
        </div>
        <div style={{display:"flex",gap:12,marginTop:10,flexWrap:"wrap"}}>
          {[[" Recebido/Proj",C.green],[" Saída/Proj",C.red],[" Projeção",C.blue+"88"]].map(([l,c])=>(
            <p key={l} style={{fontSize:"var(--arcd-type-label)",color:c,fontWeight:600}}>{l}</p>
          ))}
          <p style={{fontSize:"var(--arcd-type-label)",color:C.muted}}> Saldo (verde=positivo)</p>
        </div>
      </div>

      {/* Tabela mês a mês */}
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,overflow:"hidden"}}>
        <div style={{padding:"10px 14px",borderBottom:`1px solid ${C.line}`,display:"grid",gridTemplateColumns:"1.2fr 1fr 1fr 1fr",gap:4}}>
          {["Mês","Entradas","Saídas","Saldo"].map(h=>(
            <p key={h} style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,color:C.muted,textTransform:"uppercase"}}>{h}</p>
          ))}
        </div>
        {cashflow.map((c,i)=>(
          <div key={i} style={{
            padding:"9px 14px",
            borderBottom:i<cashflow.length-1?`1px solid ${C.line}`:"none",
            display:"grid",gridTemplateColumns:"1.2fr 1fr 1fr 1fr",gap:4,
            background:c.isCurrent?`${C.yellow}0a`:c.isProjection?`${C.blue}07`:"transparent",
          }}>
            <p style={{fontSize:"var(--arcd-type-body)",fontWeight:c.isCurrent?600:600,color:c.isCurrent?C.yellow:c.isProjection?C.blue:C.text}}>
              {c.mes}{c.isProjection?" *":""}{c.isCurrent?" ":""}
            </p>
            <p style={{fontSize:"var(--arcd-type-body)",color:C.green,fontWeight:600}}>{fmt(c.received)}</p>
            <p style={{fontSize:"var(--arcd-type-body)",color:C.red}}>{fmt(c.totalOut)}</p>
            <p style={{fontSize:"var(--arcd-type-body)",color:c.balance>=0?C.green:C.red,fontWeight:600}}>{fmt(c.balance)}</p>
          </div>
        ))}
        <div style={{padding:"8px 14px",background:C.surface,borderTop:`2px solid ${C.line}`}}>
          <p style={{fontSize:"var(--arcd-type-caption)",color:C.muted}}>* Projeção: MO estimada com 82% de presença · Terceiros com 4,3 semanas/mês</p>
        </div>
      </div>
    </div>
  );
}

// A tela de Terceiros (cadastro e pagamentos semanais) foi extraída para
// src/domains/terceirizados/components/TerceirosView.jsx em 2026-08-15 -
// importada como `Terceiros` abaixo, mesmo nome de sempre.

export const compLabel = ym => {
  if (!ym) return "-";
  const [y, m] = ym.split("-");
  return `${fullMonth(Number(m)-1)} ${y}`;
};

//
// Relatórios
//

// Relatório financeiro consolidado do caixa de obra: uma linha por obra com
// caixa ativado, saldo/aportes/gastos e um PDF por obra (mesmo template já
// usado dentro da tela Caixa de Obra).
function RelatorioCaixaObra({ data, showToast }) {
  const obrasComCaixa = useMemo(() => (data.obras||[]).filter(o=>o.hasCaixa), [data.obras]);
  const linhas = useMemo(() => obrasComCaixa.map(o => ({ obra:o, ...calcCaixaObra(data,o.id) })),
    [obrasComCaixa, data.caixaObra]);
  const totalAportes  = linhas.reduce((s,l)=>s+l.totalAportes,0);
  const totalDespesas = linhas.reduce((s,l)=>s+l.totalDespesas,0);
  const totalSaldo    = linhas.reduce((s,l)=>s+l.saldo,0);

  if (!obrasComCaixa.length) {
    return (
      <div style={{padding:24,textAlign:"center",border:`1px dashed ${C.border}`,borderRadius:10,color:C.muted,fontSize:"var(--arcd-type-label)"}}>
        Nenhuma obra com caixa ativado. Ative em <strong>Obras</strong> · "Esta obra possui caixa de obra".
      </div>
    );
  }

  return (
    <div style={{display:"flex",flexDirection:"column",gap:10}}>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(165px,1fr))",gap:8}}>
        <ReportMetric label="Total de aportes" value={fmt(totalAportes)} color={C.green} icon="download"/>
        <ReportMetric label="Total de gastos" value={fmt(totalDespesas)} color={C.red} icon="cart"/>
        <ReportMetric label="Saldo consolidado" value={fmt(totalSaldo)} color={totalSaldo>=0?C.green:C.red} icon="wallet"/>
      </div>
      <div style={{display:"flex",flexDirection:"column",gap:7}}>
        {linhas.map(l => (
          <div key={l.obra.id} style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:9,padding:"11px 13px",display:"flex",justifyContent:"space-between",alignItems:"center",gap:10,flexWrap:"wrap"}}>
            <div>
              <p style={{fontSize:"var(--arcd-type-label)",fontWeight:600,color:C.text}}>{l.obra.name}</p>
              <p style={{fontSize:"var(--arcd-type-caption)",color:C.muted,marginTop:2}}>{l.movimentos.length} lançamento(s) · aportes {fmt(l.totalAportes)} · gastos {fmt(l.totalDespesas)}</p>
            </div>
            <div style={{display:"flex",alignItems:"center",gap:10}}>
              <b style={{fontSize:"var(--arcd-type-card-title)",color:l.saldo>=0?C.green:C.red}}>{fmt(l.saldo)}</b>
              <Btn size="sm" v="ghost" onClick={()=>gerarRelatorioCaixaObraPDF(data,l.obra,l,showToast)}><Ic n="download" s={12}/> PDF</Btn>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function gerarRelatorioComprasPDF(data, { inicio, fim, obraId, origem, linhas, totais }, showToast) {
  const obraNomeSel = obraId === "all" ? "Todas as obras" : (data.obras||[]).find(o=>o.id===obraId)?.name || "-";
  const origemSel = origem === "todas" ? "Todos" : origemPagamentoLabel(origem);
  const html = montarRelatorioPadraoHtml({
    data,
    titulo: "Relatório de compras",
    subtitulo: `${fmtDateFull(inicio)} a ${fmtDateFull(fim)}`,
    meta: [
      { label: "Obra", value: obraNomeSel },
      { label: "Quem pagou", value: origemSel },
    ],
    kpis: [
      { label: "Total comprado", value: fmt(totais.comprado) },
      { label: "Total pago", value: fmt(totais.pago) },
      { label: "Saldo a pagar", value: fmt(totais.pendente) },
      { label: "Itens no período", value: String(linhas.length) },
    ],
    tabelas: [{
      headers: ["Data","Pedido","Obra","Fornecedor","Item",{label:"Qtd",num:true},{label:"Preço unit.",num:true},{label:"Subtotal",num:true},"Quem pagou","Status"],
      rows: linhas.map(l => [
        escapeHtml(fmtDateFull(l.data)), escapeHtml(l.numero), escapeHtml(l.obra), escapeHtml(l.fornecedor),
        escapeHtml(l.item), escapeHtml(`${l.qtd} ${l.unidade}`), escapeHtml(fmt(l.precoUnit)), escapeHtml(fmt(l.subtotal)),
        escapeHtml(l.origemPagamento), escapeHtml(l.statusLabel),
      ]),
      totalRow: ["","","","","","","TOTAL", fmt(totais.comprado), "", ""],
      vazio: "Nenhuma compra encontrada neste filtro.",
    }],
  });
  abrirRelatorioPadrao(html, showToast);
}

function RelatorioCompras({ data, showToast }) {
  const [inicio, setInicio] = useState(() => `${new Date().getFullYear()}-${String(new Date().getMonth()+1).padStart(2,"0")}-01`);
  const [fim, setFim] = useState(() => today());
  const [obraId, setObraId] = useState("all");
  const [origem, setOrigem] = useState("todas");

  const obraPorIdC = useMemo(() => new Map((data.obras||[]).map(o=>[o.id,o])), [data.obras]);
  const fornecedorPorId = useMemo(() => new Map((data.fornecedores||[]).map(f=>[f.id,f])), [data.fornecedores]);
  const materialPorId = useMemo(() => new Map((data.materiais||[]).map(m=>[m.id,m])), [data.materiais]);

  const linhas = useMemo(() => {
    const out = [];
    (data.pedidos||[]).forEach(p => {
      if (p.status === "cancelado") return;
      if (!p.data || p.data < inicio || p.data > fim) return;
      if (obraId!=="all" && p.obraId!==obraId) return;
      const origemPag = p.origemPagamento || "empresa";
      if (origem!=="todas" && origemPag!==origem) return;
      const statusPag = statusPagamentoPedido(p);
      const statusLabel = statusPag==="pago"?"Pago":statusPag==="parcial"?"Parcial":statusPag==="cancelado"?"Cancelado":"Pendente";
      (p.itens||[]).forEach(item => {
        const nomeItem = materialPorId.get(item.materialId)?.descricao || item.descricaoRef || "Item";
        const subtotal = Number(item.qtd||0) * Number(item.precoUnit||0);
        out.push({
          pedidoId: p.id, numero: p.numero||"-", data: p.data,
          obra: obraPorIdC.get(p.obraId)?.name || "-",
          fornecedor: fornecedorPorId.get(p.fornecedorId)?.nome || "-",
          item: nomeItem, unidade: item.unidadeRef||"-",
          qtd: Number(item.qtd||0), precoUnit: Number(item.precoUnit||0), subtotal,
          origemPagamento: origemPagamentoLabel(origemPag),
          statusLabel,
        });
      });
    });
    return out.sort((a,b)=>String(b.data||"").localeCompare(String(a.data||"")));
  }, [data.pedidos, obraPorIdC, fornecedorPorId, materialPorId, inicio, fim, obraId, origem]);

  const totais = useMemo(() => {
    const comprado = linhas.reduce((s,l)=>s+l.subtotal,0);
    const pago = linhas.filter(l=>l.statusLabel==="Pago").reduce((s,l)=>s+l.subtotal,0);
    return { comprado, pago, pendente: comprado - pago };
  }, [linhas]);

  return (
    <div style={{display:"flex",flexDirection:"column",gap:10}}>
      <div className="no-print" style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(150px,1fr))",gap:8}}>
        <Inp label="De" type="date" value={inicio} onChange={setInicio}/>
        <Inp label="Até" type="date" value={fim} onChange={setFim}/>
        <Sel label="Obra" value={obraId} onChange={setObraId} options={[{v:"all",l:"Todas as obras"},...(data.obras||[]).map(o=>({v:o.id,l:o.name}))]}/>
        <Sel label="Quem pagou" value={origem} onChange={setOrigem} options={[{v:"todas",l:"Todos"},{v:"empresa",l:origemPagamentoLabel("empresa")},{v:"caixa_obra",l:origemPagamentoLabel("caixa_obra")},{v:"cliente_direto",l:origemPagamentoLabel("cliente_direto")}]}/>
      </div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(165px,1fr))",gap:8}}>
        <ReportMetric label="Total comprado" value={fmt(totais.comprado)} color={C.blue} icon="cart"/>
        <ReportMetric label="Total pago" value={fmt(totais.pago)} color={C.green} icon="check"/>
        <ReportMetric label="Saldo a pagar" value={fmt(totais.pendente)} color={totais.pendente>0?C.orange:C.green} icon="wallet"/>
      </div>
      <div className="no-print" style={{display:"flex",justifyContent:"flex-end"}}>
        <Btn size="sm" v="ghost" onClick={()=>gerarRelatorioComprasPDF(data,{inicio,fim,obraId,origem,linhas,totais},showToast)}><Ic n="download" s={12}/> Exportar PDF</Btn>
      </div>
      <div className="scroll-x" style={{border:`1px solid ${C.border}`,borderRadius:9,overflow:"hidden"}}>
        <table style={{width:"100%",minWidth:900,borderCollapse:"collapse",background:C.card}}>
          <thead><tr>{["Data","Pedido","Obra","Fornecedor","Item","Qtd","Preço unit.","Subtotal","Quem pagou","Status"].map(h=><th key={h} style={{padding:"7px 8px",textAlign:["Qtd","Preço unit.","Subtotal"].includes(h)?"right":"left",fontSize:"var(--arcd-type-label)",color:C.muted,textTransform:"uppercase",borderBottom:`1px solid ${C.border}`}}>{h}</th>)}</tr></thead>
          <tbody>{linhas.map((l,i)=><tr key={`${l.pedidoId}-${i}`} style={{borderTop:`1px solid ${C.line}`}}>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)",color:C.muted,whiteSpace:"nowrap"}}>{fmtDate(l.data)}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)",fontWeight:600,color:C.blue}}>{l.numero}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)"}}>{l.obra}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)"}}>{l.fornecedor}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)",maxWidth:220,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{l.item}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)",textAlign:"right",whiteSpace:"nowrap"}}>{l.qtd} {l.unidade}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)",textAlign:"right"}}>{fmt(l.precoUnit)}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)",fontWeight:600,textAlign:"right"}}>{fmt(l.subtotal)}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)"}}>{l.origemPagamento}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)"}}><Badge color={l.statusLabel==="Pago"?C.green:l.statusLabel==="Parcial"?C.orange:l.statusLabel==="Cancelado"?C.red:C.muted}>{l.statusLabel}</Badge></td>
          </tr>)}</tbody>
        </table>
        {!linhas.length&&<div style={{padding:24,textAlign:"center",color:C.muted,fontSize:"var(--arcd-type-label)"}}>Nenhuma compra encontrada neste filtro.</div>}
      </div>
    </div>
  );
}

function gerarRelatorioAdministracaoPDF(data, { period, linhas, totais }, showToast) {
  const html = montarRelatorioPadraoHtml({
    data,
    titulo: "Previsão de recebimento por administração",
    subtitulo: period,
    kpis: [
      { label: "Previsto no período", value: fmt(totais.previsto) },
      { label: "Já fechado nas medições", value: fmt(totais.fechado) },
      { label: "Pendente de fechamento", value: fmt(totais.pendente) },
      { label: "Obras por administração", value: String(linhas.length) },
    ],
    tabelas: [{
      headers: ["Obra","Modalidade",{label:"% Admin.",num:true},{label:"Mão de obra",num:true},{label:"Materiais",num:true},{label:"Terceirizados",num:true},{label:"Base calculada",num:true},{label:"Previsto",num:true},{label:"Já fechado",num:true},{label:"Pendente",num:true}],
      rows: linhas.map(l => [
        escapeHtml(l.obra.name), escapeHtml(CONTRACT_LABELS[l.obra.contractType]||l.obra.contractType),
        escapeHtml(`${l.ap}%`),
        escapeHtml(`${fmt(l.laborBase)}${l.incluiMaoDeObra?"":" (não entra)"}`),
        escapeHtml(`${fmt(l.materialCost)}${l.incluiMateriais?"":" (não entra)"}`),
        escapeHtml(`${fmt(l.tercCost)}${l.incluiTerceirizados?"":" (não entra)"}`),
        escapeHtml(fmt(l.adminBase)), escapeHtml(fmt(l.valorAdmin)),
        escapeHtml(fmt(l.jaFechado)), escapeHtml(fmt(l.pendente)),
      ]),
      totalRow: ["","","","","","", "", fmt(totais.previsto), fmt(totais.fechado), fmt(totais.pendente)],
      vazio: "Nenhuma obra por administração encontrada.",
    }],
    legenda: "Base calculada = soma apenas das categorias configuradas no cadastro de cada obra (materiais, mão de obra e/ou terceirizados). Compras via pedidos e terceirizados pagos pela empresa para a obra já estão incluídos nos valores de materiais e terceirizados.",
  });
  abrirRelatorioPadrao(html, showToast);
}

// Documento voltado ao cliente, para justificar a cobrança da administração
// de uma obra específica no período - só entram as categorias efetivamente
// configuradas para esta obra (cadastro de Obras).
function gerarRelatorioCobrancaAdministracaoPDF(data, { l, period }, showToast) {
  const obra = l.obra;
  const composicao = [
    { label: "Mão de obra e benefícios", valor: l.laborBase, incluido: l.incluiMaoDeObra },
    { label: "Materiais (lançamentos e compras)", valor: l.materialCost, incluido: l.incluiMateriais },
    { label: "Terceirizados", valor: l.tercCost, incluido: l.incluiTerceirizados },
  ];
  if (obra.contractType === "admin_only" && l.outrosCustos > 0) {
    composicao.push({ label: "Equipamentos, rescisões e outras despesas", valor: l.outrosCustos, incluido: true });
  }
  const html = montarRelatorioPadraoHtml({
    data,
    titulo: "Relatório de cobrança - administração de obra",
    subtitulo: `${obra.name} · ${period}`,
    paisagem: false,
    meta: [
      { label: "Cliente", value: obra.cliente || "Não informado" },
      { label: "Obra", value: obra.name },
      { label: "Endereço", value: obra.address || "-" },
      { label: "Modalidade", value: CONTRACT_LABELS[obra.contractType] || obra.contractType },
    ],
    kpis: [
      { label: "Base de cálculo", value: fmt(l.adminBase) },
      { label: "% de administração", value: `${l.ap}%` },
      { label: "Valor da administração", value: fmt(l.valorAdmin) },
      { label: "Já fechado nas medições", value: fmt(l.jaFechado) },
    ],
    tabelas: [{
      titulo: "Composição dos custos do período",
      headers: ["Categoria",{label:"Valor gasto",num:true},"Entra na base de administração?"],
      rows: composicao.map(c => [escapeHtml(c.label), escapeHtml(fmt(c.valor)), c.incluido?"Sim":"Não"]),
      totalRow: ["Base de administração ($ × %)", fmt(l.adminBase), `${l.ap}% = ${fmt(l.valorAdmin)}`],
    }],
    legenda: `Valor calculado como ${l.ap}% sobre a base de administração definida no contrato desta obra. Categorias marcadas "Não" não entram no cálculo, conforme configurado no cadastro da obra.`,
    assinaturas: ["Responsável pela construtora", `Representante · ${obra.cliente || "cliente"}`],
  });
  abrirRelatorioPadrao(html, showToast);
}

function RelatorioAdministracao({ data, year, month, showToast }) {
  const obrasAdmin = useMemo(() => (data.obras||[])
    .filter(o => o.contractType==="admin_only" || o.contractType==="fixed_labor_admin"),
    [data.obras]);

  const linhas = useMemo(() => {
    return obrasAdmin.map(obra => {
      const projection = calcProjecaoContratoObra(data, obra.id, year, month);
      const laborBase = projection.laborCost + projection.benefitCost;
      // Usa exclusivamente a configuração salva no cadastro da obra (nenhum
      // filtro deste relatório sobrescreve o que foi definido lá).
      const {
        adminBase, incluiMaoDeObra, incluiMateriais, incluiTerceirizados,
        outrosCustos, adminEligibleMaterialCost, tercCost, jaFechado,
      } = projection;
      const ap = Number(obra.adminPercentage||0);
      const valorAdmin = adminBase * (ap/100);
      return {
        obra, ap, adminBase, valorAdmin, jaFechado, pendente: Math.max(0, valorAdmin-jaFechado),
        // Usa o material líquido (já descontando lançamentos marcados "não
        // entra na taxa de administração"), não o bruto - senão a soma das
        // linhas "Sim" deste relatório não bate com a base de fato cobrada.
        laborBase, materialCost: adminEligibleMaterialCost, tercCost, outrosCustos,
        incluiMaoDeObra, incluiMateriais, incluiTerceirizados,
      };
    });
  }, [obrasAdmin, year, month, data]);

  const totais = useMemo(() => ({
    previsto: linhas.reduce((s,l)=>s+l.valorAdmin,0),
    fechado:  linhas.reduce((s,l)=>s+l.jaFechado,0),
    pendente: linhas.reduce((s,l)=>s+l.pendente,0),
  }), [linhas]);

  const period = `${fullMonth(month)} · ${year}`;
  const celulaCategoria = (valor, incluido) => (
    <span style={{color:incluido?C.text:C.muted,textDecoration:incluido?"none":"line-through"}}>{fmt(valor)}</span>
  );

  return (
    <div style={{display:"flex",flexDirection:"column",gap:10}}>
      <p style={{fontSize:"var(--arcd-type-label)",color:C.muted}}>A base de cálculo usa exatamente o que está configurado no cadastro de cada obra (Obras → Contrato financeiro). Valores riscados não entram na base dessa obra.</p>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(165px,1fr))",gap:8}}>
        <ReportMetric label="Previsto no período" value={fmt(totais.previsto)} color={C.purple} icon="dollar"/>
        <ReportMetric label="Já fechado nas medições" value={fmt(totais.fechado)} color={C.green} icon="check"/>
        <ReportMetric label="Pendente de fechamento" value={fmt(totais.pendente)} color={totais.pendente>0?C.orange:C.green} icon="wallet"/>
      </div>
      <div className="no-print" style={{display:"flex",justifyContent:"flex-end"}}>
        <Btn size="sm" v="ghost" onClick={()=>gerarRelatorioAdministracaoPDF(data,{ period, linhas, totais },showToast)}><Ic n="download" s={12}/> Exportar PDF</Btn>
      </div>
      <div className="scroll-x" style={{border:`1px solid ${C.border}`,borderRadius:9,overflow:"hidden"}}>
        <table style={{width:"100%",minWidth:1050,borderCollapse:"collapse",background:C.card}}>
          <thead><tr>{["Obra","Modalidade","% Admin.","Mão de obra","Materiais","Terceirizados","Base calculada","Previsto","Já fechado","Pendente","Ações"].map(h=><th key={h} style={{padding:"7px 8px",textAlign:["Obra","Modalidade","Ações"].includes(h)?"left":"right",fontSize:"var(--arcd-type-label)",color:C.muted,textTransform:"uppercase",borderBottom:`1px solid ${C.border}`}}>{h}</th>)}</tr></thead>
          <tbody>{linhas.map(l=><tr key={l.obra.id} style={{borderTop:`1px solid ${C.line}`}}>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)",fontWeight:600}}>{l.obra.name}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)",color:C.muted}}>{CONTRACT_LABELS[l.obra.contractType]||l.obra.contractType}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)",textAlign:"right"}}>{l.ap}%</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)",textAlign:"right"}}>{celulaCategoria(l.laborBase,l.incluiMaoDeObra)}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)",textAlign:"right"}}>{celulaCategoria(l.materialCost,l.incluiMateriais)}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)",textAlign:"right"}}>{celulaCategoria(l.tercCost,l.incluiTerceirizados)}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)",textAlign:"right",fontWeight:600}}>{fmt(l.adminBase)}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)",fontWeight:600,textAlign:"right",color:C.purple}}>{fmt(l.valorAdmin)}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)",textAlign:"right",color:C.green}}>{fmt(l.jaFechado)}</td>
            <td style={{padding:"7px 8px",fontSize:"var(--arcd-type-table)",textAlign:"right",fontWeight:600,color:l.pendente>0?C.orange:C.green}}>{fmt(l.pendente)}</td>
            <td style={{padding:"7px 8px"}}><Btn size="sm" v="ghost" onClick={()=>gerarRelatorioCobrancaAdministracaoPDF(data,{l,period},showToast)}><Ic n="download" s={11}/> Cobrança</Btn></td>
          </tr>)}</tbody>
        </table>
        {!linhas.length&&<div style={{padding:24,textAlign:"center",color:C.muted,fontSize:"var(--arcd-type-label)"}}>Nenhuma obra por administração (admin_only ou mista) encontrada.</div>}
      </div>
    </div>
  );
}

function Relatorios({ data, showToast, currentUser }) {
  const [section,setSection]=useState("monthly");
  const canViewProjection=["admin","rh","financeiro"].includes(currentUser?.role);
  return <div>
    {canViewProjection&&<FlowTabs label="Relatórios de mão de obra" active={section} onChange={setSection}
      steps={[{id:"monthly",label:"Relatórios mensais"},{id:"projection",label:"Projeção de mão de obra"}]}/>}
    {section==="projection"&&canViewProjection
      ?<LaborProjectionReport requestReport={obterProjecaoMaoObra}/>
      :<RelatoriosMensais data={data} showToast={showToast}/>}
  </div>;
}

function RelatoriosMensais({ data, showToast }) {
  const [year, setYear] = useState(new Date().getFullYear());
  const [month, setMonth] = useState(new Date().getMonth());
  const [filterObra, setFilterObra] = useState("all");
  const [view, setView] = useState("custos"); // "custos" | "relatorio"

  const days = useMemo(() => getDays(year, month), [year, month]);
  const obraPorIdRel = useMemo(() => new Map(data.obras.map(o => [o.id, o])), [data.obras]);
  const obraName = id => obraPorIdRel.get(id)?.name || "-";
  const payrollHolidays = useMemo(() => getPayrollHolidays(data, year), [data.config?.paymentHolidays, year]);
  const holidaysInMonth = useMemo(() => days.filter(d => payrollHolidays.includes(d) && prIsWeekdayIso(d)),
    [days, payrollHolidays]);
  const obraCostRows = useMemo(() => data.obras.map(o => {
    const activeEmps = data.employees.filter(e => e.active !== false && e.obra === o.id);

    let presentes = 0;
    let meiodia = 0;
    let faltas = 0;
    let semRegistro = 0;
    let holidayPay = 0;

    data.employees.forEach(e => {
      days.forEach(d => {
        if (!isEmployeeEmployedOnDate(e, d)) return;
        if (holidaysInMonth.includes(d)) return;

        const a = getAtt(data, e.id, d);
        const obraDoDia = resolveEmployeeAttendanceObraId({
          data,
          employee:e,
          date:d,
          record:a,
        });
        if (obraDoDia !== o.id) return;
        const s = a?.status;

        if (s === "P") {
          presentes++;
        } else if (s === "M") {
          meiodia++;
        } else if (s === "F") {
          faltas++;
        } else if (isLeaveStatus(s)) {
          // Afastamento (férias/atestado/folga): não é falta nem pendência.
        } else if (e.obra === o.id && e.active !== false) {
          semRegistro++;
        }
      });

      holidaysInMonth.forEach(h => {
        if (!isEmployeeEmployedOnDate(e, h)) return;
        if (resolveHolidayObraId({ data, employee:e, holidayIso:h }) !== o.id) return;
        const rule = getHolidayPayRule(data, e, h, payrollHolidays);
        holidayPay += Number(rule.amount || 0);
      });
    });

    // Fonte única dos valores: a mesma função consumida pelo DRE, incluindo
    // hora extra, benefício, obra gravada no ponto e custos arquivados.
    const { laborCost, benefitCost, totalCost } = calcObraLaborCost(data, o.id, days);
    const areaM2 = Number(o.areaM2 || 0);
    const laborCostPerM2 = areaM2 > 0 ? laborCost / areaM2 : 0;
    const totalCostPerM2 = areaM2 > 0 ? totalCost / areaM2 : 0;

    return {
      id: o.id,
      name: o.name,
      areaM2,
      trabalhadores: activeEmps.length,
      presentes,
      meiodia,
      faltas,
      semRegistro,
      laborCost,
      benefitCost,
      holidayPay,
      totalCost,
      laborCostPerM2,
      totalCostPerM2,
    };
  }), [data, days, holidaysInMonth, payrollHolidays]);

  const filteredRows = obraCostRows.filter(r => filterObra === "all" || r.id === filterObra);

  const totals = filteredRows.reduce((acc, r) => ({
    areaM2: acc.areaM2 + r.areaM2,
    trabalhadores: acc.trabalhadores + r.trabalhadores,
    presentes: acc.presentes + r.presentes,
    meiodia: acc.meiodia + r.meiodia,
    faltas: acc.faltas + r.faltas,
    semRegistro: acc.semRegistro + r.semRegistro,
    laborCost: acc.laborCost + r.laborCost,
    benefitCost: acc.benefitCost + r.benefitCost,
    holidayPay: acc.holidayPay + r.holidayPay,
    totalCost: acc.totalCost + r.totalCost,
  }), {
    areaM2: 0,
    trabalhadores: 0,
    presentes: 0,
    meiodia: 0,
    faltas: 0,
    semRegistro: 0,
    laborCost: 0,
    benefitCost: 0,
    holidayPay: 0,
    totalCost: 0,
  });

  const totalLaborCostPerM2 = totals.areaM2 > 0 ? totals.laborCost / totals.areaM2 : 0;
  const totalCostPerM2 = totals.areaM2 > 0 ? totals.totalCost / totals.areaM2 : 0;

  const byObra = filteredRows.map(r => ({
    id: r.id,
    name: r.name,
    trabalhadores: r.trabalhadores,
    presentes: r.presentes,
    faltas: r.faltas,
    custo: r.laborCost,
    custoTotal: r.totalCost,
    custoM2: r.laborCostPerM2,
  }));

  const topCost = useMemo(() => data.employees.map(e => {
    let total = 0;

    days.forEach(d => {
      if (!isEmployeeEmployedOnDate(e, d)) return;
      if (holidaysInMonth.includes(d)) return;
      const record = getAtt(data, e.id, d);
      const obraDoDia = resolveEmployeeAttendanceObraId({
        data,
        employee:e,
        date:d,
        record,
      });
      if (filterObra !== "all" && obraDoDia !== filterObra) return;
      total += calculateAttendanceDayCost({ employee:e, record, config:data.config }).laborCost;
    });

    holidaysInMonth.forEach(h => {
      if (!isEmployeeEmployedOnDate(e, h)) return;
      const obraDoDia = resolveHolidayObraId({ data, employee:e, holidayIso:h });
      if (filterObra !== "all" && obraDoDia !== filterObra) return;
      total += Number(getHolidayPayRule(data, e, h, payrollHolidays).amount || 0);
    });

    return { name: e.name, obra: obraName(e.obra), total };
  }).filter(i => i && i.total > 0).sort((a, b) => b.total - a.total).slice(0, 10),
    [data, filterObra, days, holidaysInMonth, payrollHolidays, obraPorIdRel]);

  const exportObraCosts = async () => {
    await carregarXLSX();
    const wb = XLSX.utils.book_new();
    const ws = XLSX.utils.aoa_to_sheet([
      ["Relatório de gasto por obra", `${fullMonth(month)} ${year}`],
      ["Filtro", filterObra === "all" ? "Todas as obras" : obraName(filterObra)],
      [],
      [
        "Obra",
        "Área (m)",
        "Trabalhadores ativos",
        "Presenças",
        "Meio dia",
        "Faltas",
        "Sem registro",
        "Mão de obra",
        "Feriados pagos",
        "VT/VR",
        "Total com benefícios",
        "Mão de obra por m",
        "Total por m",
      ],
      ...filteredRows.map(r => [
        r.name,
        r.areaM2,
        r.trabalhadores,
        r.presentes,
        r.meiodia,
        r.faltas,
        r.semRegistro,
        r.laborCost,
        r.holidayPay,
        r.benefitCost,
        r.totalCost,
        r.laborCostPerM2,
        r.totalCostPerM2,
      ]),
      [
        "TOTAL",
        totals.areaM2,
        totals.trabalhadores,
        totals.presentes,
        totals.meiodia,
        totals.faltas,
        totals.semRegistro,
        totals.laborCost,
        totals.holidayPay,
        totals.benefitCost,
        totals.totalCost,
        totalLaborCostPerM2,
        totalCostPerM2,
      ],
    ]);

    ws["!cols"] = [22, 10, 16, 10, 10, 10, 12, 14, 14, 12, 18, 18, 14].map(w => ({ wch: w }));
    XLSX.utils.book_append_sheet(wb, ws, "Gasto por Obra");
    await XLSX.writeFile(wb, `arcd-gasto-obra-${year}-${String(month + 1).padStart(2, "0")}.xlsx`);
  };

  const [chartMode, setChartMode] = useState("custos");
  const [highlightObra, setHighlightObra] = useState("");

  return (
    <div className="anim" style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      <PageHero
        eyebrow="Inteligência gerencial"
        title="Relatórios e inteligência"
        description="Custos, produtividade e presença em uma leitura técnica unificada."
        actions={<span style={{display:"inline-flex",padding:"5px 8px",border:`1px solid ${C.border}`,borderRadius:5,background:C.surface,color:C.yellowD,fontSize:"var(--arcd-type-caption)",fontWeight:600,letterSpacing:.3}}>{fullMonth(month)} · {year}</span>}
      />

      <div className="no-print" style={{display:"flex",flexWrap:"wrap",gap:8,alignItems:"center"}}>
        <TabRow tabs={[["custos","Painel analítico"],["relatorio","Relatório executivo"],["caixa","Caixa de obra"],["compras","Relatório de compras"],["administracao","Recebimento por administração"]]} active={view} onChange={setView}/>
        <div style={{display:"flex",gap:8,marginLeft:"auto"}}>
          <Sel value={String(month)} onChange={v => setMonth(Number(v))} options={Array.from({ length: 12 }, (_, i) => ({ v: String(i), l: fullMonth(i) }))} />
          <Sel value={String(year)} onChange={v => setYear(Number(v))} options={Array.from({ length: 4 }, (_, i) => new Date().getFullYear() - 1 + i).map(y => ({ v: String(y), l: String(y) }))} />
        </div>
      </div>

      {/*  RELATÓRIO MENSAL COMPLETO  */}
      {view === "relatorio" && <RelatorioMensal data={data} year={year} month={month} showToast={showToast}/>}

      {/*  CAIXA DE OBRA  */}
      {view === "caixa" && <RelatorioCaixaObra data={data} showToast={showToast}/>}

      {/*  RELATÓRIO DE COMPRAS  */}
      {view === "compras" && <RelatorioCompras data={data} showToast={showToast}/>}

      {/*  RECEBIMENTO POR ADMINISTRAÇÃO  */}
      {view === "administracao" && <RelatorioAdministracao data={data} year={year} month={month} showToast={showToast}/>}

      {/*  INDICADORES (view padrão)  */}
      {view === "custos" && <>
      <div className="no-print" style={{display:"flex",alignItems:"end",gap:8,flexWrap:"wrap"}}><div style={{flex:"1 1 250px"}}><Sel label="Escopo da análise" value={filterObra} onChange={v=>{setFilterObra(v);setHighlightObra(v==="all"?"":v);}} options={[{ v: "all", l: "Todas as obras" }, ...data.obras.map(o => ({ v: o.id, l: o.name }))]}/></div><Btn onClick={exportObraCosts} v="ghost"><Ic n="download" s={14}/> Exportar base</Btn></div>

      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(165px,1fr))",gap:8}}>
        <ReportMetric label="Mão de obra" value={fmt(totals.laborCost)} detail={`${totals.trabalhadores} profissionais ativos`} color={C.yellow} icon="users"/>
        <ReportMetric label="Custo por m²" value={totals.areaM2>0?fmt(totalLaborCostPerM2):"Sem área"} detail={`${totals.areaM2.toLocaleString("pt-BR")} m² analisados`} color={totals.areaM2>0?C.green:C.muted} icon="ruler"/>
        <ReportMetric label="Custo total" value={fmt(totals.totalCost)} detail={`${fmt(totals.benefitCost)} em VT/VR`} color={C.blue} icon="wallet"/>
        <ReportMetric label="Registros críticos" value={totals.faltas+totals.semRegistro} detail={`${totals.faltas} faltas · ${totals.semRegistro} sem registro`} color={(totals.faltas+totals.semRegistro)>0?C.red:C.green} icon="alert"/>
      </div>

      <Suspense fallback={<div className="arcd-page-loading">Carregando gráfico...</div>}>
        <LazyRelatoriosChartPanel byObra={byObra} chartMode={chartMode} setChartMode={setChartMode} highlightObra={highlightObra} setHighlightObra={setHighlightObra}/>
      </Suspense>

      <div style={{ display: "flex", flexDirection: "column", gap: 7 }}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:8}}><p style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,letterSpacing:1,textTransform:"uppercase",color:C.muted}}>Leitura técnica por obra</p>{highlightObra&&<button onClick={()=>setHighlightObra("")} style={{border:0,background:"transparent",color:C.yellowD,fontSize:"var(--arcd-type-control)",fontWeight:600,cursor:"pointer"}}>Limpar destaque</button>}</div>
        {[...filteredRows].sort((a,b)=>(b.id===highlightObra)-(a.id===highlightObra)).map(r => (
          <div key={r.id} onClick={()=>setHighlightObra(r.id)} className="lift-card" style={{ background:C.card,border:`1px solid ${highlightObra===r.id?C.yellow:C.line}`,borderRadius:12,padding:13,cursor:"pointer",opacity:highlightObra&&highlightObra!==r.id?0.72:1,boxShadow:highlightObra===r.id?`0 8px 24px ${C.yellow}12`:C.shHair }}>
            <div style={{ display: "flex", justifyContent: "space-between", gap: 10, alignItems: "flex-start" }}>
              <div>
                <p style={{ fontFamily:FONT_DISPLAY, fontWeight:600,fontSize:"var(--arcd-type-card-title)" }}>{r.name}</p>
                <p style={{ color: C.muted, fontSize:"var(--arcd-type-label)",marginTop:2 }}>
                  Área: {r.areaM2 > 0 ? `${r.areaM2.toLocaleString("pt-BR")} m²` : "não cadastrada"} · {r.trabalhadores} trabalhador(es)
                </p>
                <p style={{ color: C.subtle, fontSize:"var(--arcd-type-label)",marginTop:2 }}>
                  {r.presentes} presentes · {r.meiodia} meios períodos · {r.faltas} faltas · {r.semRegistro} sem registro
                </p>
              </div>
              <div style={{ textAlign: "right" }}>
                <p style={{ color: C.yellow, fontWeight:600 }}>{fmt(r.laborCost)}</p>
                <p style={{ color: r.areaM2 > 0 ? C.green : C.muted, fontSize: "var(--arcd-type-body)", fontWeight:600 }}>
                  {r.areaM2 > 0 ? `${fmt(r.laborCostPerM2)}/m` : "sem m"}
                </p>
              </div>
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 6, marginTop: 10 }}>
              {[
                ["Feriados pagos", fmt(r.holidayPay), C.green],
                ["VT/VR", fmt(r.benefitCost), C.blue],
                ["Total", fmt(r.totalCost), C.yellow],
              ].map(([label, value, color]) => (
                <div key={label} style={{ background:C.surface,border:`1px solid ${C.line}`,borderRadius:8,padding:"7px 9px" }}>
                  <p style={{ fontSize:"var(--arcd-type-caption)",color:C.muted,textTransform:"uppercase",fontWeight:600,letterSpacing:.5 }}>{label}</p>
                  <p style={{ color:C.text,fontWeight:600,fontSize:"var(--arcd-type-body)",marginTop:2 }}>{value}</p>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 14 }}>
        <h3 style={{ fontFamily:FONT_DISPLAY, color: C.yellow, textTransform: "uppercase", marginBottom: 8 }}>Top custos do mês</h3>
        {topCost.length === 0 && <p style={{ color: C.muted, fontSize: "var(--arcd-type-body)" }}>Nenhum custo lançado no período.</p>}
        {topCost.map(i => (
          <div key={`${i.name}-${i.obra}`} style={{ borderTop: `1px solid ${C.border}`, padding: "9px 0", display: "flex", justifyContent: "space-between" }}>
            <div><p style={{ fontWeight:600 }}>{i.name}</p><p style={{ color: C.muted, fontSize: "var(--arcd-type-body)" }}>{i.obra}</p></div>
            <p style={{ color: C.yellow, fontWeight:600 }}>{fmt(i.total)}</p>
          </div>
        ))}
      </div>
      </> /* fim view==="custos" */}
    </div>
  );
}


//
// RELATÓRIO MENSAL COMPLETO POR OBRA
//

function RelatorioMensal({ data, year, month, showToast }) {
  const rows   = useMemo(() => calcRelatorioMensal(data, year, month), [year, month,
    data.obras, data.attendance, data.employees, data.pagsTerceiros, data.payments,
    data.terceirizados, data.outrasDesp, data.pedidos, data.medicoes, data.rescisoes,
    data.equipamentos, data.locacoesEquip, data.advances]);
  const period = `${fullMonth(month)} ${year}`;

  // Totais consolidados
  const tot = rows.reduce((acc, r) => ({
    received:       acc.received       + r.received,
    revenueEsp:     acc.revenueEsp     + r.revenueEsperada,
    laborCost:      acc.laborCost      + r.moData.laborCost,
    benefitCost:    acc.benefitCost    + r.moData.benefitCost,
    tercCost:       acc.tercCost       + r.tercCost,
    rescTotal:      acc.rescTotal      + r.rescTotal,
    adiantTotal:    acc.adiantTotal    + r.adiantTotal,
    totalDespesas:  acc.totalDespesas  + r.totalDespesas,
    margem:         acc.margem         + r.margem,
  }), { received:0, revenueEsp:0, laborCost:0, benefitCost:0, tercCost:0, rescTotal:0, adiantTotal:0, totalDespesas:0, margem:0 });

  //  PDF
  const gerarPDF = () => {
    const tabelaObra = r => ({
      titulo: r.obra.name,
      descricao: [
        `${CONTRACT_LABELS[r.obra.contractType]||"Contrato"} · ${r.activeEmps} func. ativos · ${r.activeTercs} terceiros · ${r.presencaDias} presenças`,
        r.tercDetalhes.length ? `Terceirizados pagos: ${r.tercDetalhes.map(p=>`${p.tercName||"-"} (${fmt(p.amount)}, ${fmtDateFull(p.date)})`).join("; ")}` : "",
        r.rescDetalhes.length ? `Rescisões: ${r.rescDetalhes.map(rd=>`${rd.empName||"-"} (${fmt(rd.totalLiquido)}, ${fmtDateFull(rd.demissao)})`).join("; ")}` : "",
      ].filter(Boolean).join(" — "),
      headers: ["Descrição", { label:"Valor", num:true }],
      rows: [
        ["(+) Receita recebida", escapeHtml(fmt(r.received))],
        ["(+) Receita esperada (contrato)", escapeHtml(fmt(r.revenueEsperada))],
        ["(-) Mão de obra própria", escapeHtml(fmt(r.moData.laborCost))],
        ["(-) Benefícios (VT/VR)", escapeHtml(fmt(r.moData.benefitCost))],
        ["(-) Terceirizados", escapeHtml(fmt(r.tercCost))],
        ...(r.rescTotal>0 ? [["(-) Rescisões", escapeHtml(fmt(r.rescTotal))]] : []),
        ...(r.adiantTotal>0 ? [["(-) Adiantamentos", escapeHtml(fmt(r.adiantTotal))]] : []),
        ["Total de despesas", escapeHtml(fmt(r.totalDespesas))],
        ["Margem esperada", escapeHtml(fmt(r.margemEsperada))],
      ],
      totalRow: [`Margem (${r.margemPct.toFixed(1)}%)`, escapeHtml(fmt(r.margem))],
    });

    const html = montarRelatorioPadraoHtml({
      data,
      titulo: "Relatório mensal",
      subtitulo: period,
      kpis: [
        { label: "Receita recebida", value: fmt(tot.received) },
        { label: "Custo MO própria", value: fmt(tot.laborCost+tot.benefitCost) },
        { label: "Terceiros + rescisões", value: fmt(tot.tercCost+tot.rescTotal) },
        { label: "Margem global", value: fmt(tot.margem) },
      ],
      tabelas: [
        ...rows.map(tabelaObra),
        {
          titulo: "Consolidado geral",
          headers: ["Descrição", { label:"Valor", num:true }],
          rows: [
            ["(+) Receita recebida total", escapeHtml(fmt(tot.received))],
            ["(+) Receita esperada total", escapeHtml(fmt(tot.revenueEsp))],
            ["(-) Mão de obra própria", escapeHtml(fmt(tot.laborCost))],
            ["(-) Benefícios (VT/VR)", escapeHtml(fmt(tot.benefitCost))],
            ["(-) Terceirizados", escapeHtml(fmt(tot.tercCost))],
            ...(tot.rescTotal>0 ? [["(-) Rescisões", escapeHtml(fmt(tot.rescTotal))]] : []),
            ...(tot.adiantTotal>0 ? [["(-) Adiantamentos", escapeHtml(fmt(tot.adiantTotal))]] : []),
            ["Total de despesas", escapeHtml(fmt(tot.totalDespesas))],
          ],
          totalRow: ["Margem global", escapeHtml(fmt(tot.margem))],
        },
      ],
    });
    abrirRelatorioPadrao(html, showToast);
  };

  //  Excel
  const exportXLS = async () => {
    await carregarXLSX();
    const wb = XLSX.utils.book_new();

    // Aba 1 - Resumo consolidado
    const ws1 = XLSX.utils.aoa_to_sheet([
      [`Relatório Mensal - ${period}`],
      [`Empresa: ${data.config.companyName||"ArcD"}`],
      [],
      ["Indicador","Valor"],
      ["Receita recebida",        tot.received],
      ["Receita esperada",        tot.revenueEsp],
      ["(-) Mão de obra própria", tot.laborCost],
      ["(-) Benefícios",          tot.benefitCost],
      ["(-) Terceirizados",       tot.tercCost],
      ["(-) Rescisões",           tot.rescTotal],
      ["(-) Adiantamentos",       tot.adiantTotal],
      ["Total despesas",          tot.totalDespesas],
      ["Margem global",           tot.margem],
    ]);
    ws1["!cols"] = [{wch:28},{wch:16}];
    XLSX.utils.book_append_sheet(wb, ws1, "Resumo");

    // Aba 2 - Detalhe por obra
    const header2 = ["Obra","Tipo Contrato","Recebido","Receita Esp.","MO Própria","Benefícios","Terceiros","Rescisões","Adiantamentos","Total Desp.","Margem","Margem %","Presenças","Faltas","Func.Ativos","Terceiros Ativos"];
    const body2 = rows.map(r=>[
      r.obra.name,
      CONTRACT_LABELS[r.obra.contractType]||r.obra.contractType,
      r.received, r.revenueEsperada,
      r.moData.laborCost, r.moData.benefitCost,
      r.tercCost, r.rescTotal, r.adiantTotal, r.totalDespesas,
      r.margem, r.margemPct.toFixed(1)+"%",
      r.presencaDias, r.faltas, r.activeEmps, r.activeTercs,
    ]);
    const total2 = ["TOTAL","",tot.received,tot.revenueEsp,tot.laborCost,tot.benefitCost,tot.tercCost,tot.rescTotal,tot.adiantTotal,tot.totalDespesas,tot.margem,"","","","",""];
    const ws2 = XLSX.utils.aoa_to_sheet([[`Detalhe por obra - ${period}`],[],header2,...body2,total2]);
    ws2["!cols"] = [22,16,12,12,12,12,12,12,12,12,12,10,10,8,10,12].map(w=>({wch:w}));
    XLSX.utils.book_append_sheet(wb, ws2, "Por Obra");

    // Aba 3 - Pagamentos recebidos
    const h3=["Data","Obra","Valor","Descrição"];
    const b3=rows.flatMap(r=>r.recDetalhes.map(p=>[p.date, r.obra.name, p.amount, p.description]));
    const ws3=XLSX.utils.aoa_to_sheet([[`Pagamentos recebidos - ${period}`],[],h3,...b3]);
    ws3["!cols"]=[12,22,12,30].map(w=>({wch:w}));
    XLSX.utils.book_append_sheet(wb, ws3, "Recebimentos");

    // Aba 4 - Terceiros
    const h4=["Data","Obra","Terceirizado","Especialidade","Valor","Descrição"];
    const b4=rows.flatMap(r=>r.tercDetalhes.map(p=>[p.date,r.obra.name,p.tercName||"-",p.specialty||"-",p.amount,p.description||"-"]));
    const ws4=XLSX.utils.aoa_to_sheet([[`Pagamentos terceiros - ${period}`],[],h4,...b4]);
    ws4["!cols"]=[12,22,20,14,12,28].map(w=>({wch:w}));
    XLSX.utils.book_append_sheet(wb, ws4, "Terceiros");

    // Aba 5 - Rescisões
    const h5=["Obra","Funcionário","CPF","Admissão","Rescisão","Tipo","Total Líquido"];
    const b5=rows.flatMap(r=>r.rescDetalhes.map(rc=>[r.obra.name,rc.empName||"-",rc.empCPF||"-",rc.admissao,rc.demissao,TIPO_LABEL[rc.tipo]||rc.tipo,rc.totalLiquido]));
    if(b5.length>0){
      const ws5=XLSX.utils.aoa_to_sheet([[`Rescisões - ${period}`],[],h5,...b5]);
      ws5["!cols"]=[22,22,14,12,12,30,12].map(w=>({wch:w}));
      XLSX.utils.book_append_sheet(wb, ws5, "Rescisões");
    }

    await XLSX.writeFile(wb, `arcd-relatorio-${year}-${String(month+1).padStart(2,"0")}.xlsx`);
  };

  //  UI
  return (
    <div style={{display:"flex",flexDirection:"column",gap:14}} className="anim">

      <PageHero
        eyebrow="Inteligência gerencial"
        title="Relatório executivo"
        description="Visão consolidada de receita, custo e resultado por obra."
        actions={<span style={{display:"inline-flex",padding:"5px 8px",border:`1px solid ${C.border}`,borderRadius:5,background:C.surface,color:C.yellowD,fontSize:"var(--arcd-type-caption)",fontWeight:600,letterSpacing:.3}}>{fullMonth(month)} · {year}</span>}
      />

      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(150px,1fr))",gap:8}}>
        <ReportMetric label="Receita recebida" value={fmt(tot.received)} detail="Caixa realizado no período" color={C.yellow} icon="wallet"/>
        <ReportMetric label="Margem global" value={fmt(tot.margem)} detail={tot.received?`${((tot.margem/tot.received)*100).toFixed(1)}% da receita`:"Sem receita no período"} color={tot.margem>=0?C.green:C.red} icon="trending"/>
        <ReportMetric label="Total de despesas" value={fmt(tot.totalDespesas)} detail="Custos diretos e benefícios" color={C.red} icon="receipt"/>
        <ReportMetric label="Receita esperada" value={fmt(tot.revenueEsp)} detail="Posição contratual estimada" color={C.text} icon="target"/>
      </div>

      {/* Ações */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(160px,1fr))",gap:8}}>
        <Btn onClick={gerarPDF} v="danger" full><Ic n="file"/> Relatório PDF</Btn>
        <Btn onClick={exportXLS} v="success" full><Ic n="download"/> Excel Completo</Btn>
      </div>

      {/* Cards por obra */}
      {rows.map(r => {
        const margemColor = r.margem >= 0 ? C.green : C.red;
        return (
          <div key={r.obra.id} style={{
            background:C.card, border:`1px solid ${C.border}`,
            borderTop:`2px solid ${margemColor}`, borderRadius:10, overflow:"hidden",
          }}>
            {/* Header da obra */}
            <div style={{padding:"12px 16px",borderBottom:`1px solid ${C.line}`,display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:10}}>
              <div>
                <p style={{fontFamily:FONT_DISPLAY,fontWeight:600,fontSize:"var(--arcd-type-section-title)",letterSpacing:.3}}>{r.obra.name}</p>
                <div style={{display:"flex",gap:4,flexWrap:"wrap",marginTop:4}}>
                  <Badge color={C.yellow}>{CONTRACT_LABELS[r.obra.contractType]||"Contrato"}</Badge>
                  <Badge color={C.blue}>{r.activeEmps} func.</Badge>
                  {r.activeTercs>0&&<Badge color={C.orange}>{r.activeTercs} terceiros</Badge>}
                  <Badge color={C.muted}>{r.presencaDias} presenças</Badge>
                </div>
              </div>
              <div style={{textAlign:"right",flexShrink:0}}>
                <p style={{fontFamily:FONT_DISPLAY,fontWeight:600,fontSize:"var(--arcd-type-section-title)",color:margemColor,letterSpacing:.5,lineHeight:1}}>{fmt(r.margem)}</p>
                <p style={{fontSize:"var(--arcd-type-label)",color:C.muted,marginTop:2}}>margem {r.margemPct.toFixed(0)}%</p>
              </div>
            </div>

            {/* DRE mini */}
            <div style={{padding:"10px 16px",display:"flex",flexDirection:"column",gap:0}}>
              {/* Receitas */}
              <p style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,color:C.muted,textTransform:"uppercase",letterSpacing:.8,marginBottom:4}}>Receitas</p>
              {[
                ["Recebido no mês",  r.received,         C.green],
                ["Esperado (contrato)", r.revenueEsperada, C.subtle],
              ].map(([l,v,c])=>(
                <div key={l} style={{display:"flex",justifyContent:"space-between",padding:"3px 0",borderBottom:`1px solid ${C.line}44`}}>
                  <p style={{fontSize:"var(--arcd-type-body)",color:c}}>{l}</p>
                  <p style={{fontSize:"var(--arcd-type-body)",color:c,fontWeight:600}}>{fmt(v)}</p>
                </div>
              ))}

              {/* Despesas */}
              <p style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,color:C.muted,textTransform:"uppercase",letterSpacing:.8,marginTop:8,marginBottom:4}}>Despesas</p>
              {[
                ["(-) MO própria",       r.moData.laborCost,   C.orange],
                ["(-) Benefícios VT/VR", r.moData.benefitCost, C.muted],
                ["(-) Terceirizados",    r.tercCost,           C.purple, r.tercCost===0],
                ["(-) Rescisões",        r.rescTotal,          C.red,    r.rescTotal===0],
                ["(-) Adiantamentos",    r.adiantTotal,        C.muted,  r.adiantTotal===0],
              ].filter(([,,, skip])=>!skip).map(([l,v,c])=>(
                <div key={l} style={{display:"flex",justifyContent:"space-between",padding:"3px 0",borderBottom:`1px solid ${C.line}44`}}>
                  <p style={{fontSize:"var(--arcd-type-body)",color:C.muted}}>{l}</p>
                  <p style={{fontSize:"var(--arcd-type-body)",color:c,fontWeight:600}}>{fmt(v)}</p>
                </div>
              ))}

              {/* Totais */}
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:6,marginTop:10}}>
                <div style={{background:C.surface,border:`1px solid ${C.border}`,padding:"8px 10px",borderRadius:8}}>
                  <p style={{fontSize:"var(--arcd-type-caption)",color:C.muted,textTransform:"uppercase",fontWeight:600}}>Total despesas</p>
                  <p style={{fontSize:"var(--arcd-type-card-title)",color:C.red,fontWeight:600,marginTop:2}}>{fmt(r.totalDespesas)}</p>
                </div>
                <div style={{background:C.surface,border:`1px solid ${margemColor}44`,padding:"8px 10px",borderRadius:8}}>
                  <p style={{fontSize:"var(--arcd-type-caption)",color:C.muted,textTransform:"uppercase",fontWeight:600}}>Margem esp.</p>
                  <p style={{fontSize:"var(--arcd-type-card-title)",color:r.margemEsperada>=0?C.green:C.red,fontWeight:600,marginTop:2}}>{fmt(r.margemEsperada)}</p>
                </div>
              </div>

              {/* Detalhe terceiros/rescisões se houver */}
              {r.tercDetalhes.length>0&&(
                <div style={{marginTop:8}}>
                  <p style={{fontSize:"var(--arcd-type-label)",fontWeight:600,color:C.purple,textTransform:"uppercase",marginBottom:3}}>Terceiros pagos</p>
                  {r.tercDetalhes.map(p=>(
                    <div key={p.id} style={{display:"flex",justifyContent:"space-between",fontSize:"var(--arcd-type-label)",color:C.muted,padding:"2px 0"}}>
                      <span>{p.tercName||"-"} <span style={{color:C.muted,fontSize:"var(--arcd-type-label)"}}>({fmtDateFull(p.date)})</span></span>
                      <span style={{color:C.purple,fontWeight:600}}>{fmt(p.amount)}</span>
                    </div>
                  ))}
                </div>
              )}
              {r.rescDetalhes.length>0&&(
                <div style={{marginTop:8}}>
                  <p style={{fontSize:"var(--arcd-type-label)",fontWeight:600,color:C.red,textTransform:"uppercase",marginBottom:3}}>Rescisões</p>
                  {r.rescDetalhes.map(rc=>(
                    <div key={rc.id} style={{display:"flex",justifyContent:"space-between",fontSize:"var(--arcd-type-label)",color:C.muted,padding:"2px 0"}}>
                      <span>{rc.empName||"-"} <span style={{color:C.muted,fontSize:"var(--arcd-type-label)"}}>({TIPO_LABEL[rc.tipo]||rc.tipo})</span></span>
                      <span style={{color:C.red,fontWeight:600}}>{fmt(rc.totalLiquido)}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        );
      })}

      {/* Totais finais */}
      <div style={{background:C.card,border:`2px solid ${C.yellow}`,borderRadius:10,padding:"14px 16px"}}>
        <p style={{fontFamily:FONT_DISPLAY,fontWeight:600,fontSize:"var(--arcd-type-card-title)",color:C.yellow,textTransform:"uppercase",letterSpacing:.5,marginBottom:10}}>Consolidado Geral - {fullMonth(month)} {year}</p>
        {[
          ["Receita recebida",  tot.received,          C.green],
          ["Receita esperada",  tot.revenueEsp,        C.subtle],
          ["MO própria",        tot.laborCost,         C.orange],
          ["Benefícios",        tot.benefitCost,       C.muted],
          ["Terceirizados",     tot.tercCost,          C.purple],
          ["Rescisões",         tot.rescTotal,         C.red],
          ["Adiantamentos",     tot.adiantTotal,       C.muted],
          ["Total despesas",    tot.totalDespesas,     C.red],
          ["Margem global",     tot.margem,            tot.margem>=0?C.green:C.red],
        ].map(([l,v,c])=>(
          <div key={l} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"5px 0",borderBottom:`1px solid ${C.line}44`}}>
            <p style={{fontSize:"var(--arcd-type-body)",color:C.muted}}>{l}</p>
            <p style={{fontSize:"var(--arcd-type-body)",color:c,fontWeight:600}}>{fmt(v)}</p>
          </div>
        ))}
      </div>

      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
        <Btn onClick={gerarPDF} v="danger" full><Ic n="file"/> PDF</Btn>
        <Btn onClick={exportXLS} v="success" full><Ic n="download"/> Excel</Btn>
      </div>
    </div>
  );
}

//
// Agente de IA - apoio operacional
// Funciona com análise local do app e, se existir backend /api/ai-agent,
// usa o endpoint de IA sem expor chave no navegador.
//

const agentNormalize = value => String(value || "")
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .toLowerCase();

const agentDateLabel = iso => fmtDateFull(iso) || "-";

const getAgentMonthCostByObra = (data, year = new Date().getFullYear(), month = new Date().getMonth()) => {
  const days = getDays(year, month);
  const holidays = getPayrollHolidays(data, year);
  const holidaysInMonth = days.filter(d => holidays.includes(d) && prIsWeekdayIso(d));

  return (data.obras || []).map(obra => {
    let presentes = 0;
    let meiodia = 0;
    let faltas = 0;
    let semRegistro = 0;

    (data.employees || []).forEach(emp => {
      days.forEach(day => {
        if (!isEmployeeEmployedOnDate(emp, day)) return;
        if (holidaysInMonth.includes(day)) return;
        const record = getAtt(data, emp.id, day);
        const obraDoDia = resolveEmployeeAttendanceObraId({
          data,
          employee:emp,
          date:day,
          record,
        });
        if (obraDoDia !== obra.id) return;
        const status = record?.status;

        if (status === "P") {
          presentes++;
        } else if (status === "M") {
          meiodia++;
        } else if (status === "F") {
          faltas++;
        } else if (isLeaveStatus(status)) {
          // Afastamento: não conta como falta nem como dia sem registro.
        } else if (emp.active !== false && emp.obra === obra.id) {
          semRegistro++;
        }
      });

    });

    // O CFO/IA recebe exatamente a mesma MO do DRE e dos relatórios.
    const { laborCost, benefitCost, totalCost } = calcObraLaborCost(data, obra.id, days);
    const areaM2 = Number(obra.areaM2 || 0);

    return {
      obraId: obra.id,
      obraName: obra.name,
      areaM2,
      laborCost,
      benefitCost,
      totalCost,
      laborCostPerM2: areaM2 > 0 ? laborCost / areaM2 : 0,
      totalCostPerM2: areaM2 > 0 ? totalCost / areaM2 : 0,
      presentes,
      meiodia,
      faltas,
      semRegistro,
    };
  }).sort((a, b) => b.totalCost - a.totalCost);
};

const buildAgentContext = data => {
  const now = new Date();
  const currentYear = now.getFullYear();
  const currentMonth = now.getMonth();
  const todayIso = today();
  const activeEmployees = (data.employees || []).filter(e => e.active !== false);
  const activeObras = (data.obras || []).filter(o => o.status !== "done");
  const attendanceSummary = getObraAttendanceSummary(data, todayIso);
  const completion = getAttendanceCompletionMessage(attendanceSummary);
  const costs = getAgentMonthCostByObra(data, currentYear, currentMonth);
  const pendingUnlocks = (data.unlockRequests || []).filter(r => r.status === "pending");
  const noArea = activeObras.filter(o => !Number(o.areaM2 || 0));
  const noTeam = activeObras.filter(o => !activeEmployees.some(e => e.obra === o.id));
  const incompleteEmployees = activeEmployees.filter(e =>
    !e.name || !e.role || !e.obra || !e.startDate || !Number(e.dailyRate || 0)
  );
  const missingPointEmployees = completion.pendingObras.flatMap(o =>
    o.missingEmployees.map(e => ({ name: e.name, obra: o.obraName }))
  );
  const paymentInfo = getPayrollPaymentCalendar(
    currentYear,
    currentMonth,
    now.getDate() <= 15 ? "1" : "2",
    data
  );

  return {
    today: todayIso,
    companyName: data.config?.companyName || "ArcD Obras",
    totalObras: (data.obras || []).length,
    activeObras: activeObras.length,
    totalEmployees: (data.employees || []).length,
    activeEmployees: activeEmployees.length,
    pendingPointObras: completion.pendingObras.map(o => ({
      obraName: o.obraName,
      missingCount: o.missingCount,
      missingEmployees: o.missingEmployees.map(e => e.name),
    })),
    completedPointObras: completion.completedObras.map(o => o.obraName),
    allPointsDoneToday: completion.allDone,
    missingPointEmployees,
    pendingUnlocks: pendingUnlocks.map(r => ({ obraName: r.obraName, date: r.date, employeeName: r.employeeName || "Todos / obra", reason: r.reason })),
    noAreaObras: noArea.map(o => o.name),
    noTeamObras: noTeam.map(o => o.name),
    incompleteEmployees: incompleteEmployees.slice(0, 30).map(e => ({
      name: e.name,
      role: e.role || "sem função",
      obra: activeObras.find(o => o.id === e.obra)?.name || "sem obra",
      missing: [
        !e.role ? "função" : "",
        !e.obra ? "obra" : "",
        !e.startDate ? "data de admissão" : "",
        !Number(e.dailyRate || 0) ? "diária" : "",
      ].filter(Boolean),
    })),
    monthlyCosts: costs.slice(0, 10).map(c => ({
      obraName: c.obraName,
      laborCost: c.laborCost,
      totalCost: c.totalCost,
      areaM2: c.areaM2,
      laborCostPerM2: c.laborCostPerM2,
      totalCostPerM2: c.totalCostPerM2,
    })),
    paymentDate: paymentInfo.paymentDate,
    paymentBaseDate: paymentInfo.baseDate,
    paymentAdjusted: paymentInfo.adjusted,
    // Terceirizados
    activeTerc: (data.terceirizados||[]).filter(t=>t.active!==false).length,
    tercPendingThisWeek: (() => {
      const fri = getFridayOfWeek(0);
      const {start: ws} = getWeekRange(fri);
      return (data.terceirizados||[]).filter(t=>t.active!==false&&!(data.pagsTerceiros||[]).some(p=>p.tercId===t.id&&p.date>=ws&&p.date<=fri)).length;
    })(),
    tercWeeklyTotal: (data.terceirizados||[]).filter(t=>t.active!==false).reduce((s,t)=>s+Number(t.weeklyRate||0),0),
  };
};

const agentFormatPendingPoints = ctx => {
  if (ctx.allPointsDoneToday) {
    return `Todos os pontos de hoje (${agentDateLabel(ctx.today)}) estão cadastrados nas obras com equipe ativa.`;
  }

  if (!ctx.pendingPointObras.length) {
    return `Não encontrei obras com equipe ativa pendente de ponto em ${agentDateLabel(ctx.today)}.`;
  }

  return [
    `Existem ${ctx.pendingPointObras.length} obra(s) com ponto pendente hoje (${agentDateLabel(ctx.today)}):`,
    ...ctx.pendingPointObras.map(o => `- ${o.obraName}: ${o.missingCount} trabalhador(es) sem ponto - ${o.missingEmployees.join(", ")}`),
  ].join("\n");
};

const agentFormatCosts = ctx => {
  if (!ctx.monthlyCosts.length) return "Ainda não há custo de mão de obra lançado no mês atual.";

  return [
    "Resumo de gasto de mão de obra por obra no mês atual:",
    ...ctx.monthlyCosts.map(c => {
      const m2 = c.areaM2 > 0 ? `  ${fmt(c.laborCostPerM2)}/m mão de obra` : "  área m não cadastrada";
      return `- ${c.obraName}: ${fmt(c.laborCost)} mão de obra | ${fmt(c.totalCost)} com benefícios${m2}`;
    }),
  ].join("\n");
};

const agentFormatIncompletes = ctx => {
  const parts = [];

  if (ctx.incompleteEmployees.length) {
    parts.push("Funcionários ativos com cadastro incompleto:");
    parts.push(...ctx.incompleteEmployees.map(e => `- ${e.name}: falta ${e.missing.join(", ")}.`));
  }

  if (ctx.noAreaObras.length) {
    parts.push("\nObras sem metragem cadastrada:");
    parts.push(...ctx.noAreaObras.map(name => `- ${name}`));
  }

  if (ctx.noTeamObras.length) {
    parts.push("\nObras ativas sem equipe vinculada:");
    parts.push(...ctx.noTeamObras.map(name => `- ${name}`));
  }

  return parts.length ? parts.join("\n") : "Não encontrei pendências cadastrais relevantes nos dados atuais.";
};

const agentFormatPayroll = ctx => {
  const obs = ctx.paymentAdjusted
    ? `A data base ${agentDateLabel(ctx.paymentBaseDate)} foi ajustada para ${agentDateLabel(ctx.paymentDate)}.`
    : `A data de pagamento permanece em ${agentDateLabel(ctx.paymentDate)}.`;

  return [
    `Próximo pagamento calculado: ${agentDateLabel(ctx.paymentDate)}.`,
    obs,
    `Pontos de hoje: ${ctx.allPointsDoneToday ? "todos cadastrados" : `${ctx.pendingPointObras.length} obra(s) pendente(s)`}.`,
    ctx.pendingUnlocks.length ? `Há ${ctx.pendingUnlocks.length} solicitação(ões) de permissão pendente(s).` : "Não há solicitação de permissão pendente.",
  ].join("\n");
};

const agentFormatPriorities = ctx => {
  const priorities = [];

  if (ctx.pendingPointObras.length) priorities.push(`Finalizar ponto de ${ctx.pendingPointObras.length} obra(s) pendente(s).`);
  if (ctx.pendingUnlocks.length) priorities.push(`Analisar ${ctx.pendingUnlocks.length} solicitação(ões) de alteração de ponto.`);
  if (ctx.noAreaObras.length) priorities.push(`Cadastrar metragem de ${ctx.noAreaObras.length} obra(s) para custo por m.`);
  if (ctx.incompleteEmployees.length) priorities.push(`Corrigir cadastro de ${ctx.incompleteEmployees.length} funcionário(s) ativo(s).`);
  if (!priorities.length) priorities.push("Não há alertas críticos. Mantenha a rotina de finalizar o ponto por obra ao fim do dia.");

  return [
    "Prioridades sugeridas pelo agente:",
    ...priorities.map((p, i) => `${i + 1}. ${p}`),
  ].join("\n");
};

const generateLocalAgentAnswer = (data, question) => {
  const ctx = buildAgentContext(data);
  const q = agentNormalize(question);

  if (!q.trim()) return agentFormatPriorities(ctx);
  if (q.includes("ponto") || q.includes("falt") || q.includes("pendente") || q.includes("cadastrar")) return agentFormatPendingPoints(ctx);
  if (q.includes("custo") || q.includes("gasto") || q.includes("m2") || q.includes("metro") || q.includes("obra")) return agentFormatCosts(ctx);
  if (q.includes("cadastro") || q.includes("incompleto") || q.includes("diaria") || q.includes("metragem")) return agentFormatIncompletes(ctx);
  if (q.includes("folha") || q.includes("pagamento") || q.includes("feriado") || q.includes("salario")) return agentFormatPayroll(ctx);
  if (q.includes("prioridade") || q.includes("risco") || q.includes("alerta") || q.includes("resumo")) return agentFormatPriorities(ctx);

  return [
    "Análise geral do agente:",
    agentFormatPriorities(ctx),
    "",
    agentFormatPendingPoints(ctx),
    "",
    agentFormatPayroll(ctx),
  ].join("\n");
};

async function askRemoteAgentIfAvailable(data, question) {
  try {
    const payload = await chamarIA({ modulo:"geral", question, context:buildAgentContext(data) });
    if (!payload.ok) return null;
    return payload?.answer || null;
  } catch {
    return null;
  }
}

function AgenteIA({ data, showToast, onTab }) {
  const [input, setInput] = useState("");
  const [thinking, setThinking] = useState(false);
  const initialAnswer = useMemo(() => generateLocalAgentAnswer(data, "prioridades"), [data]);
  const [messages, setMessages] = useState([
    {
      role: "assistant",
      text: "Sou o Agente IA da ArcD Obras. Posso ajudar com ponto pendente, folha, custo por obra, custo por m, cadastros incompletos e alertas operacionais.",
    },
    { role: "assistant", text: initialAnswer },
  ]);

  const ctx = useMemo(() => buildAgentContext(data), [data]);

  const quickPrompts = [
    "O que falta no ponto de hoje?",
    "Quais obras estão gastando mais?",
    "Quais cadastros estão incompletos?",
    "Resumo da folha e pagamento",
    "Quais são as prioridades de hoje?",
  ];

  const sendQuestion = async (question = input) => {
    const q = String(question || "").trim();
    if (!q) return;

    setInput("");
    setMessages(prev => [...prev, { role: "user", text: q }]);
    setThinking(true);

    const remote = await askRemoteAgentIfAvailable(data, q);
    const answer = remote || generateLocalAgentAnswer(data, q);

    setMessages(prev => [...prev, { role: "assistant", text: answer }]);
    setThinking(false);
  };

  const copyLastAnswer = () => {
    const last = [...messages].reverse().find(m => m.role === "assistant")?.text || "";
    if (!last) return;
    navigator.clipboard.writeText(last).then(() => showToast("Resposta copiada.")).catch(() => showToast("Erro ao copiar.", "error"));
  };

  const goToPendingPoint = () => {
    onTab?.("ponto");
    if (ctx.pendingPointObras.length) showToast("Abra a obra pendente no filtro do ponto.", "warn");
  };

  return (
    <div className="anim" style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      <PageHero
        eyebrow="Assistente operacional"
        title="Agente IA ArcD"
        description="Analisa ponto, folha, obras, pendências, custo por obra e custo de mão de obra por m²."
      />

      <div style={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 8 }}>
        {[
          [ctx.allPointsDoneToday ? "Ponto completo" : "Ponto pendente", ctx.allPointsDoneToday ? "Todas as obras" : `${ctx.pendingPointObras.length} obra(s)`, ctx.allPointsDoneToday ? C.green : C.red],
          ["Funcionários ativos", ctx.activeEmployees, C.yellow],
          ["Solicitações", ctx.pendingUnlocks.length, ctx.pendingUnlocks.length ? C.red : C.green],
          ["Obras sem m", ctx.noAreaObras.length, ctx.noAreaObras.length ? C.orange : C.green],
        ].map(([label, value, color]) => (
          <div key={label} style={{ background: C.card, border: `1px solid ${C.border}`, borderTop: `3px solid ${color}`, padding: 12, borderRadius: 8 }}>
            <p style={{ color: C.muted, fontSize:"var(--arcd-type-label)", textTransform: "uppercase", fontWeight:600 }}>{label}</p>
            <p style={{ color, fontFamily:"var(--arcd-font-sans)", fontSize: "var(--arcd-type-kpi)", fontWeight:600 }}>{value}</p>
          </div>
        ))}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <Btn v="warning" onClick={goToPendingPoint} full><Ic n="clock" /> Ir para Ponto</Btn>
        <Btn v="ghost" onClick={() => onTab?.("relat")} full><Ic n="chart" /> Ver Relatórios</Btn>
      </div>

      <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 14, borderRadius: 10 }}>
        <h3 style={{ fontFamily:"var(--arcd-font-sans)", color: C.yellow, fontSize: "var(--arcd-type-section-title)", textTransform: "uppercase", marginBottom: 10 }}>
          Perguntas rápidas
        </h3>
        <div style={{ display: "flex", gap: 7, flexWrap: "wrap" }}>
          {quickPrompts.map(p => (
            <button
              key={p}
              onClick={() => sendQuestion(p)}
              style={{
                background: C.surface,
                color: C.text,
                border: `1px solid ${C.border}`,
                borderLeft: `1px solid ${C.yellow}`,
                padding: "8px 10px",
                borderRadius: 999,
                cursor: "pointer",
                fontSize: "var(--arcd-type-control)",
                fontWeight:600,
              }}
            >
              {p}
            </button>
          ))}
        </div>
      </div>

      <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 12, borderRadius: 10, minHeight: 300 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
          <h3 style={{ fontFamily:"var(--arcd-font-sans)", color: C.yellow, fontSize: "var(--arcd-type-section-title)", textTransform: "uppercase" }}>
            Conversa com o agente
          </h3>
          <Btn v="ghost" size="sm" onClick={copyLastAnswer}><Ic n="copy" /> Copiar</Btn>
        </div>

        <div style={{ display: "flex", flexDirection: "column", gap: 9, maxHeight: 390, overflowY: "auto", paddingRight: 3 }}>
          {messages.map((m, idx) => (
            <div
              key={`${m.role}-${idx}`}
              style={{
                alignSelf: m.role === "user" ? "flex-end" : "stretch",
                maxWidth: m.role === "user" ? "86%" : "100%",
                background: m.role === "user" ? C.yellow : C.surface,
                color: m.role === "user" ? C.bg : C.text,
                border: `1px solid ${m.role === "user" ? C.yellow : C.border}`,
                borderLeft: m.role === "assistant" ? `4px solid ${C.yellow}` : undefined,
                borderRadius: 8,
                padding: "10px 12px",
                whiteSpace: "pre-wrap",
                fontSize: "var(--arcd-type-body)",
                lineHeight: 1.35,
              }}
            >
              {m.text}
            </div>
          ))}
          {thinking && (
            <div style={{ color: C.yellow, fontSize: "var(--arcd-type-body)", fontWeight:600, padding: "6px 2px" }}>
              Agente analisando dados...
            </div>
          )}
        </div>
      </div>

      <div className="fluid-grid" style={{ display: "grid", gridTemplateColumns: "1fr auto", gap: 8 }}>
        <Inp
          value={input}
          onChange={setInput}
          placeholder="Pergunte: quais obras faltam ponto? qual maior custo por m?"
        />
        <Btn onClick={() => sendQuestion()} disabled={thinking || !input.trim()}>
          <Ic n="brain" /> Enviar
        </Btn>
      </div>

      <p style={{ color: C.muted, fontSize:"var(--arcd-type-label)", lineHeight: 1.35 }}>
        O agente usa os dados já cadastrados no sistema. Se existir uma rota segura <strong>/api/ai-agent</strong>, ele usa IA generativa; caso contrário, responde com análise local automática, sem expor chaves no navegador.
      </p>
    </div>
  );
}

// A tela de Rescisão foi extraída para
// src/domains/rh/components/RescisaoView.jsx em 2026-08-20. TIPO_LABEL
// segue aqui porque RelatorioMensal (mais abaixo) também usa.
const TIPO_LABEL = RESCISSION_TYPE_LABEL;

//
// Configurações / aprovações
//

function IntegracaoGemini({ showToast, standalone=false }) {
  const { formGrid } = useBreakpoint();
  const [geminiKey,setGeminiKey]=useState("");
  const [aiStatus,setAIStatus]=useState({carregando:true,configured:false,provider:"gemini",model:""});
  const [salvandoIA,setSalvandoIA]=useState(false);
  const [resultadoConfiguracao,setResultadoConfiguracao]=useState({tipo:"",mensagem:""});
  const carregarStatusIA=useCallback(async()=>{
    const status=await verificarStatusIA();
    setAIStatus({carregando:false,configured:!!status.configured,provider:status.provider||"gemini",model:status.model||"",source:status.source||"none",updatedAt:status.updatedAt||"",updatedBy:status.updatedBy||"",validationStatus:status.validationStatus||"unknown",validationMessage:status.validationMessage||"",error:status.ok?"":status.error||"Falha ao verificar."});
  },[]);
  useEffect(()=>{carregarStatusIA();},[carregarStatusIA]);
  const salvarIntegracaoIA=async()=>{
    if(!geminiKey.trim()){showToast("Cole uma chave da API Gemini.","error");return;}
    setSalvandoIA(true);setResultadoConfiguracao({tipo:"",mensagem:""});
    try{
      const result=await configurarGemini(geminiKey.trim());
      if(!result.ok){const mensagem=result.error||"Não foi possível validar a chave.";setResultadoConfiguracao({tipo:"erro",mensagem});showToast(mensagem,"error");return;}
      const mensagem=result.warning||"Gemini conectado a todas as IAs do ArcD.";
      setGeminiKey("");setResultadoConfiguracao({tipo:result.warning?"aviso":"sucesso",mensagem});await carregarStatusIA();showToast(mensagem,result.warning?"error":undefined);
    }catch{
      const mensagem="Não foi possível alcançar o servidor de configuração. Tente novamente.";
      setResultadoConfiguracao({tipo:"erro",mensagem});showToast(mensagem,"error");
    }finally{setSalvandoIA(false);}
  };
  const desconectarIntegracaoIA=async()=>{
    if(!window.confirm("Desconectar o Gemini configurado no ArcD?"))return;
    setSalvandoIA(true);const result=await removerConfiguracaoIA();setSalvandoIA(false);
    if(!result.ok){showToast(result.error||"Não foi possível desconectar.","error");return;}
    await carregarStatusIA();showToast(result.configured?"Configuração do administrador removida; a chave do ambiente continua ativa.":"Gemini desconectado.");
  };
  return <div className={standalone?"anim":""} style={{background:C.card,border:`1px solid ${aiStatus.configured&&aiStatus.validationStatus!=="rate_limit"?C.green:aiStatus.configured?C.orange:C.border}`,borderLeft:`1px solid ${aiStatus.configured&&aiStatus.validationStatus!=="rate_limit"?C.green:C.yellow}`,borderRadius:10,padding:14}}>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:10,flexWrap:"wrap"}}><div><p style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,color:C.yellow,letterSpacing:1,textTransform:"uppercase"}}>Inteligência artificial corporativa</p><h3 style={{fontSize:"var(--arcd-type-card-title)",marginTop:3}}>Google Gemini · integração única</h3><p style={{fontSize:"var(--arcd-type-label)",color:C.muted,marginTop:4,maxWidth:720}}>Esta autenticação atende Compras, Financeiro, Diário de Obra, Orçamento, Planejamento, auditoria administrativa e o agente geral. A chave fica criptografada no servidor e não aparece novamente.</p></div><Badge color={aiStatus.carregando?C.orange:aiStatus.configured&&aiStatus.validationStatus!=="rate_limit"?C.green:aiStatus.configured?C.orange:C.red}>{aiStatus.carregando?"VERIFICANDO":!aiStatus.configured?"NÃO CONFIGURADA":aiStatus.validationStatus==="rate_limit"?"CHAVE SALVA · COTA ATINGIDA":"GEMINI CONECTADO"}</Badge></div>
    {aiStatus.configured&&<div style={{marginTop:10,padding:"8px 10px",borderRadius:8,background:`${C.green}0A`,border:`1px solid ${C.green}33`,fontSize:"var(--arcd-type-label)",color:C.subtle}}>Modelo: <strong>{aiStatus.model||"Gemini"}</strong> · origem: {aiStatus.source==="admin"?"configurada pelo administrador":"ambiente seguro da Vercel"}{aiStatus.updatedBy?` · por ${aiStatus.updatedBy}`:""}</div>}
    {aiStatus.error&&<p style={{fontSize:"var(--arcd-type-label)",color:C.red,marginTop:8}}>{aiStatus.error}</p>}
    {resultadoConfiguracao.mensagem&&<div role="status" style={{marginTop:9,padding:"9px 10px",borderRadius:8,background:resultadoConfiguracao.tipo==="sucesso"?`${C.green}0D`:`${resultadoConfiguracao.tipo==="aviso"?C.orange:C.red}0D`,border:`1px solid ${resultadoConfiguracao.tipo==="sucesso"?C.green:resultadoConfiguracao.tipo==="aviso"?C.orange:C.red}55`,fontSize:"var(--arcd-type-label)",fontWeight:600,color:resultadoConfiguracao.tipo==="sucesso"?C.green:resultadoConfiguracao.tipo==="aviso"?C.orange:C.red}}>{resultadoConfiguracao.mensagem}</div>}
    {aiStatus.validationMessage&&<div style={{marginTop:9,padding:"9px 10px",borderRadius:8,background:`${C.orange}0D`,border:`1px solid ${C.orange}44`,fontSize:"var(--arcd-type-label)",color:C.text}}>{aiStatus.validationMessage} <a href="https://aistudio.google.com/app/usage" target="_blank" rel="noreferrer" style={{color:C.blue,fontWeight:600}}>Ver uso e limites ↗</a></div>}
    <div style={{display:"grid",gridTemplateColumns:formGrid(2),gap:9,marginTop:12,alignItems:"end"}}><Inp label={aiStatus.configured?"Substituir chave de API":"Chave da API Gemini"} type="password" value={geminiKey} onChange={setGeminiKey} placeholder="Cole a chave somente aqui"/><div style={{display:"flex",gap:7,flexWrap:"wrap"}}><Btn onClick={salvarIntegracaoIA} disabled={salvandoIA||!geminiKey.trim()}><Ic n="check"/> {salvandoIA?"Validando...":aiStatus.configured?"Validar e substituir":"Validar e conectar"}</Btn>{aiStatus.source==="admin"&&<Btn v="danger" onClick={desconectarIntegracaoIA} disabled={salvandoIA}>Desconectar</Btn>}</div></div>
    <p style={{fontSize:"var(--arcd-type-caption)",color:C.muted,marginTop:9}}>Crie e copie a chave em <a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer" style={{color:C.blue,fontWeight:600}}>Google AI Studio · Chaves de API ↗</a>. O nível gratuito tem limites de uso e o Google informa que entradas e respostas podem ser usadas para melhorar seus produtos; avalie isso antes de enviar documentos sigilosos ou dados pessoais.</p>
  </div>;
}

function ConfiguracaoIA({ showToast }) {
  return <div className="anim" style={{display:"flex",flexDirection:"column",gap:12}}>
    <PageHero
      eyebrow="Administração da IA"
      title="Configurar Gemini"
      description="Uma única chave para todos os módulos inteligentes do ArcD."
    />
    <IntegracaoGemini showToast={showToast} standalone/>
  </div>;
}

function Config({ data, update, showToast, currentUser, onLogout, dispatchAttendanceCommand, dispatchCommand }) {
  const { formGrid } = useBreakpoint();
  const [form, setForm] = useState(data.config);
  const [holidayYear, setHolidayYear] = useState(new Date().getFullYear());
  const setField = key => value => setForm(f => ({ ...f, [key]: value }));
  const holidays = getPayrollHolidays(data, holidayYear);

  const saveConfig = async () => {
    const result=await dispatchCommand(atual=>({
      type:OPERATIONAL_COMMAND.COMPANY_CONFIG_SAVED,
      idempotencyKey:`configuracao-empresa-${uid()}`,
      expectedVersion:Number(form.version||0),
      payload:{config:{...atual.config,...form}},
    }));
    if(!result?.ok){
      showToast(result?.reason||"As configurações não foram confirmadas pelo servidor.","error");
      return;
    }
    if(result.data?.config)setForm(result.data.config);
    showToast("Configurações salvas.");
  };

  const approveRequest = async id => {
    const result=await dispatchAttendanceCommand({
      action:"attendance-unlock-approve",
      operationId:pointOperationId(),
      requestId:id,
    });
    if(!result?.ok){
      showToast(result?.reason||"A permissão não foi aprovada pelo servidor.","error");
      return;
    }
    showToast("Permissão aprovada por 30 minutos.");
  };

  const rejectRequest = async id => {
    const result=await dispatchAttendanceCommand({
      action:"attendance-unlock-reject",
      operationId:pointOperationId(),
      requestId:id,
    });
    if(!result?.ok){
      showToast(result?.reason||"A solicitação não foi recusada pelo servidor.","error");
      return;
    }
    showToast("Solicitação recusada.");
  };

  const pending = (data.unlockRequests||[]).filter(r => r.status === "pending").slice().reverse();
  const recent = data.unlockRequests.slice().reverse().slice(0, 12);

  const exportBackup = () => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `arcd-obras-backup-${today()}.json`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    showToast("Backup exportado.");
  };

  return (
    <div className="anim" style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      <PageHero
        eyebrow="Sistema"
        title="Configurações"
        description="Aparência, dados da empresa, aprovações e calendário."
      />

      <ThemeSettings />

      <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 14 }}>
        <h3 style={{ fontFamily:"var(--arcd-font-sans)", color: C.yellow, textTransform: "uppercase", marginBottom: 10 }}>Empresa</h3>
        <div style={{ display: "grid", gridTemplateColumns:formGrid(2), gap: 10 }}>
          <Inp label="Empresa" value={form.companyName} onChange={setField("companyName")} />
          <Inp label="Produto" value={form.productName} onChange={setField("productName")} />
          <CampoCNPJ value={form.cnpj} onChange={setField("cnpj")} onEncontrado={d=>setForm(f=>({...f, companyName: f.companyName||d.razaoSocial||d.nome }))}/>
          <Inp label="Responsável RH" value={form.hrName} onChange={setField("hrName")} />
          <Inp label="E-mail RH" value={form.hrEmail} onChange={setField("hrEmail")} />
          <Inp label="WhatsApp RH (c/ DDI)" value={form.hrPhone} onChange={setField("hrPhone")} placeholder="5581999990000" />
          <Inp label="WhatsApp de Compras (c/ DDI)" value={form.whatsappCompras} onChange={setField("whatsappCompras")} placeholder="5581999990000" />
          <Inp label="E-mail aprovador" value={form.approverEmail} onChange={setField("approverEmail")} />
        </div>
        <div style={{ marginTop: 12 }}><Btn onClick={saveConfig}><Ic n="check" /> Salvar configurações</Btn></div>
      </div>

      <IntegracaoGemini showToast={showToast}/>

      {/* DRE - Alíquotas e tributação */}
      <div style={{ background:C.card, border:`1px solid ${C.border}`, borderRadius:8, padding:14 }}>
        <h3 style={{ fontFamily:"var(--arcd-font-sans)", fontWeight:600, color:C.yellow, textTransform:"uppercase", letterSpacing:.5, marginBottom:4, fontSize:"var(--arcd-type-body)" }}>DRE - Tributação</h3>
        <p style={{ fontSize:"var(--arcd-type-label)", color:C.muted, marginBottom:12 }}>Configure as alíquotas para o cálculo automático do DRE da empresa.</p>
        <div style={{ display:"grid", gridTemplateColumns:formGrid(2), gap:10 }}>
          <Inp label="ISS (%)" type="number" value={String(form.aliquotaISS||"")} onChange={v=>setField("aliquotaISS")(v)} placeholder="Ex.: 5"/>
          <Inp label="PIS (%)" type="number" value={String(form.aliquotaPIS||"")} onChange={v=>setField("aliquotaPIS")(v)} placeholder="Ex.: 0.65"/>
          <Inp label="COFINS (%)" type="number" value={String(form.aliquotaCOFINS||"")} onChange={v=>setField("aliquotaCOFINS")(v)} placeholder="Ex.: 3"/>
          <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:6,padding:"8px 12px",display:"flex",alignItems:"center"}}>
            <p style={{fontSize:"var(--arcd-type-label)",color:C.muted}}>Simples Nacional: use ISS apenas (alíquota efetiva total)</p>
          </div>
          <Inp label="IR - Alíquota estimada (%)" type="number" value={String(form.aliquotaIR||"")} onChange={v=>setField("aliquotaIR")(v)} placeholder="Ex.: 15"/>
          <Inp label="CSLL - Alíquota estimada (%)" type="number" value={String(form.aliquotaCSLL||"")} onChange={v=>setField("aliquotaCSLL")(v)} placeholder="Ex.: 9"/>
        </div>
        {(Number(form.aliquotaISS||0)+Number(form.aliquotaPIS||0)+Number(form.aliquotaCOFINS||0))>0&&(
          <div style={{marginTop:10,background:`${C.yellow}10`,border:`1px solid ${C.yellow}33`,borderRadius:6,padding:"8px 12px"}}>
            <p style={{fontSize:"var(--arcd-type-label)",color:C.text}}>
              Carga sobre faturamento: <strong style={{color:C.yellow}}>{(Number(form.aliquotaISS||0)+Number(form.aliquotaPIS||0)+Number(form.aliquotaCOFINS||0)).toFixed(2)}%</strong>
              {(Number(form.aliquotaIR||0)+Number(form.aliquotaCSLL||0))>0&&<>  Provisão IR+CSLL: <strong style={{color:C.yellow}}>{(Number(form.aliquotaIR||0)+Number(form.aliquotaCSLL||0)).toFixed(1)}%</strong></>}
            </p>
          </div>
        )}
        <div style={{marginTop:10}}><Btn onClick={saveConfig}><Ic n="check"/> Salvar alíquotas</Btn></div>
      </div>

      <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 14 }}>
        <h3 style={{ fontFamily:"var(--arcd-font-sans)", color: C.yellow, textTransform: "uppercase", marginBottom: 10 }}>Solicitações pendentes</h3>
        {pending.length === 0 && <p style={{ color: C.muted, fontSize: "var(--arcd-type-body)" }}>Nenhuma solicitação pendente.</p>}
        {pending.map(r => (
          <div key={r.id} style={{ background: C.surface, border: `1px solid ${C.border}`, borderLeft: `1px solid ${C.yellow}`, padding: 12, marginBottom: 8 }}>
            <p style={{ fontWeight:600 }}>{r.obraName}  {fmtDateFull(r.date)}</p>
            <p style={{ color: C.muted, fontSize: "var(--arcd-type-body)" }}>{r.employeeName || "Todos / obra"}</p>
            <p style={{ color: C.subtle, fontSize: "var(--arcd-type-body)", marginTop: 5 }}>{r.reason}</p>
            <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
              <Btn v="success" size="sm" onClick={() => approveRequest(r.id)}><Ic n="unlock" /> Aprovar 30 min</Btn>
              <Btn v="danger" size="sm" onClick={() => rejectRequest(r.id)}><Ic n="x" /> Recusar</Btn>
            </div>
          </div>
        ))}
      </div>

      <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 14 }}>
        <h3 style={{ fontFamily:"var(--arcd-font-sans)", color: C.yellow, textTransform: "uppercase", marginBottom: 10 }}>Histórico de permissões</h3>
        {recent.length === 0 && <p style={{ color: C.muted, fontSize: "var(--arcd-type-body)" }}>Sem solicitações registradas.</p>}
        {recent.map(r => (
          <div key={r.id} style={{ borderBottom: `1px solid ${C.border}`, padding: "8px 0" }}>
            <p style={{ color: r.status === "approved" ? C.green : r.status === "rejected" ? C.red : C.yellow, fontWeight:600, fontSize: "var(--arcd-type-body)" }}>{String(r.status || "pending").toUpperCase()}  {r.obraName}  {fmtDateFull(r.date)}</p>
            <p style={{ color: C.muted, fontSize: "var(--arcd-type-body)" }}>{r.employeeName || "Todos / obra"}  {r.reason}</p>
          </div>
        ))}
      </div>

      <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 14 }}>
        <h3 style={{ fontFamily:"var(--arcd-font-sans)", color: C.yellow, textTransform: "uppercase", marginBottom: 10 }}>Feriados considerados</h3>
        <Sel value={String(holidayYear)} onChange={v => setHolidayYear(Number(v))} options={Array.from({ length: 5 }, (_, i) => new Date().getFullYear() - 1 + i).map(y => ({ v: String(y), l: String(y) }))} />
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(130px, 1fr))", gap: 6, marginTop: 10 }}>
          {holidays.map(h => <Badge key={h} color={C.blue}>{fmtDateFull(h)}</Badge>)}
        </div>
      </div>

      <div style={{ background:C.card, border:`1px solid ${C.border}`, padding:14, borderRadius:8 }}>
        <h3 style={{ fontFamily:"var(--arcd-font-sans)", color:C.yellow, textTransform:"uppercase", marginBottom:10, fontSize:"var(--arcd-type-body)", fontWeight:600 }}>Backup</h3>
        <Btn v="ghost" onClick={exportBackup}><Ic n="download"/> Exportar backup JSON</Btn>
      </div>

      {/* Gestão de usuários */}
      <div style={{ background:C.card, border:`1px solid ${C.border}`, padding:14, borderRadius:8 }}>
        <h3 style={{ fontFamily:"var(--arcd-font-sans)", color:C.yellow, textTransform:"uppercase", marginBottom:12, fontSize:"var(--arcd-type-body)", fontWeight:600 }}>Usuários e Permissões</h3>
        <GestaoUsuarios data={data} update={update} showToast={showToast} currentUser={currentUser}/>
      </div>

      {/* Logout */}
      <div style={{ background:C.surface, border:`1.5px solid ${C.border}`, padding:14, borderRadius:8 }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:10 }}>
          <div>
            <p style={{ fontWeight:600, fontSize:"var(--arcd-type-body)", color:C.text }}>{currentUser?.nome||"-"}</p>
            <p style={{ fontSize:"var(--arcd-type-label)", color:C.muted, marginTop:2 }}>{ROLES.find(r=>r.v===currentUser?.role)?.l||"-"}</p>
          </div>
          <Btn v="danger" size="sm" onClick={onLogout}>Sair</Btn>
        </div>
      </div>
    </div>
  );
}

