// Painel corporativo para monitor/TV. É deliberadamente somente leitura:
// sintetiza progresso, qualidade, campo e suprimentos sem permitir que um
// clique acidental em uma tela compartilhada altere a operação.
function PainelTV({data,ultimaSync,onAtualizar,allowedTabs=[]}){
  const [visao,setVisao]=useState("panorama");
  const podeVerEquipe=allowedTabs.includes("equipe_obras");
  const raizRef=useRef(null);
  const {isDesktop}=useBreakpoint();
  const [pagina,setPagina]=useState(0);
  const [agora,setAgora]=useState(()=>new Date());
  const [telaCheia,setTelaCheia]=useState(false);
  const [cicloImagem,setCicloImagem]=useState(0);
  const obras=useMemo(()=>(data.obras||[]).filter(o=>o.status!=="done"),[data.obras]);
  const linhas=useMemo(()=>obras.map(obra=>{
    const plano=(data.planos||[]).find(p=>p.obraId===obra.id);
    const tarefas=plano?.tarefas||[];
    const executivas=tarefas.filter(t=>!t.titulo);
    const progresso=executivas.length?Math.round(executivas.reduce((s,t)=>s+Number(t.progresso||0),0)/executivas.length):0;
    const tarefasComDatas=executivas.filter(t=>t.inicio&&t.fim);
    const planejado=tarefasComDatas.length?Math.round(tarefasComDatas.reduce((s,t)=>s+Number(desvioTarefaAuto(t,today()).pctPrevisto||0),0)/tarefasComDatas.length):null;
    const atrasadas=tarefas.filter(t=>t.fim&&t.fim<today()&&Number(t.progresso||0)<100);
    const equipe=(data.employees||[]).filter(e=>e.active!==false&&e.obra===obra.id);
    const diarioHoje=(data.rdos||[]).find(r=>r.obraId===obra.id&&r.data===today()&&r.status==="concluido");
    const pendencias=(data.conferencias||[]).filter(c=>c.obraId===obra.id)
      .flatMap(c=>(c.pendencias||[]).filter(p=>p.status!=="resolvida"));
    const qualidade=(data.qualidadeRegistros||[]).filter(q=>q.obraId===obra.id&&!["aprovada","liberada_concessao"].includes(q.status));
    const compras=(data.solicitacoesCompra||[]).filter(s=>s.obraId===obra.id&&!["atendida","cancelada","concluida"].includes(s.status));
    const necessidades=[];
    if(!obra.engineerId&&!obra.engineer)necessidades.push("Definir engenheiro responsável");
    if(equipe.length&&!diarioHoje)necessidades.push("RDO de hoje pendente");
    if(atrasadas.length)necessidades.push(`${atrasadas.length} atividade(s) atrasada(s)`);
    if(pendencias.length)necessidades.push(`${pendencias.length} inconformidade(s) aberta(s)`);
    if(qualidade.length)necessidades.push(`${qualidade.length} FVS/FVM em inspeção`);
    if(compras.length)necessidades.push(`${compras.length} solicitação(ões) de compra`);
    const criticas=pendencias.filter(p=>p.impacto==="critico").length;
    const prazo=obra.contractEnd?Math.ceil((new Date(`${obra.contractEnd}T12:00:00`)-new Date(`${today()}T12:00:00`))/86400000):null;
    const severidade=criticas||prazo!==null&&prazo<0?3:atrasadas.length||pendencias.length||!diarioHoje&&equipe.length?2:necessidades.length?1:0;
    const fotosRdo=(data.rdos||[]).filter(r=>r.obraId===obra.id&&(r.fotos||[]).length)
      .sort((a,b)=>String(b.data||"").localeCompare(String(a.data||"")))
      .flatMap(r=>(r.fotos||[]).map((foto,indice)=>({url:foto.url||"",tipo:"rdo",legenda:foto.legenda||`Foto ${indice+1}`,data:r.data||"",codigo:r.codigo||""})))
      .filter(f=>f.url).slice(0,16);
    const imagens=[...(obra.capaUrl?[{url:obra.capaUrl,tipo:"capa",legenda:"Imagem da obra",data:"",codigo:""}]:[]),...fotosRdo]
      .filter((foto,indice,lista)=>lista.findIndex(x=>x.url===foto.url)===indice);
    return {obra,progresso,planejado,temPlanejamento:planejado!==null,desvioFisico:planejado===null?null:progresso-planejado,equipe:equipe.length,diarioHoje:!!diarioHoje,atrasadas:atrasadas.length,pendencias:pendencias.length,criticas,qualidade:qualidade.length,compras:compras.length,necessidades,prazo,severidade,imagens};
  }).sort((a,b)=>b.severidade-a.severidade||b.pendencias-a.pendencias||a.obra.name.localeCompare(b.obra.name)),[obras,data.planos,data.employees,data.rdos,data.conferencias,data.qualidadeRegistros,data.solicitacoesCompra]);
  const porPagina=isDesktop?4:2,totalPaginas=Math.max(1,Math.ceil(linhas.length/porPagina));
  const visiveis=linhas.slice(pagina*porPagina,pagina*porPagina+porPagina);
  const linhasPlanejadas=linhas.filter(o=>o.temPlanejamento);
  const progressoGeral=linhasPlanejadas.length?Math.round(linhasPlanejadas.reduce((s,o)=>s+o.progresso,0)/linhasPlanejadas.length):0;
  const planejadoGeral=linhasPlanejadas.length?Math.round(linhasPlanejadas.reduce((s,o)=>s+o.planejado,0)/linhasPlanejadas.length):0;
  const necessidadesTotal=linhas.reduce((s,o)=>s+o.necessidades.length,0);
  const pendenciasTotal=linhas.reduce((s,o)=>s+o.pendencias,0);
  const obrasAtencao=linhas.filter(o=>o.severidade>=2).length;
  const imagem=data.config?.companyImageUrl||data.config?.logoUrl||ARCD_LOGO;

  useEffect(()=>{const t=window.setInterval(()=>setAgora(new Date()),1000);return()=>window.clearInterval(t);},[]);
  useEffect(()=>{const t=window.setInterval(()=>setPagina(p=>(p+1)%totalPaginas),12000);return()=>window.clearInterval(t);},[totalPaginas]);
  useEffect(()=>{const t=window.setInterval(()=>setCicloImagem(c=>c+1),7800);return()=>window.clearInterval(t);},[]);
  useEffect(()=>setPagina(p=>Math.min(p,totalPaginas-1)),[totalPaginas]);
  useEffect(()=>{if(!onAtualizar)return undefined;const t=window.setInterval(()=>onAtualizar(),90000);return()=>window.clearInterval(t);},[onAtualizar]);
  useEffect(()=>{const fn=()=>setTelaCheia(document.fullscreenElement===raizRef.current);document.addEventListener("fullscreenchange",fn);return()=>document.removeEventListener("fullscreenchange",fn);},[]);
  const alternarTelaCheia=async()=>{if(document.fullscreenElement)await document.exitFullscreen?.();else await raizRef.current?.requestFullscreen?.();};

  return <div ref={raizRef} className="anim arcd-tv" style={{minHeight:telaCheia?"100vh":"calc(100vh - 126px)",background:"radial-gradient(circle at 78% 8%,rgba(212,175,55,.13),transparent 26%),linear-gradient(142deg,#111412,#1b1c18 62%,#111210)",color:C.surface,borderRadius:telaCheia?0:16,overflow:"hidden",padding:"clamp(16px,2vw,28px)",position:"relative",display:"flex",flexDirection:"column",gap:"clamp(10px,1.3vw,17px)",boxShadow:"0 18px 60px rgba(18,18,18,.2)"}}>
    <img src={imagem} alt="" aria-hidden="true" style={{position:"absolute",right:"3%",top:"5%",width:"min(30vw,420px)",height:"min(30vw,420px)",objectFit:"contain",opacity:.035,pointerEvents:"none"}}/>
    <div aria-hidden="true" className="arcd-tv-scan" style={{position:"absolute",left:0,right:0,height:1,background:`linear-gradient(90deg,transparent,${C.yellow}88,transparent)`,boxShadow:`0 0 18px ${C.yellow}`}}/>
    <header className="arcd-tv-header" style={{position:"relative",zIndex:1,display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:18}}>
      <div><div style={{display:"flex",alignItems:"center",gap:9}}><span style={{width:8,height:8,borderRadius:99,background:C.green,boxShadow:`0 0 18px ${C.green}`}}/><span style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,letterSpacing:2,textTransform:"uppercase",color:C.yellow}}>MARCELL · Centro de operações</span></div><h1 style={{fontFamily:"var(--arcd-font-sans)",fontSize:"clamp(24px,3vw,46px)",fontWeight:600,letterSpacing:-1.2,lineHeight:1,marginTop:9}}>{visao==="equipe"&&podeVerEquipe?"Equipe nas Obras":"Panorama executivo das obras"}</h1><p style={{fontSize:"var(--arcd-type-label)",color:"rgba(245,243,238,.5)",marginTop:7}}>{visao==="equipe"&&podeVerEquipe?"Equipe por obra e registros recebidos do ponto":"Visão contínua de avanço, campo, qualidade, suprimentos e prazos"}</p></div>
      <div style={{display:"flex",alignItems:"center",gap:10}}><div style={{textAlign:"right"}}><p style={{fontFamily:"var(--arcd-font-sans)",fontSize:"clamp(20px,2.2vw,34px)",fontWeight:600,color:C.yellow,lineHeight:1}}>{agora.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})}</p><p style={{fontSize:"var(--arcd-type-caption)",color:"rgba(245,243,238,.45)",marginTop:5}}>{agora.toLocaleDateString("pt-BR",{weekday:"short",day:"2-digit",month:"short"})}</p></div><button onClick={alternarTelaCheia} title="Alternar tela cheia" style={{width:40,height:40,borderRadius:11,border:`1px solid ${C.yellow}44`,background:"rgba(212,175,55,.08)",color:C.yellow,cursor:"pointer"}}><Ic n={telaCheia?"x":"eye"} s={15}/></button></div>
    </header>

    <Tabs value={podeVerEquipe?visao:"panorama"} onValueChange={setVisao} style={{display:"flex",flexDirection:"column",gap:16,flex:1,minHeight:0}}><TabsList className="arcd-tv-visoes" aria-label="Visão do Modo TV"><TabsTrigger value="panorama">Panorama executivo</TabsTrigger>{podeVerEquipe&&<TabsTrigger value="equipe">Equipe nas Obras</TabsTrigger>}</TabsList>
    <TabsContent value="panorama" style={{display:visao==="panorama"||!podeVerEquipe?"flex":"none",flexDirection:"column",gap:16,flex:1,minHeight:0}}>
    <div className="arcd-tv-summary" style={{position:"relative",zIndex:1,display:"grid",gridTemplateColumns:isDesktop?"repeat(4,minmax(0,1fr))":"repeat(2,minmax(0,1fr))",gap:"clamp(7px,1vw,11px)"}}>{[
      ["Obras em operação",linhas.length,"carteira ativa",C.yellow],
      ["Planejado × executado",linhasPlanejadas.length?`${planejadoGeral}% · ${progressoGeral}%`:"—",linhasPlanejadas.length?`${progressoGeral-planejadoGeral>=0?"+":""}${progressoGeral-planejadoGeral} p.p.`:"sem cronograma",linhasPlanejadas.length&&progressoGeral>=planejadoGeral?C.green:C.yellow],
      ["Pendências técnicas",pendenciasTotal,"conferências",pendenciasTotal?C.red:C.green],
      ["Obras em atenção",obrasAtencao,necessidadesTotal?`${necessidadesTotal} ações mapeadas`:"operação regular",obrasAtencao?C.yellow:C.green],
    ].map(([l,v,s,c])=><div key={l} style={{background:"rgba(245,243,238,.055)",border:"1px solid rgba(245,243,238,.12)",borderRadius:10,padding:"clamp(9px,1vw,13px)"}}><p style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,textTransform:"uppercase",letterSpacing:.7,color:"rgba(245,243,238,.58)"}}>{l}</p><p style={{fontFamily:"var(--arcd-font-sans)",fontSize:"clamp(21px,2vw,32px)",fontWeight:600,color:c,lineHeight:1,marginTop:5}}>{v}</p><p style={{fontSize:"var(--arcd-type-caption)",color:"rgba(245,243,238,.46)",marginTop:4}}>{s}</p></div>)}</div>

    <section className="arcd-tv-grid" aria-live="polite" style={{position:"relative",zIndex:1,display:"grid",gridTemplateColumns:isDesktop?"repeat(2,minmax(0,1fr))":"minmax(0,1fr)",gap:"clamp(8px,1vw,13px)",flex:1,minHeight:0}}>
      {visiveis.map((item,cardIndex)=>{const cor=item.severidade===3?C.red:item.severidade===2?C.yellow:item.severidade===1?C.cinza:C.green;const indiceImagem=item.imagens.length?(cicloImagem+cardIndex)%item.imagens.length:0;const foto=item.imagens[indiceImagem];return <article className="arcd-tv-work" key={item.obra.id} style={{position:"relative",overflow:"hidden",border:`1px solid ${cor}66`,borderRadius:12,background:"linear-gradient(145deg,#171a17,#0e100f)",display:"flex",flexDirection:"column",minHeight:0,boxShadow:"inset 0 0 38px rgba(0,0,0,.2)"}}>
        {foto&&<img key={`${item.obra.id}-${foto.url}-${cicloImagem}`} className="arcd-tv-photo" src={foto.url} alt="" aria-hidden="true" loading="eager" onError={e=>{e.currentTarget.style.display="none";}} style={{position:"absolute",inset:"-2%",width:"104%",height:"104%",objectFit:"cover",objectPosition:"center",filter:"saturate(.9) contrast(1.06) brightness(.94)",pointerEvents:"none"}}/>}
        <div aria-hidden="true" style={{position:"absolute",inset:0,zIndex:1,background:"linear-gradient(90deg,rgba(6,8,9,.7) 0%,rgba(6,8,9,.4) 48%,rgba(6,8,9,.12) 100%),linear-gradient(0deg,rgba(5,6,7,.6) 0%,rgba(5,6,7,.02) 76%)"}}/>
        <div aria-hidden="true" style={{position:"absolute",inset:0,zIndex:1,opacity:.1,backgroundImage:`linear-gradient(${C.yellow}55 1px,transparent 1px),linear-gradient(90deg,${C.yellow}55 1px,transparent 1px)`,backgroundSize:"34px 34px",maskImage:"linear-gradient(90deg,transparent 20%,#000 100%)"}}/>
        {!foto&&<div aria-hidden="true" style={{position:"absolute",inset:0,zIndex:1,opacity:.2,backgroundImage:`linear-gradient(${C.yellow}40 1px,transparent 1px),linear-gradient(90deg,${C.yellow}40 1px,transparent 1px)`,backgroundSize:"30px 30px"}}/>}
        <span style={{position:"absolute",zIndex:3,left:0,top:0,bottom:0,width:3,background:cor,boxShadow:`0 0 18px ${cor}`}}/>
        <div className="arcd-tv-work-content" style={{position:"relative",zIndex:2,padding:"clamp(11px,1.15vw,16px)",display:"flex",flexDirection:"column",flex:1,minHeight:0}}>
          <div style={{display:"flex",justifyContent:"space-between",gap:12,alignItems:"flex-start"}}><div style={{minWidth:0}}><p style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,letterSpacing:1,textTransform:"uppercase",color:cor,textShadow:"0 1px 10px rgba(0,0,0,.8)"}}>{item.severidade>=3?"Atenção crítica":item.severidade===2?"Ação necessária":item.severidade===1?"Monitoramento":"Operação regular"}</p><h2 style={{fontFamily:"var(--arcd-font-sans)",fontSize:"clamp(17px,1.5vw,25px)",fontWeight:600,color:"#fff",marginTop:4,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis",textShadow:"0 2px 14px #000"}}>{item.obra.name}</h2><p style={{fontSize:"var(--arcd-type-caption)",color:"rgba(255,255,255,.72)",marginTop:3,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis",textShadow:"0 1px 8px #000"}}>Eng. {item.obra.engineer||"não definido"} · {item.equipe} pessoa(s) em campo</p>{foto&&<p style={{fontSize:"var(--arcd-type-caption)",color:"rgba(255,255,255,.42)",marginTop:4,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{foto.tipo==="rdo"?`RDO-${String(foto.codigo||0).padStart(3,"0")} · ${fmtDate(foto.data)} · ${foto.legenda}`:"Imagem cadastrada da obra"} · {indiceImagem+1}/{item.imagens.length}</p>}</div><div style={{textAlign:"right",flexShrink:0,padding:"5px 8px",borderRadius:9,background:"rgba(4,5,6,.52)",border:"1px solid rgba(255,255,255,.09)",backdropFilter:"blur(8px)"}}><strong style={{fontSize:"clamp(20px,2vw,31px)",fontWeight:600,color:C.yellow,textShadow:`0 0 16px ${C.yellow}55`}}>{item.progresso}%</strong><p style={{fontSize:"var(--arcd-type-caption)",color:"rgba(255,255,255,.48)",textTransform:"uppercase"}}>avanço</p></div></div>
          <div style={{marginTop:10,padding:"7px 9px",borderRadius:9,background:"rgba(5,8,10,.58)",border:"1px solid rgba(255,255,255,.11)",backdropFilter:"blur(8px)",boxShadow:"0 7px 22px rgba(0,0,0,.2)"}}><div style={{display:"flex",justifyContent:"space-between",gap:8,alignItems:"center",marginBottom:5}}><p style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,letterSpacing:1,color:"rgba(255,255,255,.54)",textTransform:"uppercase"}}>Curva física · hoje</p><span style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,color:item.temPlanejamento&&item.desvioFisico>=0?C.green:C.yellow}}>{item.temPlanejamento?`${item.desvioFisico>=0?"+":""}${item.desvioFisico} p.p.`:"sem cronograma"}</span></div>{[["Planejado",item.planejado,C.cinza],["Executado",item.progresso,item.temPlanejamento&&item.progresso>=item.planejado?C.green:C.yellow]].map(([label,valor,cor])=>{const disponivel=valor!==null;return <div key={label} style={{display:"grid",gridTemplateColumns:"54px minmax(0,1fr) 30px",gap:6,alignItems:"center",marginTop:4}}><span style={{fontSize:"var(--arcd-type-caption)",color:"rgba(255,255,255,.58)"}}>{label}</span><div style={{height:4,borderRadius:99,background:"rgba(255,255,255,.14)",overflow:"hidden"}}><i style={{display:"block",height:"100%",width:`${disponivel?Math.max(0,Math.min(100,valor)):0}%`,background:cor,boxShadow:disponivel?`0 0 10px ${cor}`:"none"}}/></div><b style={{fontSize:"var(--arcd-type-caption)",color:cor,textAlign:"right"}}>{disponivel?`${valor}%`:"—"}</b></div>})}</div>
          <div className="arcd-tv-work-stats" style={{display:"grid",gridTemplateColumns:"repeat(4,minmax(0,1fr))",gap:5,marginTop:9}}>{[["RDO",item.diarioHoje?"OK":"Pendente",item.diarioHoje?C.green:C.yellow],["Atrasos",item.atrasadas,item.atrasadas?C.red:C.green],["Qualidade",item.qualidade,item.qualidade?C.yellow:C.green],["Compras",item.compras,item.compras?C.yellow:C.green]].map(([l,v,c])=><div key={l} style={{padding:"6px 7px",borderRadius:7,background:"rgba(6,8,9,.62)",border:"1px solid rgba(255,255,255,.11)",backdropFilter:"blur(8px)",minWidth:0}}><p style={{fontSize:"var(--arcd-type-caption)",color:"rgba(255,255,255,.55)",textTransform:"uppercase",fontWeight:600}}>{l}</p><p style={{fontSize:"var(--arcd-type-label)",fontWeight:600,color:c,marginTop:2,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis",textShadow:"0 1px 7px #000"}}>{v}</p></div>)}</div>
          <div style={{marginTop:"auto",paddingTop:10,display:"flex",gap:6,alignItems:"center",minWidth:0}}><span style={{width:6,height:6,borderRadius:99,background:cor,boxShadow:`0 0 10px ${cor}`,flexShrink:0}}/><p style={{fontSize:"var(--arcd-type-caption)",color:item.necessidades.length?"rgba(255,255,255,.82)":C.green,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis",textShadow:"0 1px 8px #000"}}>{item.necessidades[0]||"Sem necessidade operacional crítica"}{item.necessidades.length>1?` · +${item.necessidades.length-1}`:""}</p>{item.prazo!==null&&<span style={{marginLeft:"auto",padding:"3px 6px",borderRadius:6,background:"rgba(4,5,6,.55)",fontSize:"var(--arcd-type-caption)",color:item.prazo<0?C.red:"rgba(255,255,255,.62)",whiteSpace:"nowrap"}}>{item.prazo<0?`${Math.abs(item.prazo)}d vencido`:`${item.prazo}d restantes`}</span>}</div>
        </div>
      </article>;})}
      {!visiveis.length&&<div style={{gridColumn:"1/-1",display:"grid",placeItems:"center",border:"1px dashed rgba(245,243,238,.15)",borderRadius:15,color:"rgba(245,243,238,.45)"}}>Nenhuma obra ativa para exibir.</div>}
    </section>

    <footer className="arcd-tv-footer" style={{position:"relative",zIndex:1,display:"flex",justifyContent:"space-between",alignItems:"center",gap:12,color:"rgba(245,243,238,.46)",fontSize:"var(--arcd-type-caption)"}}><span>Sincronização automática · {ultimaSync?ultimaSync.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"}):"agora"}</span><div style={{display:"flex",alignItems:"center",gap:6}}><button onClick={()=>setPagina(p=>(p-1+totalPaginas)%totalPaginas)} aria-label="Página anterior" style={{width:28,height:24,border:`1px solid rgba(245,243,238,.15)`,borderRadius:5,background:"transparent",color:C.surface,cursor:"pointer"}}>‹</button>{Array.from({length:totalPaginas},(_,i)=><button key={i} onClick={()=>setPagina(i)} aria-label={`Página ${i+1}`} style={{width:i===pagina?18:6,height:6,border:0,borderRadius:99,background:i===pagina?C.yellow:"rgba(245,243,238,.22)",cursor:"pointer",transition:"width .2s"}}/>)}<span style={{margin:"0 2px"}}>{pagina+1}/{totalPaginas}</span><button onClick={()=>setPagina(p=>(p+1)%totalPaginas)} aria-label="Próxima página" style={{width:28,height:24,border:`1px solid rgba(245,243,238,.15)`,borderRadius:5,background:"transparent",color:C.surface,cursor:"pointer"}}>›</button></div></footer>
    </TabsContent>
    {podeVerEquipe&&<TabsContent value="equipe" style={{flex:1}}><Suspense fallback={<p role="status">Carregando equipe…</p>}><EquipeObrasTV /></Suspense></TabsContent>}
    </Tabs>
  </div>;
}

// Comunicação interna: conversa da equipe (chat), checklist de prioridades
// diárias dos engenheiros de campo e ranking. Mensagens e ajustes de ranking
// vivem em linhas próprias no banco (api/chat.js, api/ranking.js) - não
// entram no documento único de "data", que não pode crescer a cada mensagem.
// Atualização por atualização periódica (sem tempo real): a lista é
// recarregada a cada poucos segundos enquanto a aba de conversa está aberta.
function Comunicacao({ data, currentUser, showToast }) {
  const [aba, setAba] = useState("notificacoes");
  const ehAdmin = currentUser?.role === "admin";

  //  Notificações: checklist de prioridades por engenheiro de campo
  const engenheiros = useMemo(() => (data.usuarios || []).filter(u => u.active !== false && u.role === "engenheiro"), [data.usuarios]);
  const hoje = today();
  const resumoAtendimento = useMemo(() => getObraAttendanceSummary(data, hoje), [data, hoje]);

  const checklistPorUsuario = useMemo(() => engenheiros.map(u => {
    const obrasDele = (data.obras || []).filter(o => o.engineerId === u.id && o.status !== "done");
    const pontoOk = obrasDele.every(o => {
      const s = resumoAtendimento.find(x => x.obraId === o.id);
      return !s || !s.hasTeam || s.completed;
    });
    const diarioOk = obrasDele.every(o => (data.rdos || []).some(r => r.obraId === o.id && r.data === hoje));
    const pendenciasAbertas = (data.conferencias || []).flatMap(c => (c.pendencias || [])
      .filter(p => p.status !== "resolvida" && p.responsavelAjusteId === u.id));
    return { usuario: u, obrasDele, pontoOk, diarioOk, conferenciasOk: pendenciasAbertas.length === 0, pendenciasAbertas: pendenciasAbertas.length };
  }), [engenheiros, data.obras, data.rdos, data.conferencias, resumoAtendimento, hoje]);

  //  Ranking
  const [ajustes, setAjustes] = useState([]);
  const [ajusteModal, setAjusteModal] = useState(null);
  const [pontosForm, setPontosForm] = useState("");
  const [motivoForm, setMotivoForm] = useState("");

  const carregarRanking = useCallback(async () => {
    const r = await listarAjustesRanking();
    if (r.ok) setAjustes(r.ajustes || []);
  }, []);

  useEffect(() => { if (aba === "ranking" || aba === "notificacoes") carregarRanking(); }, [aba, carregarRanking]);

  const ranking = useMemo(() => checklistPorUsuario.map(c => {
    const meusAjustes = ajustes.filter(a => a.userId === c.usuario.id);
    const pontosManual = meusAjustes.reduce((s, a) => s + Number(a.pontos || 0), 0);
    const pontosAutomaticos = (c.pontoOk ? 10 : 0) + (c.diarioOk ? 10 : 0) + (c.conferenciasOk ? 10 : 0);
    return { ...c, pontosManual, pontosAutomaticos, total: pontosAutomaticos + pontosManual, ajustes: meusAjustes };
  }).sort((a, b) => b.total - a.total), [checklistPorUsuario, ajustes]);

  const salvarAjuste = async () => {
    const pts = Number(pontosForm);
    if (!pts) { showToast("Informe os pontos.", "error"); return; }
    if (!motivoForm.trim()) { showToast("Justifique o ajuste.", "error"); return; }
    const r = await adicionarAjusteRanking(ajusteModal.usuario.id, pts, motivoForm.trim());
    if (!r.ok) { showToast(r.error || "Não foi possível salvar.", "error"); return; }
    setAjusteModal(null); setPontosForm(""); setMotivoForm("");
    carregarRanking();
    showToast("Ajuste registrado.");
  };

  const removerAjuste = async (id) => {
    if (!window.confirm("Remover este ajuste?")) return;
    const r = await removerAjusteRanking(id);
    if (!r.ok) { showToast(r.error || "Não foi possível remover.", "error"); return; }
    carregarRanking();
  };

  return (
    <div className="anim" style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      <PageHero
        eyebrow="Comunicação interna"
        title="Comunicação"
        description="Prioridades do dia e ranking de engenharia de campo. O chat da equipe agora é o balão flutuante no canto da tela."
      />
      <TabRow equal tabs={[["notificacoes", "Notificações"], ["ranking", "Ranking"]]} active={aba} onChange={setAba}/>

      {aba === "notificacoes" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          <p style={{ fontSize:"var(--arcd-type-label)", color: C.muted }}>Prioridades do dia por engenheiro de campo: ponto, diário de obra e conferências.</p>
          {!checklistPorUsuario.length && <p style={{ padding: 20, textAlign: "center", color: C.muted, fontSize:"var(--arcd-type-label)" }}>Nenhum engenheiro de campo cadastrado.</p>}
          {checklistPorUsuario.map(c => (
            <div key={c.usuario.id} style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 9, padding: "11px 13px" }}>
              <p style={{ fontSize:"var(--arcd-type-label)", fontWeight:600, color: C.text }}>{c.usuario.nome}</p>
              <div style={{ display: "flex", gap: 14, marginTop: 6, flexWrap: "wrap" }}>
                {[["Ponto", c.pontoOk], ["Diário de obra", c.diarioOk], ["Conferências", c.conferenciasOk]].map(([l, ok]) => (
                  <span key={l} style={{ display: "inline-flex", alignItems: "center", gap: 5, fontSize:"var(--arcd-type-label)", color: ok ? C.green : C.red, fontWeight:600 }}>
                    <Ic n={ok ? "check" : "alert"} s={12} color={ok ? C.green : C.red} />{l}
                  </span>
                ))}
              </div>
              {!c.conferenciasOk && <p style={{ fontSize:"var(--arcd-type-caption)", color: C.red, marginTop: 4 }}>{c.pendenciasAbertas} pendência(s) de conferência em aberto.</p>}
            </div>
          ))}
        </div>
      )}

      {aba === "ranking" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          <p style={{ fontSize:"var(--arcd-type-label)", color: C.muted }}>10 pontos por item do checklist de hoje (ponto, diário, conferências) + ajustes manuais do administrador.</p>
          {ranking.map((r, idx) => (
            <div key={r.usuario.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, background: C.card, border: `1px solid ${idx === 0 ? C.yellow : C.border}`, borderRadius: 9, padding: "10px 13px" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10, minWidth: 0 }}>
                <span style={{ fontSize: "var(--arcd-type-body)", fontWeight:600, color: idx < 3 ? C.yellowD : C.muted, width: 20 }}>{idx + 1}º</span>
                <div style={{ minWidth: 0 }}>
                  <p style={{ fontSize:"var(--arcd-type-label)", fontWeight:600, color: C.text }}>{r.usuario.nome}</p>
                  <p style={{ fontSize:"var(--arcd-type-caption)", color: C.muted, marginTop: 2 }}>{r.pontosAutomaticos} pts checklist{r.pontosManual ? ` · ${r.pontosManual > 0 ? "+" : ""}${r.pontosManual} ajuste` : ""}</p>
                </div>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 8, flexShrink: 0 }}>
                <b style={{ fontSize: "var(--arcd-type-card-title)", color: C.text }}>{r.total}</b>
                {ehAdmin && <Btn size="sm" v="ghost" onClick={() => setAjusteModal({ usuario: r.usuario })}><Ic n="edit" s={11} /> Ajustar</Btn>}
              </div>
            </div>
          ))}
          {ehAdmin && !!ajustes.length && (
            <div style={{ marginTop: 8 }}>
              <p style={{ fontSize:"var(--arcd-type-label)", fontWeight:600, color: C.muted, textTransform: "uppercase", letterSpacing: .6, marginBottom: 6 }}>Histórico de ajustes</p>
              {ajustes.map(a => {
                const u = (data.usuarios || []).find(x => x.id === a.userId);
                return (
                  <div key={a.id} style={{ display: "flex", justifyContent: "space-between", gap: 8, alignItems: "center", padding: "7px 0", borderTop: `1px solid ${C.line}` }}>
                    <div style={{ minWidth: 0 }}>
                      <p style={{ fontSize:"var(--arcd-type-label)" }}><b>{u?.nome || "Usuário"}</b> {a.pontos > 0 ? "+" : ""}{a.pontos} pts · {a.motivo}</p>
                      <p style={{ fontSize:"var(--arcd-type-caption)", color: C.muted, marginTop: 2 }}>{a.criadoPor} · {fmtDateFull(String(a.criadoEm || "").slice(0, 10))}</p>
                    </div>
                    <Btn size="sm" v="ghost" iconOnly title="Remover ajuste" ariaLabel="Remover ajuste" onClick={() => removerAjuste(a.id)}><Ic n="trash" s={11} /></Btn>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {ajusteModal && (
        <Modal title={`Ajustar ranking · ${ajusteModal.usuario.nome}`} onClose={() => setAjusteModal(null)}>
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            <Inp label="Pontos (use negativo para descontar) *" type="number" value={pontosForm} onChange={setPontosForm} placeholder="Ex.: 10 ou -5" />
            <Inp label="Justificativa *" value={motivoForm} onChange={setMotivoForm} multiline placeholder="Ex.: Entregou o diário atrasado três vezes na semana." />
            <div style={{ display: "flex", gap: 8 }}>
              <Btn v="ghost" onClick={() => setAjusteModal(null)} full>Cancelar</Btn>
              <Btn onClick={salvarAjuste} full>Salvar ajuste</Btn>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

// Bipe curto via Web Audio API - sem depender de um arquivo de áudio para
// empacotar. Silencioso em navegadores que bloqueiam áudio sem interação
// prévia do usuário (ignora o erro; a mensagem já chegou visualmente).
// Chat flutuante da empresa: bolha fixa no canto inferior direito, minimizável,
// com visual próximo do WhatsApp (fundo bege, balões verdes/brancos, cabeçalho
// escuro). Fica montado em qualquer tela do app - não depende da aba "chat"
// estar aberta. Atualização por atualização periódica (sem tempo real).
const WA = {
  header: "#075E54",
  headerDark: "#054c40",
  bubbleMine: "#DCF8C6",
  bubbleTheirs: "#FFFFFF",
  bg: "#ECE5DD",
  green: "#25D366",
  red: "#E53935",
  mentionBg: "rgba(7,94,84,.14)",
};

function IconeChat({ size = 26 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
      <path d="M12 2C6.48 2 2 6.02 2 11c0 2.4 1.05 4.58 2.77 6.2L4 22l5.1-1.53C10.03 20.8 11 21 12 21c5.52 0 10-4.02 10-9s-4.48-10-10-10z" fill="#fff"/>
    </svg>
  );
}

// Destaca "@Nome" dentro do texto da mensagem para quem já foi resolvido como
// menção real (não qualquer "@" digitado à toa).
function ChatFlutuante({ currentUser, usuarios, showToast, bottomOffset=20 }) {
  const [aberto, setAberto] = useState(false);
  const [gestaoAberta, setGestaoAberta] = useState(false);
  const [mensagens, setMensagens] = useState([]);
  const [mutados, setMutados] = useState([]);
  const [texto, setTexto] = useState("");
  const [enviando, setEnviando] = useState(false);
  const [naoLidas, setNaoLidas] = useState(0);
  const [temMencaoNaoLida, setTemMencaoNaoLida] = useState(false);
  const [mencaoParaAbrirId, setMencaoParaAbrirId] = useState(null);
  const [mencaoDestacadaId, setMencaoDestacadaId] = useState(null);
  const [mencaoQuery, setMencaoQuery] = useState(null);
  const [anexoPendente, setAnexoPendente] = useState(null);
  const [subindoAnexo, setSubindoAnexo] = useState(false);
  const scrollRef = useRef(null);
  const inputRef = useRef(null);
  const fileInputRef = useRef(null);
  const ultimoIdRef = useRef(null);
  const primeiraCargaRef = useRef(true);
  const abertoRef = useRef(false);
  useEffect(() => { abertoRef.current = aberto; }, [aberto]);

  const ehAdmin = currentUser?.role === "admin";
  const usuariosMencionaveis = (usuarios || []).filter(u => u.active !== false && u.id !== currentUser?.id);

  const mencoesNoTexto = t => resolveMentionsInText(t, usuariosMencionaveis);

  const carregarChat = useCallback(async () => {
    const r = await listarMensagensChat();
    if (!r.ok) return;
    const lista = r.mensagens || [];
    setMensagens(lista);
    setMutados(r.mutados || []);

    const ultima = lista[lista.length - 1];
    if (ultima && ultima.id !== ultimoIdRef.current) {
      const novas = ultimoIdRef.current
        ? lista.slice(lista.findIndex(m => m.id === ultimoIdRef.current) + 1)
        : [];
      const novasDeOutros = novas.filter(m => m.userId !== currentUser?.id && !m.deletedAt);
      if (novasDeOutros.length && !primeiraCargaRef.current) {
        const mencaoRecebida = novasDeOutros.find(m => (m.mentions || []).some(mm => mm.id === currentUser?.id));
        if (mencaoRecebida) {
          playChatMentionSound();
          showToast?.(`${mencaoRecebida.userName} mencionou você no chat.`, "info");
          if (!abertoRef.current) { setNaoLidas(n => n + novasDeOutros.length); setTemMencaoNaoLida(true); }
          setMencaoParaAbrirId(mencaoRecebida.id);
        } else {
          playChatMessageSound();
          if (!abertoRef.current) setNaoLidas(n => n + novasDeOutros.length);
        }
      }
      ultimoIdRef.current = ultima.id;
    }
    primeiraCargaRef.current = false;
  }, [currentUser?.id, showToast]);

  // 8 s com a aba visível; oculta, 60 s (ver domains/sync/polling.js).
  useEffect(() => {
    if (!currentUser) return undefined;
    const polling = criarPollingAdaptativo({ tarefa: carregarChat, visivelMs: 8000, ocultoMs: 60000 });
    polling.iniciar();
    return polling.parar;
  }, [carregarChat, currentUser]);

  useEffect(() => {
    if (aberto && scrollRef.current && !mencaoParaAbrirId) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [mensagens, aberto, mencaoParaAbrirId]);

  // Ao abrir o painel com uma menção pendente, pula direto para ela em vez de
  // rolar para o fim - é o motivo de o usuário ter clicado no sino.
  useEffect(() => {
    if (!aberto || !mencaoParaAbrirId) return;
    const el = scrollRef.current?.querySelector(`[data-msg-id="${mencaoParaAbrirId}"]`);
    el?.scrollIntoView({ block: "center" });
    setMencaoDestacadaId(mencaoParaAbrirId);
    setMencaoParaAbrirId(null);
    const t = setTimeout(() => setMencaoDestacadaId(null), 2400);
    return () => clearTimeout(t);
  }, [aberto, mencaoParaAbrirId, mensagens]);

  const abrirPainel = () => { setAberto(true); setNaoLidas(0); setTemMencaoNaoLida(false); };

  const euEstouMutado = mutados.some(m => m.userId === currentUser?.id);

  const aoDigitar = valor => {
    setTexto(valor);
    const m = /@([^\s@]*)$/.exec(valor);
    setMencaoQuery(m ? m[1] : null);
  };

  const escolherMencao = u => {
    setTexto(t => t.replace(/@([^\s@]*)$/, `@${u.nome} `));
    setMencaoQuery(null);
    inputRef.current?.focus();
  };

  const sugestoesMencao = mencaoQuery === null ? [] : usuariosMencionaveis
    .filter(u => String(u.nome || "").toLowerCase().includes(mencaoQuery.toLowerCase()))
    .slice(0, 6);

  const escolherArquivo = async e => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    setSubindoAnexo(true);
    try {
      const ehImagem = String(file.type || "").startsWith("image/");
      if (!ehImagem && file.size > 4 * 1024 * 1024) throw new Error("Arquivo muito grande (máx. 4MB).");
      const dataUrl = ehImagem ? await comprimirImagem(file) : await arquivoComoDataUrl(file);
      const ext = (file.name.split(".").pop() || "").slice(0, 8);
      const r = await subirAnexoChat({ dataUrl, ext });
      if (!r.ok || !r.url) throw new Error(r.error || "Falha ao enviar o arquivo.");
      setAnexoPendente({ url: r.url, name: file.name, type: file.type || "", size: file.size || 0 });
    } catch (err) {
      showToast?.(err.message || "Falha ao enviar o arquivo.", "error");
    } finally {
      setSubindoAnexo(false);
    }
  };

  const enviar = async () => {
    const t = texto.trim();
    if (!t && !anexoPendente) return;
    setEnviando(true);
    const r = await enviarMensagemChat(t, { mentions: mencoesNoTexto(t), attachment: anexoPendente });
    setEnviando(false);
    if (!r.ok) { showToast?.(r.error || "Não foi possível enviar a mensagem.", "error"); return; }
    setTexto(""); setAnexoPendente(null); setMencaoQuery(null);
    carregarChat();
  };

  const apagar = async (id) => {
    if (!window.confirm("Apagar esta mensagem para todos?")) return;
    const r = await apagarMensagemChat(id);
    if (!r.ok) { showToast?.(r.error || "Não foi possível apagar.", "error"); return; }
    carregarChat();
  };

  const alternarMudo = async (userId, mutadoAgora) => {
    const r = mutadoAgora ? await dessilenciarUsuarioChat(userId) : await silenciarUsuarioChat(userId);
    if (!r.ok) { showToast?.(r.error || "Não foi possível atualizar.", "error"); return; }
    carregarChat();
  };

  if (!currentUser) return null;

  return (
    <div className="no-print arcd-team-chat" style={{ "--chat-bottom":typeof bottomOffset==="number"?`${bottomOffset}px`:bottomOffset,position: "fixed", right: 20, bottom: bottomOffset, zIndex: 1300, display: "flex", flexDirection: "column", alignItems: "flex-end", fontFamily: "var(--arcd-font-sans)" }}>
      {aberto && (
        <div style={{
          width: "min(360px, calc(100vw - 32px))", height: "min(520px, calc(100dvh - var(--chat-bottom) - 88px))",
          background: WA.bg, borderRadius: 12, overflow: "hidden", marginBottom: 12,
          boxShadow: "0 12px 40px rgba(0,0,0,.28)", display: "flex", flexDirection: "column",
          border: "1px solid rgba(0,0,0,.08)",
        }}>
          {/* Cabeçalho estilo WhatsApp */}
          <div style={{ background: WA.header, color: "#fff", padding: "11px 12px", display: "flex", alignItems: "center", gap: 9, flexShrink: 0 }}>
            <div style={{ width: 34, height: 34, borderRadius: "50%", background: "rgba(255,255,255,.18)", display: "grid", placeItems: "center", flexShrink: 0 }}>
              <IconeChat size={18} />
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <p style={{ fontSize: "var(--arcd-type-body)", fontWeight:600, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>Comunicação da equipe</p>
              <p style={{ fontSize:"var(--arcd-type-label)", opacity: .8 }}>{(usuarios || []).filter(u => u.active !== false).length} participante(s)</p>
            </div>
            {ehAdmin && (
              <button onClick={() => setGestaoAberta(v => !v)} title="Gerenciar grupo" aria-label="Gerenciar grupo"
                style={{ background: "transparent", border: 0, color: "#fff", opacity: .85, cursor: "pointer", padding: 6 }}>
                <Ic n="settings" s={16} />
              </button>
            )}
            <button onClick={() => setAberto(false)} title="Minimizar" aria-label="Minimizar"
              style={{ background: "transparent", border: 0, color: "#fff", cursor: "pointer", padding: 6 }}>
              <Ic n="chevron" s={16} />
            </button>
          </div>

          {gestaoAberta ? (
            <div style={{ flex: 1, overflowY: "auto", background: "#fff", padding: 12 }}>
              <button onClick={() => setGestaoAberta(false)} style={{ background: "transparent", border: 0, color: WA.header, fontSize:"var(--arcd-type-control)", fontWeight:600, cursor: "pointer", marginBottom: 10 }}>← Voltar para a conversa</button>
              <p style={{ fontSize:"var(--arcd-type-label)", fontWeight:600, color: "#666", textTransform: "uppercase", letterSpacing: .6, marginBottom: 8 }}>Silenciar participantes</p>
              <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                {(usuarios || []).filter(u => u.active !== false && u.id !== currentUser?.id).map(u => {
                  const mutado = mutados.some(m => m.userId === u.id);
                  return (
                    <div key={u.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, padding: "7px 0", borderTop: "1px solid #eee" }}>
                      <span style={{ fontSize:"var(--arcd-type-label)", color: "#222" }}>{u.nome}</span>
                      <Btn size="sm" v={mutado ? "danger" : "ghost"} onClick={() => alternarMudo(u.id, mutado)}>{mutado ? "Dessilenciar" : "Silenciar"}</Btn>
                    </div>
                  );
                })}
              </div>
            </div>
          ) : (
            <>
              <div ref={scrollRef} style={{ flex: 1, overflowY: "auto", display: "flex", flexDirection: "column", gap: 6, padding: "10px 10px" }}>
                {!mensagens.length && <p style={{ fontSize:"var(--arcd-type-label)", color: "#8a8a8a", textAlign: "center", marginTop: 20 }}>Nenhuma mensagem ainda. Comece a conversa.</p>}
                {mensagens.map(m => {
                  const minha = m.userId === currentUser?.id;
                  const apagada = !!m.deletedAt;
                  const destacada = mencaoDestacadaId === m.id;
                  return (
                    <div key={m.id} data-msg-id={m.id} style={{ alignSelf: minha ? "flex-end" : "flex-start", maxWidth: "82%", display: "flex", alignItems: "flex-end", gap: 4 }}>
                      <div className={destacada ? "chat-msg-flash" : ""} style={{
                        padding: "6px 9px", borderRadius: 8, background: apagada ? "#f2f2f2" : (minha ? WA.bubbleMine : WA.bubbleTheirs),
                        boxShadow: "0 1px 1px rgba(0,0,0,.12)",
                      }}>
                        {!minha && !apagada && <p style={{ fontSize:"var(--arcd-type-caption)", fontWeight:600, color: "#1565C0", marginBottom: 1 }}>{m.userName}</p>}
                        {!apagada && m.attachment && (
                          m.attachment.type?.startsWith("image/") ? (
                            <a href={m.attachment.url} target="_blank" rel="noopener noreferrer" style={{ display: "block", marginBottom: m.text ? 6 : 2 }}>
                              <img src={m.attachment.url} alt={m.attachment.name} style={{ maxWidth: "100%", maxHeight: 180, borderRadius: 6, display: "block" }} />
                            </a>
                          ) : (
                            <a href={m.attachment.url} target="_blank" rel="noopener noreferrer" style={{
                              display: "flex", alignItems: "center", gap: 6, padding: "6px 8px", borderRadius: 6,
                              background: "rgba(0,0,0,.05)", marginBottom: m.text ? 6 : 2, textDecoration: "none",
                            }}>
                              <Ic n="file" s={16} color="#666" />
                              <span style={{ fontSize:"var(--arcd-type-label)", color: "#222", fontWeight:600, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", flex: 1 }}>{m.attachment.name}</span>
                              <Ic n="download" s={13} color="#888" />
                            </a>
                          )
                        )}
                        {(m.text || apagada) && <p style={{ fontSize: "var(--arcd-type-body)", color: apagada ? "#999" : "#111", fontStyle: apagada ? "italic" : "normal", lineHeight: 1.35, wordBreak: "break-word" }}>
                          {apagada ? "Mensagem apagada pelo administrador" : splitMentionText(m.text, m.mentions).map((part, index) => part.mentioned
                            ? <b key={index} style={{ color: WA.header, background: WA.mentionBg, borderRadius:4, padding:"0 3px" }}>{part.text}</b>
                            : <span key={index}>{part.text}</span>)}
                        </p>}
                        <p style={{ fontSize:"var(--arcd-type-caption)", color: "#8a8a8a", textAlign: "right", marginTop: 2 }}>
                          {new Date(m.createdAt).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}
                        </p>
                      </div>
                      {ehAdmin && !apagada && (
                        <button onClick={() => apagar(m.id)} title="Apagar mensagem" aria-label="Apagar mensagem"
                          style={{ background: "transparent", border: 0, color: "#b0453d", cursor: "pointer", padding: 3, flexShrink: 0 }}>
                          <Ic n="trash" s={10} />
                        </button>
                      )}
                    </div>
                  );
                })}
              </div>
              <div style={{ padding: 8, background: "#F0F0F0", flexShrink: 0, position: "relative" }}>
                {sugestoesMencao.length > 0 && (
                  <div style={{
                    position: "absolute", left: 8, right: 8, bottom: "100%", marginBottom: 6, background: "#fff",
                    borderRadius: 8, boxShadow: "0 4px 16px rgba(0,0,0,.18)", border: "1px solid #ddd", overflow: "hidden", zIndex: 2,
                  }}>
                    {sugestoesMencao.map(u => (
                      <button key={u.id} onClick={() => escolherMencao(u)} style={{
                        display: "flex", alignItems: "center", gap: 8, width: "100%", padding: "8px 10px",
                        border: 0, background: "transparent", cursor: "pointer", textAlign: "left",
                      }}>
                        <span style={{
                          width: 24, height: 24, borderRadius: "50%", background: WA.header, color: "#fff",
                          fontSize:"var(--arcd-type-label)", fontWeight:600, display: "grid", placeItems: "center", flexShrink: 0,
                        }}>{(u.nome || "?").slice(0, 1).toUpperCase()}</span>
                        <span style={{ fontSize: "var(--arcd-type-body)", color: "#222", fontWeight:600 }}>{u.nome}</span>
                      </button>
                    ))}
                  </div>
                )}
                {anexoPendente && (
                  <div style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 7, padding: "6px 8px", background: "#fff", borderRadius: 8, border: "1px solid #ddd" }}>
                    {anexoPendente.type?.startsWith("image/")
                      ? <img src={anexoPendente.url} alt="" style={{ width: 32, height: 32, objectFit: "cover", borderRadius: 4 }} />
                      : <Ic n="file" s={16} color="#666" />}
                    <span style={{ fontSize:"var(--arcd-type-label)", color: "#222", fontWeight:600, flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{anexoPendente.name}</span>
                    <button onClick={() => setAnexoPendente(null)} title="Remover anexo" aria-label="Remover anexo"
                      style={{ background: "transparent", border: 0, color: "#999", cursor: "pointer", padding: 3 }}>
                      <Ic n="x" s={13} />
                    </button>
                  </div>
                )}
                <div style={{ display: "flex", gap: 7 }}>
                  <input ref={fileInputRef} type="file" onChange={escolherArquivo} style={{ display: "none" }}
                    accept="image/*,.pdf,.doc,.docx,.xls,.xlsx,.txt,audio/*" />
                  <button onClick={() => fileInputRef.current?.click()} disabled={euEstouMutado || subindoAnexo}
                    title="Anexar arquivo" aria-label="Anexar arquivo" style={{
                      width: 36, height: 36, borderRadius: "50%", border: 0, flexShrink: 0, background: "#fff", color: "#555",
                      display: "grid", placeItems: "center", cursor: euEstouMutado ? "default" : "pointer", opacity: subindoAnexo ? .6 : 1,
                    }}>
                    {subindoAnexo
                      ? <div style={{ width: 14, height: 14, border: "2px solid #ccc", borderTopColor: WA.header, borderRadius: 99, animation: "spin 1s linear infinite" }} />
                      : <Ic n="attach" s={16} />}
                  </button>
                  <input ref={inputRef} value={texto} onChange={e => aoDigitar(e.target.value)} disabled={euEstouMutado || enviando}
                    onKeyDown={e => {
                      if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); enviar(); }
                      if (e.key === "Escape") setMencaoQuery(null);
                    }}
                    placeholder={euEstouMutado ? "Você foi silenciado" : "Mensagem · use @ para marcar alguém"}
                    style={{ flex: 1, height: 36, border: "1px solid #ddd", borderRadius: 20, background: "#fff", color: "#111", padding: "0 13px", fontSize: "var(--arcd-type-control)", outline: "none" }} />
                  <button onClick={enviar} disabled={euEstouMutado || enviando || (!texto.trim() && !anexoPendente)} title="Enviar" aria-label="Enviar"
                    style={{
                      width: 36, height: 36, borderRadius: "50%", border: 0, flexShrink: 0,
                      background: (euEstouMutado || (!texto.trim() && !anexoPendente)) ? "#b8e3c9" : WA.green, color: "#fff",
                      display: "grid", placeItems: "center", cursor: (euEstouMutado || (!texto.trim() && !anexoPendente)) ? "default" : "pointer",
                    }}>
                    <Ic n="chevR" s={15} />
                  </button>
                </div>
              </div>
            </>
          )}
        </div>
      )}

      {/* Bolha flutuante */}
      <button onClick={() => (aberto ? setAberto(false) : abrirPainel())} title="Comunicação da equipe" aria-label="Abrir chat da equipe"
        className={temMencaoNaoLida ? "chat-mention-pulse" : ""}
        style={{
          width: 56, height: 56, borderRadius: "50%", border: 0, background: WA.green, cursor: "pointer",
          display: "grid", placeItems: "center", boxShadow: "0 6px 18px rgba(0,0,0,.28)", position: "relative",
        }}>
        <IconeChat size={26} />
        {naoLidas > 0 && (
          <span style={{
            position: "absolute", top: -3, right: -3, minWidth: 20, height: 20, borderRadius: 99,
            background: WA.red, color: "#fff", fontSize:"var(--arcd-type-label)", fontWeight:600, display: "grid", placeItems: "center",
            padding: "0 4px", border: "2px solid #fff",
          }}>{naoLidas > 99 ? "99+" : naoLidas}</span>
        )}
      </button>
    </div>
  );
}

