// Busca global estilo command palette (Ctrl/Cmd+K). Filtra o índice por texto,
// agrupa por tipo, navega por teclado (setas + Enter) ou clique.
function BuscaGlobal({ indice, allowedTabs, onIr, onFechar }) {
  const [q, setQ] = useState("");
  const [sel, setSel] = useState(0);
  const inputRef = useRef(null);
  useEffect(() => { inputRef.current?.focus(); }, []);

  const termo = q.trim().toLowerCase();
  const resultados = useMemo(() => {
    if (!termo) return [];
    return indice
      .filter(r => allowedTabs.includes(r.tabId))
      .filter(r => r.rotulo.toLowerCase().includes(termo) || r.sub.toLowerCase().includes(termo))
      .sort((a,b) => {
        // Quem começa com o termo vem antes; telas por último.
        const aStart = a.rotulo.toLowerCase().startsWith(termo) ? 0 : 1;
        const bStart = b.rotulo.toLowerCase().startsWith(termo) ? 0 : 1;
        if (aStart !== bStart) return aStart - bStart;
        if ((a.tipo==="Tela") !== (b.tipo==="Tela")) return a.tipo==="Tela" ? 1 : -1;
        return a.rotulo.localeCompare(b.rotulo);
      })
      .slice(0, 20);
  }, [indice, termo, allowedTabs]);

  useEffect(() => { setSel(0); }, [termo]);

  const escolher = (r) => r && onIr(r.tabId, r.obraId);
  const onKey = (e) => {
    if (e.key==="ArrowDown") { e.preventDefault(); setSel(s => Math.min(s+1, resultados.length-1)); }
    if (e.key==="ArrowUp")   { e.preventDefault(); setSel(s => Math.max(s-1, 0)); }
    if (e.key==="Enter")     { e.preventDefault(); escolher(resultados[sel]); }
  };

  const corTipo = t => ({Obra:C.blue,Funcionário:C.green,Terceirizado:C.purple,Equipamento:C.orange,Lead:C.green,Cliente:C.blue,Proposta:C.yellowD,Contrato:C.purple,Pedido:C.orange,Orçamento:C.yellowD,Parceiro:C.blue,Tela:C.muted}[t]||C.muted);

  return (
    <div onClick={onFechar} style={{
      position:"fixed", inset:0, zIndex:9999, background:"rgba(18,18,18,.45)",
      display:"flex", alignItems:"flex-start", justifyContent:"center", padding:"12vh 16px 16px" }}>
      <div onClick={e=>e.stopPropagation()} style={{
        width:"100%", maxWidth:560, background:C.card, border:`1px solid ${C.border}`,
        borderRadius:12, boxShadow:"0 24px 60px rgba(0,0,0,.35)", overflow:"hidden" }}>
        <div style={{ display:"flex", alignItems:"center", gap:9, padding:"12px 14px", borderBottom:`1px solid ${C.line}` }}>
          <Ic n="funnel" s={16} color={C.muted}/>
          <input ref={inputRef} value={q} onChange={e=>setQ(e.target.value)} onKeyDown={onKey}
            placeholder="Buscar obra, lead, pedido, funcionário, tela..."
            style={{ flex:1, border:0, outline:"none", background:"transparent", fontSize:"var(--arcd-type-control)", color:C.text }}/>
          <span style={{ fontSize:"var(--arcd-type-label)", fontWeight:600, color:C.muted, border:`1px solid ${C.border}`, borderRadius:5, padding:"2px 6px" }}>ESC</span>
        </div>
        <div style={{ maxHeight:"48vh", overflowY:"auto" }}>
          {!termo && <p style={{ padding:"18px 16px", fontSize:"var(--arcd-type-body)", color:C.muted, textAlign:"center" }}>Digite para buscar em todo o sistema.</p>}
          {termo && resultados.length===0 && <p style={{ padding:"18px 16px", fontSize:"var(--arcd-type-body)", color:C.muted, textAlign:"center" }}>Nada encontrado para "{q}".</p>}
          {resultados.map((r,i) => (
            <button key={i} onClick={()=>escolher(r)} onMouseEnter={()=>setSel(i)} style={{
              display:"flex", alignItems:"center", gap:10, width:"100%", textAlign:"left",
              background: i===sel ? `${C.yellow}12` : "transparent", border:0,
              borderLeft:`1px solid ${i===sel ? C.yellow : "transparent"}`,
              padding:"9px 14px", cursor:"pointer" }}>
              <span style={{ fontSize:"var(--arcd-type-caption)", fontWeight:600, color:corTipo(r.tipo), background:`${corTipo(r.tipo)}14`, padding:"2px 7px", borderRadius:99, flexShrink:0, textTransform:"uppercase", minWidth:78, textAlign:"center" }}>{r.tipo}</span>
              <span style={{ minWidth:0, flex:1 }}>
                <span style={{ fontSize:"var(--arcd-type-body)", fontWeight:600, color:C.text, display:"block", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{r.rotulo}</span>
                {r.sub && <span style={{ fontSize:"var(--arcd-type-label)", color:C.muted, display:"block", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{r.sub}</span>}
              </span>
            </button>
          ))}
        </div>
        <div style={{ display:"flex", justifyContent:"space-between", padding:"7px 14px", borderTop:`1px solid ${C.line}`, fontSize:"var(--arcd-type-caption)", color:C.muted }}>
          <span>↑↓ navegar · Enter abrir</span>
          <span>{resultados.length} resultado(s)</span>
        </div>
      </div>
    </div>
  );
}

function PortalClientePublico({ obraId, token }) {
  const [estado,setEstado]=useState({loading:true,portal:null,error:""});
  useEffect(()=>{let ativo=true;(async()=>{try{const resp=await fetch("/api/data",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"client-portal",obraId,token})});const json=await resp.json();if(!resp.ok)throw new Error(json.error||"Portal indisponível.");if(ativo)setEstado({loading:false,portal:json.portal,error:""});}catch(e){if(ativo)setEstado({loading:false,portal:null,error:e.message});}})();return()=>{ativo=false};},[obraId,token]);
  if(estado.loading)return <><style>{G}</style><div style={{minHeight:"100vh",display:"grid",placeItems:"center",background:C.bg,color:C.muted}}>Carregando portal da obra...</div></>;
  if(estado.error)return <><style>{G}</style><div style={{minHeight:"100vh",display:"grid",placeItems:"center",background:C.bg,padding:24}}><div style={{maxWidth:460,textAlign:"center",background:C.card,border:`1px solid ${C.border}`,borderRadius:16,padding:26}}><BrandMark/><h1 style={{fontSize:"var(--arcd-type-section-title)",color:C.text,marginTop:18}}>Este link não está disponível</h1><p style={{fontSize:"var(--arcd-type-body)",color:C.muted,marginTop:8,lineHeight:1.6}}>{estado.error}<br/>Solicite um novo acesso à construtora.</p></div></div></>;
  const p=estado.portal,o=p.obra,concluidas=(p.cronograma||[]).filter(t=>t.progresso>=100).length;
  return <><style>{G}</style><div style={{minHeight:"100vh",background:C.bg,color:C.text}}><header style={{background:"#101828",color:"white",padding:"16px clamp(16px,5vw,56px)",display:"flex",justifyContent:"space-between",alignItems:"center",gap:12}}><BrandMark/><span style={{fontSize:"var(--arcd-type-label)",opacity:.72}}>ACOMPANHAMENTO SEGURO · SOMENTE LEITURA</span></header><main style={{maxWidth:1120,margin:"0 auto",padding:"24px clamp(14px,4vw,34px) 50px"}}>
    <section style={{minHeight:230,borderRadius:20,overflow:"hidden",padding:"clamp(22px,5vw,48px)",display:"flex",alignItems:"flex-end",background:o.capaUrl?`linear-gradient(90deg,rgba(8,15,28,.92),rgba(8,15,28,.35)),url(${o.capaUrl}) center/cover`:`linear-gradient(135deg,#101828,#194b72)`,color:"white",boxShadow:`0 18px 45px ${C.shadow}`}}><div><p style={{fontSize:"var(--arcd-type-label)",fontWeight:600,letterSpacing:1,textTransform:"uppercase",color:"#f3c531"}}>Sua obra</p><h1 style={{fontSize:"clamp(30px,6vw,52px)",lineHeight:1,marginTop:7}}>{o.nome}</h1><p style={{fontSize:"var(--arcd-type-body)",opacity:.82,marginTop:10}}>{[o.endereco,o.engenheiro&&`Responsável técnico: ${o.engenheiro}`].filter(Boolean).join(" · ")}</p></div></section>
    <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(180px,1fr))",gap:10,marginTop:14}}>{[["Avanço físico",`${p.progresso}%`,C.blue],["Etapas concluídas",`${concluidas}/${p.cronograma.length}`,C.green],["Últimos diários",p.diarios.length,C.orange],["Fotos publicadas",p.fotos.length,C.purple]].map(([l,v,c])=><div key={l} style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:13,padding:16}}><p style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,color:C.muted,textTransform:"uppercase"}}>{l}</p><p style={{fontSize:"var(--arcd-type-kpi)",fontWeight:600,color:c,marginTop:5}}>{v}</p></div>)}</div>
    <section style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:14,padding:18,marginTop:14}}><h2 style={{fontSize:"var(--arcd-type-card-title)"}}>Panorama da obra</h2><p style={{fontSize:"var(--arcd-type-body)",color:C.muted,lineHeight:1.65,marginTop:7}}>{p.mensagem}</p><div style={{height:8,borderRadius:99,background:C.line,overflow:"hidden",marginTop:14}}><div style={{height:"100%",width:`${p.progresso}%`,background:`linear-gradient(90deg,${C.blue},${C.green})`}}/></div><div style={{display:"flex",justifyContent:"space-between",fontSize:"var(--arcd-type-caption)",color:C.muted,marginTop:5}}><span>Início {fmtDateFull(o.inicio)}</span><span>Previsão {fmtDateFull(o.terminoPrevisto)}</span></div></section>
    {!!p.fotos.length&&<section style={{marginTop:22}}><h2 style={{fontSize:"var(--arcd-type-section-title)",marginBottom:10}}>Registro fotográfico</h2><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(160px,1fr))",gap:9}}>{p.fotos.map((f,i)=><figure key={`${f.url}-${i}`} style={{margin:0,background:C.card,border:`1px solid ${C.border}`,borderRadius:12,overflow:"hidden"}}><img src={f.url} alt={f.legenda||"Evolução da obra"} style={{width:"100%",aspectRatio:"1",objectFit:"cover",display:"block"}}/><figcaption style={{padding:9,fontSize:"var(--arcd-type-label)",color:C.muted}}>{f.legenda||`RDO-${String(f.rdoCodigo||0).padStart(3,"0")}`} · {fmtDateFull(f.data)}</figcaption></figure>)}</div></section>}
    {!!p.cronograma.length&&<section style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:14,padding:18,marginTop:22}}><h2 style={{fontSize:"var(--arcd-type-card-title)"}}>Cronograma resumido</h2>{p.cronograma.map(t=><div key={t.id} style={{padding:"10px 0",borderTop:`1px solid ${C.line}`}}><div style={{display:"flex",justifyContent:"space-between",gap:10,fontSize:"var(--arcd-type-label)"}}><b>{t.nome}</b><span style={{fontWeight:600,color:t.progresso>=100?C.green:C.blue}}>{t.progresso}%</span></div><div style={{height:5,borderRadius:99,background:C.line,marginTop:6}}><div style={{height:"100%",width:`${t.progresso}%`,borderRadius:99,background:t.progresso>=100?C.green:C.blue}}/></div></div>)}</section>}
    <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(280px,1fr))",gap:14,marginTop:22}}>{!!p.documentos.length&&<section style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:14,padding:18}}><h2 style={{fontSize:"var(--arcd-type-card-title)"}}>Documentos liberados</h2>{p.documentos.map(d=><a key={d.id} href={d.url} target="_blank" rel="noreferrer" style={{display:"flex",gap:8,padding:"10px 0",borderTop:`1px solid ${C.line}`,color:C.blue,fontSize:"var(--arcd-type-label)",textDecoration:"none"}}><Ic n="file"/> {d.nome} ↗</a>)}</section>}{!!p.medicoes.length&&<section style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:14,padding:18}}><h2 style={{fontSize:"var(--arcd-type-card-title)"}}>Medições e pagamentos</h2>{p.medicoes.map(m=><div key={m.id} style={{display:"flex",justifyContent:"space-between",gap:10,padding:"10px 0",borderTop:`1px solid ${C.line}`,fontSize:"var(--arcd-type-label)"}}><span>{m.descricao}<small style={{display:"block",color:C.muted}}>{m.recebido?"Recebido":"Em aberto"}</small></span><b style={{color:m.recebido?C.green:C.orange}}>{fmt(m.recebido?m.valorRecebido:m.valorPrevisto)}</b></div>)}</section>}</div>
    {!!p.atualizacoes.length&&<section style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:14,padding:18,marginTop:22}}><h2 style={{fontSize:"var(--arcd-type-card-title)"}}>Atualizações recentes</h2>{p.atualizacoes.slice(0,8).map(a=><div key={a.id} style={{padding:"10px 0",borderTop:`1px solid ${C.line}`}}><p style={{fontSize:"var(--arcd-type-label)"}}>{a.mensagem}</p><p style={{fontSize:"var(--arcd-type-caption)",color:C.muted,marginTop:3}}>{a.responsavel} · {a.at?new Date(a.at).toLocaleString("pt-BR"):""}</p></div>)}</section>}
  </main></div></>;
}

export default function App() {
  const portalRequest = useMemo(()=>{
    const q=new URLSearchParams(window.location.search);
    return {obraId:q.get("portal")||"",token:q.get("token")||""};
  },[]);
  const [data,        setData]        = useState(null);
  const [tab,         setTab]         = useState("home");
  // Busca global (Ctrl/Cmd+K): índice de tudo que se pode encontrar por nome.
  const [buscaAberta, setBuscaAberta] = useState(false);
  // Obra aberta no painel detalhado. Vazio = lista/quadro normal.
  const [obraAberta,  setObraAberta]  = useState("");
  const [workflowIntent,setWorkflowIntent]=useState(null);
  const [workflowScopes,setWorkflowScopes]=useState({});
  const workflowViews=useRef(new Map());
  const workflowLastScope=useRef({});
  const workflowLastTabs=useRef(new Map());
  const [workflowTrail,setWorkflowTrail]=useState([]);
  const rememberWorkflowScope=useCallback((screen,scope)=>{
    workflowLastScope.current=scope;
    setWorkflowScopes(previous=>JSON.stringify(previous[screen])===JSON.stringify(scope)?previous:{...previous,[screen]:scope});
  },[]);
  const [loading,     setLoading]     = useState(true);
  const [erroInicial, setErroInicial] = useState("");
  const [firstSetup, setFirstSetup] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  useEffect(()=>{workflowViews.current.clear();workflowLastTabs.current.clear();workflowLastScope.current={};setWorkflowScopes({});setWorkflowTrail([]);setWorkflowIntent(null);},[currentUser?.id]);
  const [conflito,    setConflito]    = useState(null);
  const [toast,       setToast]       = useState(null);
  // Momento da ultima sincronizacao bem-sucedida com o servidor.
  const [ultimaSync,  setUltimaSync]  = useState(null);
  const [estadoSalvar,setEstadoSalvar] = useState(SAVE_QUEUE_STATE.IDLE);
  // Última gravação recusada pelo servidor (desfeita na tela): fica visível até
  // o usuário dispensar, para ninguém achar que salvou o que não salvou.
  const [edicaoRecusada,setEdicaoRecusada] = useState(null);
  // A lista de obras e o painel detalhado ocupam alturas diferentes. Sem este
  // reset o navegador preserva o scroll da lista e a obra pode abrir já no
  // meio do conteúdo. O layout effect executa antes da pintura, sem salto.
  useLayoutEffect(() => {
    if (!obraAberta) return;
    window.scrollTo({top:0,left:0,behavior:"auto"});
    document.documentElement.scrollTop=0;
    document.body.scrollTop=0;
  },[obraAberta]);
  const tabPresencaRef = useRef(tab);
  useEffect(() => {
    tabPresencaRef.current = tab;
    if (currentUser?.id) registrarPresenca(tab);
  }, [tab, currentUser?.id]);

  // Mantém a sessão visível para o administrador sem tocar no JSON principal.
  // O servidor considera on-line quem enviou heartbeat nos últimos 90 segundos.
  useEffect(() => {
    if (!currentUser?.id) return undefined;
    const atualizar = () => { registrarPresenca(tabPresencaRef.current); };
    const aoMudarVisibilidade = () => { if (!document.hidden) atualizar(); };
    const aoFechar = () => { encerrarPresenca(true); };
    const timer = window.setInterval(atualizar, 45000);
    document.addEventListener("visibilitychange", aoMudarVisibilidade);
    window.addEventListener("pagehide", aoFechar);
    return () => {
      window.clearInterval(timer);
      document.removeEventListener("visibilitychange", aoMudarVisibilidade);
      window.removeEventListener("pagehide", aoFechar);
    };
  }, [currentUser?.id]);

  useEffect(() => {
    if (typeof document === "undefined") return;
    document.title = BRAND.name;
    let favicon = document.querySelector('link[rel~="icon"]');
    if (!favicon) {
      favicon = document.createElement("link");
      favicon.rel = "icon";
      document.head.appendChild(favicon);
    }
    favicon.type = "image/png";
    favicon.href = BRAND.icon;
    let appleIcon = document.querySelector('link[rel="apple-touch-icon"]');
    if (!appleIcon) {
      appleIcon = document.createElement("link");
      appleIcon.rel = "apple-touch-icon";
      document.head.appendChild(appleIcon);
    }
    appleIcon.href = BRAND.icon;
  }, [data?.config?.companyName, data?.config?.productName]);

  const approvalHandledRef = useRef(false);
  // Última versão que veio do servidor - o ponto de partida das minhas edições.
  // Serve de "base" para o merge de conflito saber o que EU mudei.
  const baseServidorRef = useRef(null);
  // Espelho do estado atual, para a auditoria comparar antes/depois sem que o
  // `update` precise depender de `data` (o que o recriaria a cada tecla).
  const dataAtualRef = useRef(null);
  useEffect(() => { dataAtualRef.current = data; }, [data]);
  // Estado mais recente aplicado, atualizado SINCRONAMENTE dentro do `update`.
  // Serve para reconciliar salvamentos em sequencia rapida: se dois cadastros
  // sao salvos antes do React re-renderizar, o segundo poderia partir de um
  // `data` velho (do closure) e apagar o primeiro. Comparando com este ref
  // reaplicamos so as secoes que o chamador realmente mudou.
  const ultimoDataRef = useRef(null);

  const showToast = useCallback((msg, type = "success") => {
    setToast({ msg, type });
    window.clearTimeout(showToast._t);
    showToast._t = window.setTimeout(() => setToast(null), 3200);
  }, []);

  // FILA DE SALVAMENTO SERIALIZADA
  // Antes, cada update() disparava um save de rede imediato. Toques rapidos no
  // ponto criavam varios saves simultaneos com o MESMO expectedUpdatedAt - o
  // servidor aceitava o primeiro e devolvia 409 para os demais: o app
  // conflitava consigo mesmo e "nao salvava". Agora existe no maximo 1 save em
  // voo; estados novos apenas substituem o proximo a enviar (coalescencia).
  // Como o estado local ja acumula tudo, salvar so o mais recente nao perde nada.
  const saveQueueRef=useRef(null);
  const attendanceCommandInFlightRef=useRef(0);
  const attendanceQueueRef=useRef(null);
  const campoOfflineStoreRef=useRef(null);
  if(!campoOfflineStoreRef.current){
    campoOfflineStoreRef.current=createOfflineOperationStore();
  }
  if(!saveQueueRef.current){
    saveQueueRef.current=createSaveQueue({
      save:alvo=>saveDataDetailed(alvo,baseServidorRef.current),
      onState:setEstadoSalvar,
      onSuccess:({result, target})=>{
        const confirmado=normalizeData(result.merged&&result.data?result.data:target);
        baseServidorRef.current=confirmado;
        if(result.merged){
          // Uma resposta mesclada confirma `target`, mas pode chegar depois de
          // outro clique já ter produzido um snapshot local mais novo. Reaplica
          // essa intenção pendente sobre a nova base para a tela não "voltar"
          // e esconder uma edição que a fila ainda vai enviar.
          const localMaisNovo=ultimoDataRef.current||dataAtualRef.current||target;
          const rebaseado=normalizeData(reconcileOptimisticSnapshot({
            latest:confirmado,rendered:target,intended:localMaisNovo,
          }));
          ultimoDataRef.current=rebaseado;dataAtualRef.current=rebaseado;setData(rebaseado);
          showToast("Alterações simultâneas foram combinadas automaticamente.");
        }
        setUltimaSync(new Date());
      },
      onConflict:()=>showToast("Outra pessoa salvou ao mesmo tempo. Suas alterações aguardam resolução do conflito.","error"),
      onRetry:({result,delay})=>showToast(`${result?.reason||"Não foi possível conectar ao servidor."} Nova tentativa em ${Math.round(delay/1000)}s.`,"error"),
      onFailed:({result,offline,pending})=>{
        if(isServerRejection({result,offline})&&baseServidorRef.current){
          // O servidor recusou (permissão/regra): desfaz a edição otimista,
          // voltando ao último estado confirmado. Roda depois que a fila
          // devolve {ok:false} a quem chamou update(), para não confirmar
          // como salvo o que foi recusado.
          const confirmado=baseServidorRef.current;
          const secoes=rejectedSections(confirmado,pending);
          setTimeout(()=>{
            saveQueueRef.current?.discard();
            ultimoDataRef.current=confirmado;dataAtualRef.current=confirmado;setData(confirmado);
            setEdicaoRecusada({motivo:result?.reason||result?.error||"O servidor recusou a alteração.",secoes,em:new Date()});
          },0);
          showToast(`Alteração não salva e desfeita: ${result?.reason||"recusada pelo servidor"}`,"error");
          return;
        }
        showToast(offline?"Sem conexão. As alterações seguem guardadas e serão retomadas ao reconectar.":(result?.reason||"Alterações não sincronizadas. Confira a conexão e faça uma nova ação para tentar novamente."),"error");
      },
    });
  }
  // Zera a ref (não só destrói) para que uma remontagem real - ou a
  // montagem dupla do StrictMode em desenvolvimento - recrie a fila em vez
  // de reaproveitar a instância já destruída (`if(!saveQueueRef.current)`
  // acima nunca seria verdadeiro de outra forma, e todo update() passaria a
  // falhar silenciosamente com {ok:false,destroyed:true} para sempre).
  useEffect(()=>()=>{saveQueueRef.current?.destroy?.();saveQueueRef.current=null;},[]);

  useEffect(()=>{
    const retomar=()=>{
      if(saveQueueRef.current?.getState()!==SAVE_QUEUE_STATE.OFFLINE)return;
      showToast("Conexão restaurada. Retomando alterações pendentes.");
      saveQueueRef.current.resume();
    };
    window.addEventListener("online",retomar);
    return()=>window.removeEventListener("online",retomar);
  },[showToast]);

  useEffect(()=>{
    const protegerSaida=event=>{
      if(!saveQueueRef.current?.hasPending()&&!attendanceCommandInFlightRef.current&&!attendanceQueueRef.current?.hasPending())return;
      event.preventDefault();
      event.returnValue="";
    };
    window.addEventListener("beforeunload",protegerSaida);
    return()=>window.removeEventListener("beforeunload",protegerSaida);
  },[]);

  const update = useCallback(async (next) => {
    // Aceita atualização funcional. O resolvedor recebe sempre o espelho mais
    // recente, mesmo que o React ainda não tenha renderizado o clique anterior.
    // Isso elimina a dependência de closures antigos nos fluxos migrados.
    let rendered=data||dataAtualRef.current||DEFAULT();
    if(typeof next==="function"){
      rendered=dataAtualRef.current||rendered;
      next=next(rendered);
    }
    if(next&&next.__aguardarFila){
      return saveQueueRef.current?.waitForIdle()||{ok:true,state:SAVE_QUEUE_STATE.IDLE};
    }
    // ADOTAR ESTADO DO SERVIDOR (sem re-salvar)
    // Operacoes cirurgicas como arquivar/restaurar quinzena acontecem no
    // servidor e ja voltam com o dataset novo + carimbo. Aqui apenas
    // adotamos essa versao como base - re-salvar seria redundante e
    // reabriria a janela de conflito.
    if (next && next.__adotarServidor) {
      const norm = normalizeData(next.data);
      adoptServerVersion(next.updatedAt);
      baseServidorRef.current = norm;
      ultimoDataRef.current = norm;
      dataAtualRef.current = norm;
      setData(norm);
      setUltimaSync(new Date());
      return;
    }
    // Respostas de comandos granulares trazem somente as seções confirmadas.
    // Mesclá-las diretamente evita baixar e normalizar todo o cadastro após
    // cada PIX, sem alterar a fotografia autoritativa das demais seções.
    if (next && next.__adotarServidorPatch) {
      const sections=next.sections&&typeof next.sections==="object"?next.sections:{};
      const atual={...(dataAtualRef.current||DEFAULT()),...sections};
      const base={...(baseServidorRef.current||dataAtualRef.current||DEFAULT()),...sections};
      adoptServerVersion(next.updatedAt);
      baseServidorRef.current=base;
      ultimoDataRef.current=atual;
      dataAtualRef.current=atual;
      setData(atual);
      setUltimaSync(new Date());
      return;
    }

    // RECONCILIAÇÃO CONTRA O ESTADO MAIS RECENTE
    // `rendered` é exatamente a fotografia usada pelo handler do clique.
    // `ultimoDataRef` pode já conter outro cadastro ainda não renderizado.
    // A mescla de três vias aplica só a intenção do clique e conserva tanto
    // alterações de outros módulos quanto dois cadastros rápidos na mesma lista.
    let base=next;
    try{
      base=reconcileOptimisticSnapshot({
        latest:ultimoDataRef.current||rendered,
        rendered,
        intended:next,
      });
    }catch(e){console.error("optimistic-reconcile",e);base=next;}

    // O histórico auditável é criado exclusivamente no servidor, na mesma
    // transação da mutação. O cliente nunca fabrica nem substitui auditoria.
    const normalized = normalizeData(base);
    ultimoDataRef.current = normalized;   // registra sincronamente o estado mais recente
    dataAtualRef.current = normalized;    // e adianta o espelho (o effect confirmaria depois)
    setData(normalized);   // otimista: a interface não trava esperando a rede

    // Enfileira: se ja ha um save em voo, este estado apenas substitui o
    // proximo a enviar. Nunca ha dois saves simultaneos - fim dos 409 do
    // proprio dispositivo contra si mesmo.
    return saveQueueRef.current.enqueue(normalized);
  }, [data,showToast]);

  // Ponte de migração para comandos por agregado. O comando é criado dentro
  // da atualização funcional, portanto `expectedVersion` é verificado contra
  // a entidade realmente vigente — não contra um render antigo do componente.
  // Comandos críticos não passam mais pelo save por seções: o servidor lê a
  // versão autoritativa, valida a entidade e persiste a alteração com sua
  // chave idempotente. A corrente evita que dois cliques deste navegador
  // disputem a mesma versão da entidade entre si.
  const commandTailRef=useRef(Promise.resolve());
  const dispatchOperationalCommand=useCallback(commandOrFactory=>{
    const executar=async()=>{
      // Não misturamos um comando versionado com um snapshot local ainda não
      // confirmado. Se a fila não puder esvaziar, preservar a edição local é
      // mais seguro que executar o comando sobre uma base desconhecida.
      if(saveQueueRef.current?.hasPending()){
        const drained=await saveQueueRef.current.waitForIdle();
        if(!drained.ok||saveQueueRef.current?.hasPending())return {ok:false,state:drained.state,reason:drained.reason||"Há alterações locais aguardando sincronização. Use o indicador de salvamento para resolver a pendência e tente novamente."};
      }
      const atual=dataAtualRef.current||DEFAULT();
      const command=typeof commandOrFactory==="function"?commandOrFactory(atual):commandOrFactory;
      const resposta=await executarComandoOperacional(command);
      if(!resposta?.ok){
        // Só entra na fila offline durável quando a falha é de conectividade
        // (status 0/429/5xx — mesmo critério de retryable do save-queue), não
        // quando o servidor rejeitou a regra de negócio (ex.: validação),
        // caso em que repetir offline só confundiria o usuário.
        const offlineSpec=OFFLINE_QUEUEABLE_COMMANDS[command?.type];
        const retryable=[0,429,500,502,503,504].includes(Number(resposta?.status||0));
        if(offlineSpec&&retryable&&campoOfflineStoreRef.current){
          const entityId=offlineSpec.entityId(command)||command.idempotencyKey;
          const queued=await campoOfflineStoreRef.current.enqueue({
            type:offlineSpec.offlineType,idempotencyKey:command.idempotencyKey,
            entityId,payload:command,
          });
          if(queued.ok){
            showToast("Sem conexão. O lançamento foi guardado neste dispositivo e será enviado ao reconectar.","error");
            return {ok:true,offlineQueued:true,data:atual};
          }
        }
        return {ok:false,reason:resposta?.reason||resposta?.error||"O servidor não confirmou o comando operacional."};
      }
      const recebeuPatch=resposta.sections&&typeof resposta.sections==="object";
      if(recebeuPatch){
        await update({
          __adotarServidorPatch:true,
          sections:resposta.sections,
          updatedAt:resposta.updatedAt,
        });
      }else{
        await update({__adotarServidor:true,data:resposta.data,updatedAt:resposta.updatedAt});
      }
      const confirmado=dataAtualRef.current||resposta.data||DEFAULT();
      return {
        ok:true,idempotent:!!resposta.idempotent,data:confirmado,
        ...(resposta.copied!=null?{copied:resposta.copied}:{}),
        ...(resposta.summary!=null?{summary:resposta.summary}:{}),
      };
    };
    const pendente=commandTailRef.current.then(executar,executar);
    commandTailRef.current=pendente.catch(()=>undefined);
    return pendente;
  },[update,showToast]);

  // Ao reconectar, reenvia os comandos guardados offline (Fase 3 do roadmap
  // de arquitetura) reusando a mesma idempotencyKey gerada no momento do
  // salvamento — o servidor já deduplica por essa chave (ver `duplicate()` em
  // operational-commands.js), então repetir com segurança não exige lógica
  // nova aqui.
  useEffect(()=>{
    const retomarOffline=async()=>{
      const store=campoOfflineStoreRef.current;
      if(!store)return;
      let pendentes=[];
      try{pendentes=await store.list();}catch{return;}
      const aguardando=pendentes.filter(item=>item.status==="pendente");
      if(!aguardando.length)return;
      let sincronizados=0;
      for(const operacao of aguardando){
        const resultado=await dispatchOperationalCommand(()=>operacao.payload);
        // offlineQueued significa que dispatchOperationalCommand tentou de
        // novo, falhou por conectividade e reenfileirou (idempotente) — ainda
        // não chegou no servidor. Marcar como resolvido aqui apagaria a
        // pendência de um dado que continua só neste dispositivo.
        if(resultado?.offlineQueued)continue;
        await store.resolve({
          idempotencyKey:operacao.idempotencyKey,
          ok:!!resultado?.ok,
          error:resultado?.ok?"":(resultado?.reason||"Falha ao sincronizar."),
        });
        if(resultado?.ok)sincronizados+=1;
      }
      if(sincronizados>0){
        showToast(`${sincronizados} lançamento(s) offline sincronizado(s).`);
      }
    };
    window.addEventListener("online",retomarOffline);
    retomarOffline();
    return()=>window.removeEventListener("online",retomarOffline);
  },[dispatchOperationalCommand,showToast]);

  const executeAttendanceCommand=useCallback(async command=>{
      // Achado de 25/08/2026: ESTE guard (esperar saveQueueRef esvaziar antes
      // de registrar ponto) é herança de antes da Fase 1.5 (ver
      // server/domain-row-routing.js), quando Ponto ainda disputava a MESMA
      // linha/versão que o resto do cadastro. Hoje o servidor sempre relê a
      // linha de Ponto (e a linha por obra) do zero, sob lock, dentro de
      // executarComandoPontoBloqueado - nunca usa o snapshot local do
      // navegador para validar ou gravar um comando de ponto. E a
      // reconciliação otimista de `update()` (reconcileOptimisticSnapshot)
      // já preserva o `attendance` mais recente via `ultimoDataRef`
      // independente do estado da fila. Ou seja: um conflito de gravação
      // travado em outro domínio (ex.: dois navegadores editando um
      // fornecedor) não tem mais nenhuma razão técnica para bloquear o
      // registro de ponto - e a fila geral pode ficar presa em CONFLICT
      // (por design, só sai com resolução explícita do usuário - ver
      // save-queue.test.js) por tempo indefinido, travando o Ponto junto sem
      // necessidade. Reproduzido no achado de produção de 25/08/2026: o
      // banner fixo "Há alterações locais ainda não confirmadas..." impedia
      // bater ponto mesmo sem nenhuma edição pendente do próprio Ponto.
      attendanceCommandInFlightRef.current+=1;
      // O indicador de salvamento do cabeçalho (`estadoSalvar`) é compartilhado
      // com a fila geral (saveQueueRef). Se ela estiver presa em CONFLICT/
      // FAILED/OFFLINE - um problema real, em outro domínio, que só sai com
      // ação do usuário -, um registro de ponto bem-sucedido não deve
      // mascarar esse indicador de volta para SAVING/IDLE: o banner de
      // conflito (`conflito`, mais abaixo) continua visível de qualquer
      // forma, mas o pilulazinho do cabeçalho ficaria enganosamente "ok".
      const estadoGeralBloqueado=()=>[
        SAVE_QUEUE_STATE.CONFLICT,SAVE_QUEUE_STATE.FAILED,SAVE_QUEUE_STATE.OFFLINE,
      ].includes(saveQueueRef.current?.getState());
      const refletirEstadoPonto=estado=>{if(!estadoGeralBloqueado())setEstadoSalvar(estado);};
      refletirEstadoPonto(SAVE_QUEUE_STATE.SAVING);
      try{
        let resposta=null;
        for(let attempt=0;attempt<=3;attempt+=1){
          resposta=await executarComandoPonto(command);
          if(resposta?.ok)break;
          const retryable=[0,429,500,502,503,504].includes(Number(resposta?.status||0));
          if(!retryable||attempt===3)break;
          const serverDelay=Number(resposta?.status||0)===429
            ?Math.max(0,Number(resposta?.retryAfter||resposta?.retry_after_seconds||0)*1000)
            :0;
          await new Promise(resolve=>window.setTimeout(resolve,Math.max(1500*(attempt+1),serverDelay)));
        }
        if(!resposta?.ok){
          refletirEstadoPonto(SAVE_QUEUE_STATE.FAILED);
          return {
            ok:false,status:Number(resposta?.status||0),code:resposta?.code||"",
            reason:resposta?.error||"O servidor não confirmou o registro de ponto.",
          };
        }
        const atual=normalizeData(applyAttendanceServerResult(dataAtualRef.current||DEFAULT(),resposta.result));
        const base=normalizeData(applyAttendanceServerResult(baseServidorRef.current||DEFAULT(),resposta.result));
        adoptServerVersion(resposta.updatedAt);
        baseServidorRef.current=base;
        ultimoDataRef.current=atual;
        dataAtualRef.current=atual;
        setData(atual);
        setUltimaSync(new Date());
        refletirEstadoPonto(SAVE_QUEUE_STATE.IDLE);
        return {ok:true,idempotent:!!resposta.idempotent,result:resposta.result,data:atual};
      }catch(error){
        console.error("attendance-command",error);
        refletirEstadoPonto(SAVE_QUEUE_STATE.FAILED);
        return {ok:false,status:0,reason:"O servidor não confirmou o registro de ponto."};
      }finally{
        attendanceCommandInFlightRef.current=Math.max(0,attendanceCommandInFlightRef.current-1);
      }
  },[]);

  const dispatchAttendanceCommand=useCallback(commandOrFactory=>{
    const command=typeof commandOrFactory==="function"
      ?commandOrFactory(dataAtualRef.current||DEFAULT())
      :commandOrFactory;
    if(!attendanceQueueRef.current){
      attendanceQueueRef.current=createAttendanceCommandQueue({
        execute:executeAttendanceCommand,
        createOperationId:pointOperationId,
      });
    }
    return attendanceQueueRef.current.enqueue(command);
  },[executeAttendanceCommand]);

  // Mesmo motivo do cleanup de saveQueueRef acima: zera a ref para que a
  // fila seja recriada após destroy, em vez de ficar permanentemente
  // destruída (visível na montagem dupla do StrictMode em desenvolvimento).
  useEffect(()=>()=>{attendanceQueueRef.current?.destroy?.();attendanceQueueRef.current=null;},[]);

  // Sem sessão restaurada, o boot consulta apenas o estado do primeiro acesso.
  // A identificação do operador e os dados só chegam após a autenticação.
  useEffect(() => {
    if (portalRequest.obraId && portalRequest.token) { setLoading(false); return undefined; }
    let vivo = true;
    (async () => {
      try {
        // Primeiro tenta restaurar a sessão por e-mail enquanto a tela neutra
        // de carregamento ainda está ativa. Antes essa tentativa vivia dentro
        // do LoginScreen: o login chegava a aparecer e só depois era trocado
        // pelo dashboard, causando o salto visual a cada F5.
        const restaurada=await restaurarSessaoEmail();
        if(!vivo)return;
        if(restaurada.ok){
          const normalizados=normalizeData(restaurada.data||DEFAULT());
          baseServidorRef.current=normalizados;
          ultimoDataRef.current=normalizados;
          dataAtualRef.current=normalizados;
          const cadastro=normalizados.usuarios.find(u=>u.id===restaurada.usuario?.id);
          const usuarioCompleto={...restaurada.usuario,...cadastro,pin:undefined};
          setData(normalizados);setCurrentUser(usuarioCompleto);setUltimaSync(new Date());
          setTab(restoreSection(usuarioCompleto.id,allowedTabsForUser(usuarioCompleto)));
          return;
        }
        const r = await listarPerfis();
        if (!vivo) return;
        if (r.erro) setErroInicial(r.erro);
        if (r.precisaSetup) setFirstSetup(true);
      } catch (err) {
        console.error(err);
        if (vivo) showToast("Não consegui falar com o servidor.", "error");
      } finally {
        if (vivo) setLoading(false);
      }
    })();
    return () => { vivo = false; };
  }, [showToast, portalRequest.obraId, portalRequest.token]);

  useEffect(() => {
    if (!data || loading || approvalHandledRef.current) return;
    const params = new URLSearchParams(window.location.search);
    const requestId = params.get("approve_unlock");
    if (!requestId) return;
    approvalHandledRef.current = true;

    const req = (data.unlockRequests||[]).find(r => r.id === requestId);
    if (!req) {
      showToast("Solicitação de permissão não encontrada.", "error");
      window.history.replaceState({}, "", window.location.pathname + window.location.hash);
      return;
    }

    if (req.status === "approved" && req.validUntil && new Date(req.validUntil) > new Date()) {
      showToast("Essa permissão já está aprovada e vigente.");
      window.history.replaceState({}, "", window.location.pathname + window.location.hash);
      return;
    }

    const ok = window.confirm(`Aprovar alteração do ponto por 30 minutos?\n\nObra: ${req.obraName}\nData: ${fmtDateFull(req.date)}\nTrabalhador: ${req.employeeName || "Todos / obra"}`);
    if (!ok) {
      window.history.replaceState({}, "", window.location.pathname + window.location.hash);
      return;
    }

    (async()=>{
      const result=await dispatchAttendanceCommand({
        action:"attendance-unlock-approve",
        operationId:pointOperationId(),
        requestId,
      });
      showToast(
        result?.ok?"Permissão aprovada por 30 minutos.":result?.reason||"A permissão não foi aprovada pelo servidor.",
        result?.ok?"success":"error",
      );
      window.history.replaceState({}, "", window.location.pathname + window.location.hash);
    })();
  }, [data, loading, showToast, dispatchAttendanceCommand]);

  //  Navegação por grupos (filtrada por role)
  const allowedTabs  = allowedTabsForUser(currentUser);
  const allowedTabsKey=allowedTabs.join("|");
  useEffect(()=>{if(currentUser&&!allowedTabs.includes(tab))setTab(allowedTabs[0]||"home");},[currentUser?.id,allowedTabsKey,tab]);
  useEffect(()=>{rememberSection(currentUser?.id,tab,allowedTabs);},[currentUser?.id,allowedTabsKey,tab]);

  // Filtra grupos para mostrar apenas os que o usuário pode acessar
  const visibleGroups = visibleErpModules(allowedTabs,C);
  const activeGroup = activeErpModule(visibleGroups,tab);

  // Grupos abertos na sidebar. Só o grupo da aba atual começa aberto - a barra
  // abre no que importa e deixa o resto recolhido, em vez de despejar 20 abas.
  const [gruposAbertos, setGruposAbertos] = useState(() =>
    activeGroup ? { [activeGroup.id]: true } : {});
  useEffect(()=>{
    if(activeGroup?.id)setGruposAbertos(previous=>previous[activeGroup.id]?previous:{...previous,[activeGroup.id]:true});
  },[activeGroup?.id]);
  const [sidebarCompacta, setSidebarCompacta] = useState(() => {
    try { return window.localStorage.getItem("arcd-sidebar-compacta") === "1"; }
    catch { return false; }
  });

  useEffect(() => {
    try { window.localStorage.setItem("arcd-sidebar-compacta", sidebarCompacta ? "1" : "0"); }
    catch { /* Navegação privada pode bloquear o armazenamento local. */ }
  }, [sidebarCompacta]);

  // Navegar para uma aba mantém o grupo dela aberto (você acabou de ir pra lá).
  const abrirGrupoDaAba = useCallback((tabId) => {
    const g = moduleForTab(tabId);
    if (g) setGruposAbertos(prev => ({ ...prev, [g.id]: true }));
  }, []);

  // Navegação unificada: leva a uma aba (e opcionalmente abre uma obra),
  // fechando a busca. Usado pela busca global e por qualquer atalho.
  const irPara = useCallback((tabId, obraId="", options={}) => {
    if(!options.preserveHistory)setWorkflowTrail(previous=>previous.length?[]:previous);
    const scope=normalizeWorkflowScope(options.scope||{...workflowLastScope.current,...(obraId?{obraId}:{})},currentUser);
    setWorkflowIntent(previous=>({tabId,scope,action:options.action||"navigate",linked:Boolean(options.linked),record:options.record||null,sequence:(previous?.sequence||0)+1}));
    setObraAberta(obraId || "");
    setTab(tabId);
    const g = moduleForTab(tabId);
    if(g)workflowLastTabs.current.set(g.id,{tabId,obraId});
    if (g) setGruposAbertos(prev => ({ ...prev, [g.id]: true }));
    setBuscaAberta(false);
  }, [currentUser?.id,currentUser?.obraId]);
  const navigateWorkflow=useCallback((tabId,scope,options={})=>{
    if(!allowedTabs.includes(tabId))return;
    const normalized=normalizeWorkflowScope(scope||workflowScopes[tabId]||{},currentUser);
    if(tabId!==tab)setWorkflowTrail(previous=>[...previous.slice(-7),{tabId:tab,obraId:obraAberta,scope:normalizeWorkflowScope(workflowScopes[tab]||workflowLastScope.current,currentUser)}]);
    irPara(tabId,"",{...options,linked:true,scope:normalized,preserveHistory:true});
  },[allowedTabsKey,currentUser?.obraId,workflowScopes,irPara,tab,obraAberta]);
  const returnWorkflow=()=>{
    const previous=workflowTrail.at(-1);if(!previous||!allowedTabs.includes(previous.tabId))return;
    setWorkflowTrail(history=>history.slice(0,-1));
    irPara(previous.tabId,previous.obraId,{scope:previous.scope,action:"resume",preserveHistory:true});
  };

  // Índice de busca global: tudo que a pessoa pode querer achar por nome ou
  // número, com a aba de destino. Só monta quando há dados e usuário logado.
  const indiceBusca = useMemo(() => {
    if (!data) return [];
    const ix = [];
    const add = (tipo, rotulo, sub, tabId, obraId="") => rotulo && ix.push({ tipo, rotulo:String(rotulo), sub:sub||"", tabId, obraId });
    (data.obras||[]).forEach(o => add("Obra", o.name, o.address||o.engineer, "obras", o.id));
    (data.employees||[]).filter(e=>e.active!==false).forEach(e => add("Funcionário", e.name, e.role, "equipe"));
    (data.terceirizados||[]).forEach(t => add("Terceirizado", t.name, t.specialty, "terc"));
    (data.equipamentos||[]).filter(e=>e.ativo!==false).forEach(e => add("Equipamento", e.nome, e.categoria, "equip"));
    (data.orcamentos||[]).forEach(o => add("Orçamento", o.nome, "", "orc"));
    (data.pedidos||[]).forEach(p => add("Pedido", p.numero?`Pedido ${p.numero}`:"Pedido", p.fornecedor, "cmp"));
    const com = data.comercial||{};
    (com.leads||[]).forEach(l => add("Lead", l.nome, l.servico, "com_leads"));
    (com.clientes||[]).forEach(c => add("Cliente", c.nome, c.documento, "com_clientes"));
    (com.propostas||[]).forEach(p => add("Proposta", p.numero?`Proposta ${p.numero}`:p.titulo, "", "com_propostas"));
    (com.contratos||[]).forEach(c => add("Contrato", c.numero?`Contrato ${c.numero}`:"Contrato", "", "com_contratos"));
    (com.parceiros||[]).forEach(p => add("Parceiro", p.nome, "", "com_parceiros"));
    // Também indexa as próprias telas, para navegar por nome.
    Object.entries(TAB_META).forEach(([id,m]) => add("Tela", m.label, "abrir tela", id));
    return ix;
  }, [data]);

  // Atalho de teclado: Ctrl/Cmd+K abre a busca; Esc fecha.
  useEffect(() => {
    const onKey = (e) => {
      if ((e.ctrlKey||e.metaKey) && (e.key==="k"||e.key==="K")) { e.preventDefault(); setBuscaAberta(v=>!v); }
      if (e.key==="Escape") setBuscaAberta(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const toggleGrupo = useCallback((gid) => {
    setGruposAbertos(prev => ({ ...prev, [gid]: !prev[gid] }));
  }, []);
  // Obras ativas para o submenu de Engenharia - acesso direto à obra sem
  // passar pela lista em "Obras". Respeita a mesma restrição de obra única
  // que o usuário já tem no resto do sistema.
  const obrasMenuEngenharia = useMemo(() => (data?.obras||[])
    .filter(o => o.status==="active" && (!currentUser?.obraId || o.id===currentUser.obraId))
    .sort((a,b)=>a.name.localeCompare(b.name)),
    [data?.obras, currentUser?.obraId]);

  const hasSubTabs   = activeGroup?.tabs.length > 1 ||
    (activeGroup?.id==="eng_grp" && obrasMenuEngenharia.length>0);

  // Layout responsivo
  const { isDesktop, pick } = useBreakpoint();
  const operationalWorkspace=tab!=="tv";
  const SIDEBAR_W = sidebarCompacta ? 68 : 224;
  // No desktop a navegação vira sidebar → não há barra inferior ocupando espaço
  const navHeight  = isDesktop ? 0 : (hasSubTabs&&!operationalWorkspace ? 132 : 80);
  // Em monitor ultrawide (21:9, 34"), esticar o conteúdo até a borda deixa a
  // linha de texto longa demais e os cards deformados. O teto de 1440px mantém
  // a leitura confortável e centraliza o conteúdo, sem deixar a tela "vazia":
  // as grades já usam 4 colunas nesse tamanho.
  const maxConteudo = "100%";

  const goGroup = (group) => {
    if (group.tabs.includes(tab)) return;
    const previous=workflowLastTabs.current.get(group.id);
    irPara(group.tabs.includes(previous?.tabId)?previous.tabId:group.tabs[0],group.tabs.includes(previous?.tabId)?previous.obraId:"");
  };

  // Alerta rápido: ponto pendente hoje?
  const pontoPending = data
    ? getObraAttendanceSummary(data, today()).some(o => o.hasTeam && !o.completed)
    : false;
  const syncStatus = {
    [SAVE_QUEUE_STATE.IDLE]:{
      label:ultimaSync?`Salvo às ${ultimaSync.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})}`:"Dados sincronizados",
      color:C.green,
    },
    [SAVE_QUEUE_STATE.SAVING]:{label:"Salvando alterações...",color:C.yellowD},
    [SAVE_QUEUE_STATE.RETRY_SCHEDULED]:{label:"Tentando salvar novamente...",color:C.orange},
    [SAVE_QUEUE_STATE.OFFLINE]:{label:"Sem conexão · alterações protegidas",color:C.orange},
    [SAVE_QUEUE_STATE.CONFLICT]:{label:"Conflito de salvamento",color:C.red},
    [SAVE_QUEUE_STATE.FAILED]:{label:"Alterações ainda não salvas",color:C.red},
  }[estadoSalvar]||{label:"Verificando salvamento...",color:C.muted};

  // Alerta: terceiros a pagar esta sexta?
  const tercPending = data ? (() => {
    const fri = getFridayOfWeek(0);
    const { start: ws } = getWeekRange(fri);
    return (data.terceirizados||[]).filter(t=>t.active!==false).some(
      t => !(data.pagsTerceiros||[]).some(p=>p.tercId===t.id&&p.date>=ws&&p.date<=fri)
    );
  })() : false;
  const compraPending=data?(data.solicitacoesCompra||[]).some(s=>s.status==="enviada"&&(!currentUser?.obraId||s.obraId===currentUser.obraId)):false;
  const aprovacaoPendente = data ? (data.instanciasAprovacao||[]).some(i =>
    i?.status==="em_andamento" && i.snapshotPolitica && i.snapshotPolitica.etapas.some((etapa,idx) => {
      const resultado = i.resultadosEtapas?.[idx];
      return resultado?.status==="em_andamento" && (resultado.aprovadoresElegiveis||[]).some(u=>u.id===currentUser?.id);
    })
  ) : false;
  const comercialPending=data?(()=>{
    const com=data.comercial||{},now=Date.now();
    const lead=(com.leads||[]).some(l=>!["perdido","arquivado","transferido"].includes(l.etapa)&&(!l.responsavelId||!l.proximaAtividadeEm));
    const tarefa=(com.atividades||[]).some(a=>a.status!=="concluida"&&a.dataHora&&new Date(a.dataHora).getTime()<now);
    const reuniao=(com.reunioes||[]).some(r=>r.status==="agendada"&&r.dataHora&&new Date(r.dataHora).getTime()<now);
    const contrato=(com.contratos||[]).some(k=>["enviado","aguardando_assinatura"].includes(k.status)||(k.assinadoEm&&!k.entradaPaga));
    return lead||tarefa||reuniao||contrato;
  })():false;

  // Badges por grupo
  const groupBadge = {
    eng_grp: null,
    rh_grp: (allowedTabs.includes("ponto")&&pontoPending)||(allowedTabs.includes("terc")&&tercPending) ? "!" : null,
    fin_grp:   null,
    compras_grp: compraPending ? "!" : null,
    com_grp: comercialPending ? "!" : null,
    equip_grp: null,
    painel:    aprovacaoPendente ? "!" : null,
    admin_grp: null,
  };

  // Pendência na aba exata que a causa - o ponto e os terceirizados.
  const tabBadge = {
    ponto: pontoPending || null,
    terc:  tercPending || null,
    cmp:   compraPending || null,
    com_dash: comercialPending || null,
    aprov_pend: aprovacaoPendente || null,
  };

  //  Conflito de gravação
  // Tudo vive num único JSON, então DUAS pessoas mexendo em módulos
  // DIFERENTES colidem: quem salvar depois é recusado. Antes isso virava um
  // alert() e o trabalho evaporava - imagine perder o ponto de 40 pessoas
  // porque o financeiro conciliou uma transação 30 segundos antes.
  //
  // Agora seguramos o que você tentou salvar e oferecemos reaplicar sobre a
  // versão nova do servidor.
  useEffect(() => {
    const aoConflitar = (e) => setConflito(e.detail || null);
    window.addEventListener("arcd:data-conflict", aoConflitar);
    return () => window.removeEventListener("arcd:data-conflict", aoConflitar);
  }, []);

  const reaplicarSobreServidor = async () => {
    const meu = conflito?.rejectedPayload;
    const base = baseServidorRef.current;   // versão que EU tinha ao começar a editar
    setConflito(null);
    saveQueueRef.current?.discard();
    const fresco = await loadDataWithMeta();
    if (!fresco?.data) { showToast("Não consegui recarregar. Tente de novo.", "error"); return; }

    adoptServerVersion(fresco.updatedAt, fresco.data);

    if (meu) {
      // Merge por seção e por id, em vez de "last write wins" cego. Cada módulo
      // é uma lista de itens com id: quem A e B tocaram em itens DIFERENTES
      // coexiste; só o mesmo item editado pelos dois é que a minha versão vence
      // (e disso o aviso já deixou você ciente). Assim, A mexer em obras e B em
      // terceirizados não faz ninguém perder trabalho.
      const merged = mesclarDados(fresco.data, meu, base);
      const norm = normalizeData(merged);
      const result = await saveDataDetailed(norm,normalizeData(fresco.data));
      if (result.ok) {
        const confirmed=normalizeData(result.merged&&result.data?result.data:norm);
        baseServidorRef.current=confirmed;ultimoDataRef.current=confirmed;dataAtualRef.current=confirmed;
        setData(confirmed);setUltimaSync(new Date());
        showToast("Suas alterações foram mescladas com as da outra pessoa.");
      } else {
        showToast(result.reason||"Ainda em conflito. Recarregue a página.","error");
      }
    } else {
      const norm = normalizeData(fresco.data);
      baseServidorRef.current = norm;
      ultimoDataRef.current = norm;
      dataAtualRef.current = norm;
      setData(norm);
    }
  };

  const descartarMinhaVersao = async () => {
    setConflito(null);
    saveQueueRef.current?.discard();
    const fresco = await loadDataWithMeta();
    if (fresco?.data) {
      adoptServerVersion(fresco.updatedAt, fresco.data);
      const norm = normalizeData(fresco.data);
      baseServidorRef.current = norm;
      ultimoDataRef.current = norm;
      dataAtualRef.current = norm;
      setData(norm);
      showToast("Tela atualizada com a versão do servidor.");
    }
  };

  // O painel de TV permanece aberto por horas. Ele atualiza a fotografia da
  // empresa sem toast e sem disparar um novo save, mantendo a tela pública
  // silenciosa enquanto recebe as alterações feitas pelos operadores.
  const atualizarPainelTV = useCallback(async () => {
    if (saveQueueRef.current?.hasPending()) return;
    const fresco=await loadDataWithMeta();
    if(!fresco?.data)return;
    adoptServerVersion(fresco.updatedAt);
    const norm=normalizeData(fresco.data);
    baseServidorRef.current=norm;ultimoDataRef.current=norm;dataAtualRef.current=norm;
    setData(norm);setUltimaSync(new Date());
  }, []);

  // Sair e trocar usuário agora fazem a mesma coisa por baixo: limpam o PIN da
  // memória e voltam pro login. Não existe mais uma "sessão do Supabase" por
  // cima - o PIN É a sessão.
  const sairDoSistema = async () => {
    if (!window.confirm("Sair do sistema?")) return;
    await encerrarPresenca();
    setCurrentUser(null);
    setData(null);        // os dados saem da memória junto
    encerrarSessao();
  };

  // Tablet compartilhado na obra: troca quem opera, sem a pergunta de confirmação.
  const trocarDeUsuario = async () => {
    await encerrarPresenca();
    setCurrentUser(null);
    setData(null);
    encerrarSessao();
  };

  // ATENÇÃO À ORDEM DOS PORTÕES.
  // `data` agora é null ATÉ o PIN passar. Se testássemos `!data` antes do
  // login, o app ficaria carregando para sempre - os dados nunca chegariam,
  // porque ninguém teria digitado o PIN. Primeiro loading, depois setup,
  // depois login. Só então os dados existem.
  if (portalRequest.obraId && portalRequest.token) {
    return <PortalClientePublico obraId={portalRequest.obraId} token={portalRequest.token}/>;
  }

  if (loading) {
    return (
      <>
        <style>{G}</style>
        <div style={{ minHeight:"100vh", display:"flex", alignItems:"center", justifyContent:"center", background:C.bg }}>
          <div style={{ textAlign:"center" }}>
            <div style={{ width:44, height:44, border:`4px solid ${C.border}`, borderTopColor:C.yellow, borderRadius:"50%", animation:"spin 1s linear infinite", margin:"0 auto 14px" }}/>
            <BrandMark/>
            <p style={{ color:C.muted, marginTop:14 }}>Carregando operação...</p>
          </div>
        </div>
      </>
    );
  }

  //  Tela de login se não há usuário logado
  if (!currentUser) {
    // O servidor devolve o usuário E os dados na mesma resposta - os dados
    // não existiam no navegador antes do PIN passar.
    const handleLogin = (usuario, dados) => {
      const normalizados=normalizeData(dados || DEFAULT());
      baseServidorRef.current = normalizados;   // ponto de partida para merge
      ultimoDataRef.current = normalizados;
      dataAtualRef.current = normalizados;
      const cadastro=normalizados.usuarios.find(item=>item.id===usuario.id);
      const usuarioCompleto={...usuario,...cadastro,pin:undefined};
      setData(normalizados);
      setUltimaSync(new Date());
      setCurrentUser(usuarioCompleto);
      const allowed = allowedTabsForUser(usuarioCompleto);
      setTab(restoreSection(usuarioCompleto.id,allowed));
    };

    return (
      <LoginScreen
        onLogin={handleLogin}
        erroInicial={erroInicial}
        precisaSetup={firstSetup}
      />
    );
  }

  return (
    <>
      <style>{G}</style>
      <div className="arcd-app-shell" data-tab={tab} style={{
        minHeight:"100vh", background:"transparent", color:C.text,
        paddingBottom: isDesktop ? 8 : `calc(${navHeight + 8}px + env(safe-area-inset-bottom))`,
        paddingLeft: isDesktop ? SIDEBAR_W : 0,   // abre espaço p/ a sidebar
        transition: "padding-left .18s ease",
      }}>

        {/*  SIDEBAR (só desktop)  */}
        {isDesktop && (
          <aside className="no-print arcd-sidebar" style={{
            position:"fixed", top:0, left:0, bottom:0, width:SIDEBAR_W, zIndex:90,
            background:C.bg, borderRight:`1px solid ${C.border}`,
            display:"flex", flexDirection:"column",
            boxShadow:"none",
            transition:"width .18s ease",
          }}>
            {/* Marca */}
            <div style={{
              minHeight:64, padding:sidebarCompacta ? "12px 9px" : "13px 10px 12px 16px",
              borderBottom:`1px solid ${C.line}`, display:"flex", alignItems:"center",
              justifyContent:"space-between", gap:8,
            }}>
              {sidebarCompacta
                ? <div style={{ width:30, height:30, borderRadius:C.rMd, display:"grid", placeItems:"center", background:C.yellowDim }}>
                    <Ic n="building" s={17} color={C.yellowD}/>
                  </div>
                : <BrandMark dark signature={false}/>}
              <button
                onClick={()=>setSidebarCompacta(v=>!v)}
                title={sidebarCompacta ? "Expandir menu" : "Minimizar menu"}
                aria-label={sidebarCompacta ? "Expandir menu lateral" : "Minimizar menu lateral"}
                style={{
                  width:30, height:30, flexShrink:0, borderRadius:C.rMd, cursor:"pointer",
                  border:`1px solid ${C.border}`, background:C.surface, color:C.muted,
                  display:"grid", placeItems:"center", fontSize:"var(--arcd-type-control)", lineHeight:1,
                }}
              >{sidebarCompacta ? "›" : "‹"}</button>
            </div>

            {/* Busca global: atalho visível para o Ctrl/Cmd+K. */}
            <div style={{ padding:"10px 10px 4px" }}>
              <button onClick={()=>setBuscaAberta(true)} style={{
                display:"flex", alignItems:"center", justifyContent:sidebarCompacta ? "center" : "flex-start", gap:8, width:"100%",
                background:C.surface, border:`1px solid ${C.border}`, borderRadius:C.rMd,
                padding:sidebarCompacta ? "8px" : "8px 10px", cursor:"pointer", color:C.muted }}
                title={sidebarCompacta ? "Buscar (Ctrl + K)" : undefined}
                aria-label="Buscar no sistema">
                <Ic n="funnel" s={14} color={C.muted}/>
                {!sidebarCompacta && <span style={{ fontSize:"var(--arcd-type-body)", flex:1, textAlign:"left" }}>Buscar...</span>}
                {!sidebarCompacta && <span style={{ fontSize:"var(--arcd-type-caption)", fontWeight:600, border:`1px solid ${C.border}`, borderRadius:4, padding:"1px 5px" }}>⌘K</span>}
              </button>
            </div>
            {/* Navegação: grupos colapsáveis. Clique no cabeçalho abre/fecha;
                o grupo da aba atual já começa aberto. O trilho na cor do grupo
                dá o senso de nível - filho pende do pai. */}
            <nav style={{ flex:1, overflowY:"auto", padding:"10px 8px" }}>
              {visibleGroups.map(group => {
                const aberto = !!gruposAbertos[group.id];
                const badge = groupBadge[group.id];
                const contémAtiva = activeGroup?.id===group.id;

                if (sidebarCompacta) return (
                  <button
                    key={group.id}
                    title={group.label}
                    aria-label={`Abrir grupo ${group.label}`}
                    aria-current={contémAtiva ? "page" : undefined}
                    onClick={() => {
                      setGruposAbertos(prev => ({ ...prev, [group.id]: true }));
                      setSidebarCompacta(false);
                    }}
                    style={{
                      width:"100%", height:42, marginBottom:4, borderRadius:9, cursor:"pointer",
                      border:contémAtiva ? `1px solid ${group.color}55` : "1px solid transparent",
                      background:contémAtiva ? `${group.color}18` : "transparent",
                      color:contémAtiva ? group.color : C.muted,
                      display:"grid", placeItems:"center", position:"relative",
                    }}
                  >
                    <Ic n={group.icon} s={17}/>
                    {badge && (
                      <span style={{ position:"absolute", top:7, right:8, width:6, height:6, borderRadius:"50%", background:group.color }}/>
                    )}
                  </button>
                );

                // Cores do grupo viram variáveis CSS - é o que permite :hover.
                const vars = {
                  "--gc":      group.color,
                  "--gc-hov":  `${group.color}0F`,
                  "--gc-act":  `${group.color}18`,
                  "--gc-rail": aberto ? `${group.color}44` : "transparent",
                };

                return (
                  <div key={group.id} style={{ marginBottom:2, ...vars }}>
                    {/* Cabeçalho clicável. Um grupo fechado que contém a aba
                        atual mostra um ponto na sua cor - você não perde de
                        vista onde está, mesmo com o grupo recolhido. */}
                    <button
                      className="nav-grp-hd"
                      title={group.description}
                      data-open={aberto || contémAtiva}
                      onClick={() => toggleGrupo(group.id)}
                      aria-expanded={aberto}
                    >
                      <Ic n={group.icon} s={13}/>
                      <span>{group.label}</span>
                      {badge && <span className="nav-dot" style={{ marginLeft:"auto" }}/>}
                      {!badge && !aberto && contémAtiva &&
                        <span style={{ marginLeft:"auto", width:5, height:5, borderRadius:"50%",
                                       background:"var(--gc)" }}/>}
                      <span className="nav-chev" style={{ marginLeft:(badge||(!aberto&&contémAtiva)) ? 8 : "auto" }}>›</span>
                    </button>

                    {/* Corpo - só monta quando aberto */}
                    {aberto && (
                      <div className="nav-body">
                        {group.tabs.map(tabId => {
                          const meta = TAB_META[tabId];
                          const ativo = tab === tabId;
                          const temPend = tabBadge?.[tabId];
                          return (
                            <button
                              key={tabId}
                              className="nav-item"
                              data-active={ativo}
                              onClick={() => irPara(tabId)}
                              aria-current={ativo ? "page" : undefined}
                            >
                              <Ic n={meta.icon} s={13}/>
                              <span>{meta.label}</span>
                              {temPend && <span className="nav-dot"/>}
                            </button>
                          );
                        })}
                        {group.id==="eng_grp" && obrasMenuEngenharia.length>0 && (<>
                          <p style={{fontSize:"var(--arcd-type-caption)",fontWeight:600,color:C.muted,textTransform:"uppercase",letterSpacing:.6,margin:"8px 10px 3px"}}>Obras ativas</p>
                          {obrasMenuEngenharia.map(obra => (
                            <button
                              key={obra.id}
                              className="nav-item"
                              data-active={tab==="obras"&&obraAberta===obra.id}
                              onClick={() => irPara("obras", obra.id)}
                              aria-current={(tab==="obras"&&obraAberta===obra.id) ? "page" : undefined}
                              title={obra.name}
                            >
                              <Ic n="building" s={13}/>
                              <span style={{overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{obra.name}</span>
                            </button>
                          ))}
                        </>)}
                      </div>
                    )}
                  </div>
                );
              })}
            </nav>

            {/* Usuário + sair */}
            <div style={{ padding:sidebarCompacta ? "10px 8px" : "10px 12px", borderTop:`1px solid ${C.line}`, background:C.surface }}>
              {sidebarCompacta ? (
                <div style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:7 }}>
                  <div title={`${currentUser?.nome} · ${ROLES.find(r=>r.v===currentUser?.role)?.l || "Usuário"}`} style={{
                    width:30, height:30, borderRadius:"50%", display:"grid", placeItems:"center",
                    background:`${ROLES.find(r=>r.v===currentUser?.role)?.color || C.yellow}22`,
                    color:ROLES.find(r=>r.v===currentUser?.role)?.color || C.yellow,
                    fontSize:"var(--arcd-type-body)", fontWeight:600,
                  }}>{(currentUser?.nome || "U").trim().charAt(0).toUpperCase()}</div>
                  <button onClick={sairDoSistema} title="Sair do sistema" aria-label="Sair do sistema" style={{
                    width:30, height:28, background:"transparent", border:0, color:C.muted,
                    fontSize:"var(--arcd-type-control)", cursor:"pointer", lineHeight:1,
                  }}>x</button>
                </div>
              ) : (
              <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:6 }}>
                <div style={{ display:"flex", alignItems:"center", gap:6, minWidth:0 }}>
                  <div style={{
                    width:7, height:7, borderRadius:"50%", flexShrink:0,
                    background: ROLES.find(r=>r.v===currentUser?.role)?.color || C.yellow,
                  }}/>
                  <div style={{ minWidth:0 }}>
                    <p style={{ fontSize:"var(--arcd-type-label)", fontWeight:600, color:C.text, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                      {currentUser?.nome}
                    </p>
                    <p style={{ fontSize:"var(--arcd-type-caption)", color:C.muted }}>
                      {ROLES.find(r=>r.v===currentUser?.role)?.l}
                    </p>
                  </div>
                </div>
                <div style={{display:"flex",gap:2,flexShrink:0}}>
                  <button onClick={trocarDeUsuario} title="Trocar usuário (tablet compartilhado)" style={{
                    background:"transparent", border:0, color:C.muted,
                    fontSize:"var(--arcd-type-control)", cursor:"pointer", lineHeight:1, padding:"0 3px",
                  }}></button>
                  <button onClick={sairDoSistema} title="Sair do sistema" style={{
                    background:"transparent", border:0, color:C.muted,
                    fontSize:"var(--arcd-type-control)", cursor:"pointer", lineHeight:1, padding:"0 3px",
                  }}>x</button>
                </div>
              </div>
              )}
            </div>
          </aside>
        )}

        {/*  HEADER  */}
        {/* Cabeçalho e banner de conflito compartilham UM único wrapper sticky
            (em vez de cada um ter seu próprio position:sticky;top:0) - assim
            o banner nunca "some" ao rolar a tela para baixo. Achado ao
            investigar "orçamento não salva com mais de uma pessoa": o banner
            de conflito É mostrado (nada silencioso), mas antes rolava para
            fora da tela junto com o resto do conteúdo em telas longas (ex.:
            Memória de Cálculo do Orçamento) - o usuário seguia editando sem
            notar que a fila de salvamento estava travada aguardando a
            resolução do conflito, e via a mudança local sem perceber que
            nada estava chegando ao servidor. */}
        <div style={{ position:"sticky", top:0, zIndex:50 }}>
        <header className="no-print arcd-topbar" style={{
          background:"rgba(255,255,255,.97)", backdropFilter:"blur(18px)",
          borderBottom:`1px solid ${C.border}`,
          boxShadow:"none",
        }}>
          <div className="app-header-inner" style={{ maxWidth:maxConteudo, margin:"0 auto", padding: isDesktop ? "12px 22px" : "10px 14px", display:"flex", justifyContent:"space-between", alignItems:"center", gap:10 }}>
            <div className="app-header-context" style={{ display:"flex", alignItems:"center", gap:12 }}>
              {/* No desktop a marca vive na sidebar - repetir aqui é ruído */}
              {!isDesktop && <BrandMark compact/>}
              {/* Breadcrumb */}
              <div className="app-breadcrumb" style={{ display:"flex", alignItems:"center", gap:6 }}>
                {!isDesktop&&operationalWorkspace?<select className="workspace-module-select" aria-label={`Telas de ${activeGroup?.label}`} value={tab==="obras"&&obrasMenuEngenharia.some(obra=>obra.id===obraAberta)?`obra:${obraAberta}`:tab} onChange={event=>event.target.value.startsWith("obra:")?irPara("obras",event.target.value.slice(5)):irPara(event.target.value)}>
                  {activeGroup?.tabs.map(id=><option key={id} value={id}>{TAB_META[id]?.label||id}</option>)}
                  {activeGroup?.id==="eng_grp"&&obrasMenuEngenharia.length>0&&<optgroup label="Obras ativas">{obrasMenuEngenharia.map(obra=><option key={obra.id} value={`obra:${obra.id}`}>{obra.name}</option>)}</optgroup>}
                </select>:<><span style={{ fontSize:"var(--arcd-type-label)", color:activeGroup?.color, fontWeight:600, textTransform:"uppercase", letterSpacing:.8 }}>
                  {activeGroup?.label}
                </span>
                {hasSubTabs && (
                  <>
                    <span aria-hidden="true" style={{ fontSize:"var(--arcd-type-label)", color:C.muted }}>›</span>
                    <span style={{ fontSize:"var(--arcd-type-label)", color:C.muted, fontWeight:600 }}>
                      {TAB_META[tab]?.label}
                    </span>
                  </>
                )}</>}
              </div>
            </div>

            {/* Usuário logado + ponto rápido */}
            <div className="app-header-actions" style={{ display:"flex", alignItems:"center", gap:8 }}>
              <div
                className="app-save-status"
                data-testid="save-status"
                data-state={estadoSalvar}
                role="status"
                aria-live="polite"
                title={syncStatus.label}
                style={{
                  display:"inline-flex",alignItems:"center",gap:6,minHeight:32,
                  padding:"5px 9px",border:`1px solid ${syncStatus.color}44`,
                  borderRadius:C.rMd,background:`${syncStatus.color}0B`,
                  color:C.text,whiteSpace:"nowrap",
                }}
              >
                <span
                  aria-hidden="true"
                  style={{
                    width:7,height:7,borderRadius:"50%",background:syncStatus.color,flexShrink:0,
                    boxShadow:estadoSalvar===SAVE_QUEUE_STATE.SAVING?`0 0 0 4px ${syncStatus.color}1F`:"none",
                  }}
                />
                <span className="app-save-status-label" style={{fontSize:"var(--arcd-type-label)",fontWeight:600}}>
                  {syncStatus.label}
                </span>
              </div>
              {/* Badge do usuário - no desktop já aparece no rodapé da sidebar */}
              <div className="app-user-badge" style={{ display: isDesktop ? "none" : "flex", alignItems:"center", gap:6, padding:"4px 10px", background:C.surface, borderRadius:C.rMd, border:`1px solid ${C.border}` }}>
                <div style={{ width:7, height:7, borderRadius:"50%", background:ROLES.find(r=>r.v===currentUser?.role)?.color||C.yellow, flexShrink:0 }}/>
                <p style={{ fontSize:"var(--arcd-type-label)", fontWeight:600, color:C.text, maxWidth:80, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{currentUser?.nome}</p>
                <button onClick={sairDoSistema} style={{
                  background:"transparent", border:0, color:C.muted, fontSize:"var(--arcd-type-control)",
                  cursor:"pointer", lineHeight:1, padding:"0 2px",
                }} title="Sair">x</button>
              </div>

              {/* Ponto rápido */}
              {allowedTabs.includes("ponto") && (
                <button
                  className="app-quick-point"
                  aria-label="Abrir Ponto"
                  onClick={() => setTab("ponto")}
                  style={{
                    background: tab==="ponto" ? C.yellow : C.surface,
                    color: tab==="ponto" ? C.text : C.text,
                    border:`1px solid ${tab==="ponto"?C.yellow:C.border}`,
                    borderRadius:C.rMd, padding:"7px 12px",
                    display:"inline-flex", alignItems:"center", gap:5,
                    cursor:"pointer", fontFamily:"var(--arcd-font-sans)",
                    fontWeight:600, textTransform:"uppercase", letterSpacing:.6, fontSize:"var(--arcd-type-control)",
                    position:"relative",
                    "--ic-color": C.text,
                  }}
                >
                  <Ic n="clock" s={13}/> <span className="app-quick-label">Ponto</span>
                  {pontoPending && tab!=="ponto" && (
                    <span style={{ position:"absolute", top:-4, right:-4, width:9, height:9, background:C.red, borderRadius:"50%", border:`2px solid ${C.bg}` }}/>
                  )}
                </button>
              )}
            </div>
          </div>
        </header>

        {/*  CONTEÚDO  */}
        {/* Banner de conflito de gravação */}
        {conflito && (
          <div style={{
            maxWidth:maxConteudo, margin:"0 auto",
            padding: isDesktop ? "12px 22px 0" : "12px 14px 0",
          }}>
            <div style={{
              background:`${C.orange}0E`, border:`1.5px solid ${C.orange}`,
              borderRadius:8, padding:"12px 14px",
            }}>
              <p style={{fontSize:"var(--arcd-type-body)",fontWeight:600,color:C.orange,fontFamily:"var(--arcd-font-sans)"}}>
                ! Seu salvamento foi recusado
              </p>
              <p style={{fontSize:"var(--arcd-type-label)",color:C.muted,marginTop:4,lineHeight:1.55}}>
                Outra pessoa salvou alterações enquanto você trabalhava. <strong style={{color:C.text}}>
                Nada seu foi perdido</strong> - o que você fez está guardado aqui.
                Você pode reaplicar por cima da versão nova, ou descartar e recomeçar da versão do servidor.
              </p>
              <div style={{display:"flex",gap:8,marginTop:10,flexWrap:"wrap"}}>
                <Btn size="sm" onClick={reaplicarSobreServidor}>
                  <Ic n="check"/> Reaplicar minhas alterações
                </Btn>
                <Btn size="sm" v="ghost" onClick={descartarMinhaVersao}>
                  Descartar e recarregar
                </Btn>
              </div>
            </div>
          </div>
        )}
        </div>

        <main className="arcd-main" data-workspace={operationalWorkspace?tab:undefined} style={{ maxWidth:maxConteudo, margin:"0 auto", padding: isDesktop ? "24px 24px" : 14 }}>
          {edicaoRecusada&&<div role="alert" data-testid="save-rejected" style={{display:"flex",gap:10,alignItems:"flex-start",justifyContent:"space-between",flexWrap:"wrap",marginBottom:12,padding:"10px 12px",border:`1px solid ${C.red}55`,background:`${C.red}0D`,borderRadius:C.rMd,color:C.text}}>
            <span style={{fontSize:"var(--arcd-type-label)",lineHeight:1.5}}><b>Alteração não salva e desfeita</b> às {edicaoRecusada.em.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})}: {edicaoRecusada.motivo}{edicaoRecusada.secoes.length?` (${edicaoRecusada.secoes.slice(0,4).join(", ")}${edicaoRecusada.secoes.length>4?"…":""})`:""}. A tela voltou ao último estado confirmado.</span>
            <Btn v="ghost" size="sm" onClick={()=>setEdicaoRecusada(null)}>Entendi</Btn>
          </div>}
          {tab!=="projetos"&&allowedTabs.includes("projetos")&&(data.engineeringProjects||[]).some(project=>(project.sessions||[]).some(session=>session.userId===currentUser.id&&!session.endedAt))&&<Suspense fallback={null}><ProjectTimerStatus projects={data.engineeringProjects} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand} onOpen={()=>setTab("projetos")} /></Suspense>}
          <WorkflowContext.Provider value={{navigate:navigateWorkflow,intent:workflowIntent,scopes:workflowScopes,rememberScope:rememberWorkflowScope,views:workflowViews.current,goBack:returnWorkflow,returnTo:workflowTrail.length?{label:`Voltar a ${workflowTrail.at(-1).obraId?(data.obras||[]).find(o=>o.id===workflowTrail.at(-1).obraId)?.name||"Obra":TAB_META[workflowTrail.at(-1).tabId]?.label||"tela anterior"}`}:null}}>
          <WorkflowReturn/>

          {tab === "home"   && (["engenheiro","engenheiro_auditor"].includes(currentUser?.role)
            ? <DashboardEngenheiro data={data} update={update} showToast={showToast} onTab={irPara} ultimaSync={ultimaSync} currentUser={currentUser} saveState={estadoSalvar}/>
            : <Dashboard data={data} update={update} showToast={showToast} onTab={irPara} onAbrirObra={obraId=>irPara("obras",obraId)} ultimaSync={ultimaSync} currentUser={currentUser}
                              onBuscar={()=>setBuscaAberta(true)} onAtualizar={descartarMinhaVersao} saveState={estadoSalvar} />)}
          {tab === "tv" && <PainelTV data={data} ultimaSync={ultimaSync} onAtualizar={atualizarPainelTV} allowedTabs={allowedTabs}/>}
          {tab === "chat" && <Comunicacao data={data} currentUser={currentUser} showToast={showToast}/>}
          {tab === "admin_central" && <Suspense fallback={<div className="arcd-page-loading">Carregando central do administrador...</div>}><CentralAdministrador data={data} update={update} showToast={showToast} currentUser={currentUser}/></Suspense>}
          {tab === "aprov_pend" && <Suspense fallback={<div className="arcd-page-loading">Carregando aprovações...</div>}><AprovacoesPendentesView data={data} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand}/></Suspense>}
          {tab.startsWith("com_") && <Suspense fallback={<div className="arcd-page-loading">Carregando comercial...</div>}><Comercial data={data} update={update} dispatchCommand={dispatchOperationalCommand} showToast={showToast} currentUser={currentUser} view={tab} onTab={irPara} /></Suspense>}
          {tab === "obras"  && (obraAberta
            ? <ObraDetalhe data={data} obraId={obraAberta} update={update} showToast={showToast}
                           currentUser={currentUser} dispatchCommand={dispatchOperationalCommand}
                           dispatchAttendanceCommand={dispatchAttendanceCommand}
                           onVoltar={() => setObraAberta("")}
                           onEditarObra={()=>{sessionStorage.setItem("arcd_editar_obra",obraAberta);setObraAberta("");}}
                           onTab={irPara} />
            : <Obras       data={data} update={update} showToast={showToast} dispatchCommand={dispatchOperationalCommand}
                           currentUser={currentUser} onAbrirObra={setObraAberta} />)}
          {tab === "orc"    && <Suspense fallback={<div className="arcd-page-loading">Carregando orçamento...</div>}><Orcamento   data={data} update={update} showToast={showToast} currentUser={currentUser} /></Suspense>}
          {tab === "projetos" && <Suspense fallback={<div className="arcd-page-loading">Carregando projetos...</div>}><ProjetosEngenharia data={data} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand} showToast={showToast} onRefresh={async()=>{const fresh=await loadDataWithMeta();if(!fresh?.data)throw new Error("Falha ao atualizar projetos.");await update({__adotarServidorPatch:true,sections:{engineeringProjects:fresh.data.engineeringProjects||[]},updatedAt:fresh.updatedAt});}} /></Suspense>}
          {tab === "plan"   && <Suspense fallback={<div className="arcd-page-loading">Carregando planejamento...</div>}><Planejamento data={data} update={update} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand} /></Suspense>}
          {tab === "plan_suprimentos" && <Suspense fallback={<div className="arcd-page-loading">Carregando suprimentos...</div>}><LazyMarcosCurvaASuprimentos data={data} update={update} showToast={showToast} currentUser={currentUser} /></Suspense>}
          {tab === "rdo"    && <Suspense fallback={<div className="arcd-page-loading">Carregando diário de obra...</div>}><DiarioObra data={data} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand} /></Suspense>}
          {tab === "conferencia" && <Suspense fallback={<div className="arcd-page-loading">Carregando conferência...</div>}><Conferencia data={data} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand} /></Suspense>}
          {tab === "med"    && <MedicaoEvolucao data={data} update={update} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand} onAbrirPlanejamento={()=>irPara("plan")}/>}
          {tab === "obsoletos" && <Obsoletos    data={data} update={update} showToast={showToast} onTab={irPara} dispatchCommand={dispatchOperationalCommand} />}
          {tab === "equipe" && <Suspense fallback={<div className="arcd-page-loading">Carregando equipe...</div>}><EquipeView data={data} update={update} showToast={showToast} dispatchCommand={dispatchOperationalCommand} currentUser={currentUser} onTab={irPara} /></Suspense>}
          {tab === "terc"   && <Suspense fallback={<div className="arcd-page-loading">Carregando terceiros...</div>}><Terceiros data={data} update={update} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand} /></Suspense>}
          {tab === "ponto"  && <Ponto       data={data} update={update} showToast={showToast} currentUser={currentUser} dispatchAttendanceCommand={dispatchAttendanceCommand} dispatchCommand={dispatchOperationalCommand} onTab={irPara}/>}
          {tab === "equipe_obras" && <EquipeObras key={currentUser?.id} onTab={irPara} allowedTabs={allowedTabs}/>}
          {tab === "ponto_geral" && <PontoGeral data={data} update={update} showToast={showToast} currentUser={currentUser} onTab={irPara} dispatchAttendanceCommand={dispatchAttendanceCommand} dispatchCommand={dispatchOperationalCommand}/>}
          {tab === "ponto_app" && <PontoEletronico data={data} showToast={showToast} currentUser={currentUser} dispatchAttendanceCommand={dispatchAttendanceCommand} onTab={irPara}/>}
          {tab === "folha"  && <Suspense fallback={<div className="arcd-page-loading">Carregando folha...</div>}><Folha       data={data} showToast={showToast} onTab={irPara} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand} /></Suspense>}
          {tab === "resc"   && <Suspense fallback={<div className="arcd-page-loading">Carregando rescisão...</div>}><RescisaoView data={data} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand} /></Suspense>}
          {tab === "rh_indic" && <Suspense fallback={<div className="arcd-page-loading">Carregando indicadores...</div>}><IndicadoresView data={data} /></Suspense>}
          {tab === "dre_emp"  && <DREEmpresa onOpenWork={allowedTabs.includes("obras")?obraId=>irPara("obras",obraId):undefined} data={data} update={update} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand} />}
          {tab === "dre"      && <DRE          data={data} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand} />}
          {tab === "fin"      && <Financeiro onOpenWork={allowedTabs.includes("obras")?obraId=>irPara("obras",obraId):undefined} data={data} update={update} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand} />}
          {tab === "conc"     && <Suspense fallback={<div className="arcd-page-loading">Carregando conciliação...</div>}><Conciliacao  data={data} update={update} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand}/></Suspense>}
          {tab === "est"      && <Suspense fallback={<div className="arcd-page-loading">Carregando estoque...</div>}><Estoque data={data} update={update} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand}/></Suspense>}
          {tab === "equip"    && <Suspense fallback={<div className="arcd-page-loading">Carregando equipamentos...</div>}><Equipamentos data={data} update={update} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand}/></Suspense>}
          {tab === "equip_fin"&& <Suspense fallback={<div className="arcd-page-loading">Carregando equipamentos...</div>}><Equipamentos data={data} update={update} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand} contexto="financeiro"/></Suspense>}
          {tab === "patrimonio"&& <Suspense fallback={<div className="arcd-page-loading">Carregando patrimônio...</div>}><PatrimonioEmpresa data={data} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand}/></Suspense>}
          {tab === "licenca"  && <Suspense fallback={<div className="arcd-page-loading">Carregando licenciamento...</div>}><Licenciamento data={data} update={update} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand}/></Suspense>}
          {tab === "cmp"      && <Suspense fallback={<div className="arcd-page-loading">Carregando compras...</div>}><Compras      data={data} update={update} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand}/></Suspense>}
          {tab === "fornecedores" && <RankingFornecedores data={data} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand}/>}
          {tab === "suprimentos" && <CotacoesMaterial data={data} update={update} showToast={showToast} onTab={irPara}/>}
          {tab === "cad"      && <Cadastros    data={data} update={update} showToast={showToast} onTab={irPara} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand}/>}
          {tab === "medicoes" && <Suspense fallback={<div className="arcd-page-loading">Carregando medições...</div>}><MedicoesView data={data} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand} /></Suspense>}
          {tab === "caixa"    && <CaixaObra    data={data} showToast={showToast} currentUser={currentUser} dispatchCommand={dispatchOperationalCommand} />}
          {tab === "relat"    && <Relatorios   data={data} showToast={showToast} currentUser={currentUser} />}
          {tab === "ia"     && <AgenteIA    data={data} showToast={showToast} onTab={irPara} />}
          {tab === "ia_config" && <ConfiguracaoIA showToast={showToast}/>}
          {tab === "config" && <Config      data={data} update={update} showToast={showToast} currentUser={currentUser} onLogout={sairDoSistema} dispatchAttendanceCommand={dispatchAttendanceCommand} dispatchCommand={dispatchOperationalCommand} />}
          {["dre","dre_emp","conc"].includes(tab)&&<DreReconciliationManager data={data} update={update} currentUser={currentUser}/>}
          </WorkflowContext.Provider>
        </main>

        {/*  NAV INFERIOR - só celular/tablet (no desktop é sidebar)  */}
        {!isDesktop && (
        <nav className="no-print arcd-mobile-nav" style={{
          position:"fixed", bottom:0, left:0, right:0, zIndex:80,
          background:"rgba(255,255,255,.98)", backdropFilter:"blur(20px)",
          borderTop:`1px solid ${C.border}`,
          boxShadow:"none",
        }}>
          <div style={{ maxWidth:maxConteudo, margin:"0 auto" }}>

            {/* Sub-tabs (só aparece quando grupo tem >1 aba) */}
            {hasSubTabs&&!operationalWorkspace && (
              <div className="mobile-subnav" style={{
                display:"flex", gap:5, overflowX:"auto", padding:"8px 12px 6px",
                borderBottom:`1px solid ${C.line}55`,
                scrollbarWidth:"none",
              }}>
                {activeGroup?.tabs.map(tabId => {
                  const meta = TAB_META[tabId];
                  const isActive = tab === tabId;
                  return (
                    <button key={tabId} data-active={isActive} onClick={() => irPara(tabId)} style={{
                      flexShrink:0,
                      background: isActive ? `${activeGroup.color}22` : "transparent",
                      color: isActive ? activeGroup.color : C.muted,
                      border: `1.5px solid ${isActive ? activeGroup.color : C.line}`,
                      borderRadius:999, padding:"5px 14px",
                      fontFamily:"var(--arcd-font-sans)", fontWeight:600, fontSize:"var(--arcd-type-control)",
                      letterSpacing:.5, cursor:"pointer", whiteSpace:"nowrap",
                      display:"flex", alignItems:"center", gap:5,
                      transition:"all .15s ease",
                      "--ic-color": isActive ? activeGroup.color : C.muted,
                    }}>
                      <Ic n={meta.icon} s={12}/>
                      {meta.label}
                      {isActive && <span style={{ width:5, height:5, background:activeGroup.color, borderRadius:"50%", flexShrink:0 }}/>}
                    </button>
                  );
                })}
                {activeGroup?.id==="eng_grp" && obrasMenuEngenharia.map(obra => {
                  const isActive = tab==="obras" && obraAberta===obra.id;
                  return (
                    <button key={obra.id} data-active={isActive} onClick={() => irPara("obras", obra.id)} style={{
                      flexShrink:0,
                      background: isActive ? `${activeGroup.color}22` : "transparent",
                      color: isActive ? activeGroup.color : C.muted,
                      border: `1.5px solid ${isActive ? activeGroup.color : C.line}`,
                      borderRadius:999, padding:"5px 14px",
                      fontFamily:"var(--arcd-font-sans)", fontWeight:600, fontSize:"var(--arcd-type-control)",
                      letterSpacing:.5, cursor:"pointer", whiteSpace:"nowrap",
                      display:"flex", alignItems:"center", gap:5,
                      transition:"all .15s ease",
                      "--ic-color": isActive ? activeGroup.color : C.muted,
                    }}>
                      <Ic n="building" s={12}/>
                      {obra.name}
                    </button>
                  );
                })}
              </div>
            )}

            {/* Quatro setores prioritários + Mais. O setor atual permanece
                visível e o restante abre em um painel acessível. */}
            <Suspense fallback={<div className="mobile-primary-nav-loading" aria-hidden="true"/>}>
              <LazyLegacyMobileNavigation
                groups={visibleGroups}
                activeGroupId={activeGroup?.id}
                badges={groupBadge}
                onSelectGroup={goGroup}
                renderIcon={(name,size)=><Ic n={name} s={size}/>}
              />
            </Suspense>
          </div>
        </nav>
        )}
      </div>
      <Toast toast={toast}/>
      {buscaAberta && currentUser && (
        <BuscaGlobal indice={indiceBusca} allowedTabs={allowedTabs} onIr={irPara} onFechar={()=>setBuscaAberta(false)}/>
      )}
      {currentUser && tab!=="tv" && (
        <ChatFlutuante currentUser={currentUser} usuarios={data?.usuarios||[]} showToast={showToast} bottomOffset={isDesktop||tab==="conferencia"?20:`calc(${navHeight+12}px + env(safe-area-inset-bottom))`}/>
      )}
    </>
  );
}
